  ('redwood-california', '12A', 'Redwood National Park', 'United States', 'The tallest trees on earth, a free-entry national park run with three California state parks, Roosevelt elk on the meadows and a ring of lagoon kayaking, oyster boats and bluff-top inns from Crescent City to Eureka', 'future', 'verified', 'mountainValley', 'Northern California & Wine Country', '{"hiking","wildlife","family","senior","romance","parks"}', '{"dramatic","wild","coastal","serene"}', '{}', null, null, '{"safety":{"posture":"book-freely","source":"https://www.gov.uk/foreign-travel-advice/usa","verified":"2026-10-08"},"jewels":[{"name":"Tall Trees Grove","source":"https://www.nps.gov/redw/planyourvisit/hiking-trails-south.htm","accessed":"2026-10-02","si":["hiking","adventure"],"booking_route":"free NPS Tall Trees Trailhead permit, online only (nps.gov/redw/planyourvisit/permits.htm)","commission_status":"none","tier_absent_reason":"not-sold","blurb":"a 4.5-mile round-trip trail, rated moderate-strenuous with an 800-foot elevation gain, off Bald Hills Road; \"Plan 4 hours including 2 hiking hours\"; a free Tall Trees Trailhead permit is \"required year-round\" and can be made up to 24 hours in advance; vehicles must be 21 feet or less and trailers are not allowed"},{"name":"Fern Canyon Loop","source":"https://www.nps.gov/redw/planyourvisit/hiking-trails-south.htm","accessed":"2026-10-02","si":["hiking","family","adventure"],"booking_route":"free Gold Bluffs Beach day-use permit May 15 to September 15 (nps.gov/redw/planyourvisit/permits.htm); state park vehicle day-use fee applies","commission_status":"none","tier_absent_reason":"not-sold","blurb":"a 0.7-mile loop off Davison Road, \"slippery, wet year-round\", with \"30-foot fern-covered walls\"; \"Some of the exquisite ferns...are ancient species whose ancestry can be traced back 325 million years\"; seasonal bridges summer only; free Gold Bluffs Beach day-use permits \"are required May 15th to September 15th\""},{"name":"Lady Bird Johnson Grove","source":"https://www.nps.gov/redw/planyourvisit/hiking-trails-south.htm","accessed":"2026-10-02","si":["senior","family","hiking"],"booking_route":"none needed","commission_status":"none","tier_absent_reason":"not-sold","blurb":"a 1-mile loop, easy and level, off Bald Hills Road about 2 miles from Highway 101, through old-growth redwood forest with rhododendrons and azaleas in spring; \"No parking for RVs and trailers\""},{"name":"Trillium Falls Trail","source":"https://www.nps.gov/redw/planyourvisit/hiking-trails-south.htm","accessed":"2026-10-02","si":["hiking","family"],"booking_route":"none needed","commission_status":"none","tier_absent_reason":"not-sold","blurb":"a 2.5-mile loop, moderate with some steep grades, from the Elk Meadow Day Use Area on Davison Road 3 miles north of Orick; \"The trail leads you through the misty hallways of an ancient redwood home\" to a 10-foot cascade"},{"name":"James Irvine Trail","source":"https://www.nps.gov/redw/planyourvisit/hiking-trails-south.htm","accessed":"2026-10-02","si":["hiking","adventure"],"booking_route":"none needed","commission_status":"none","tier_absent_reason":"not-sold","blurb":"\"The quintessential redwood trail\", 4.2 miles, moderate, from the Prairie Creek Visitor Center through to Fern Canyon; the NPS says to plan \"4-5 hours traveling through the enormous old-growth trees\""},{"name":"Elk Prairie Trail","source":"https://www.nps.gov/redw/planyourvisit/hiking-trails-south.htm","accessed":"2026-10-02","si":["wildlife","hiking","family"],"booking_route":"none needed","commission_status":"none","tier_absent_reason":"not-sold","blurb":"a 2.8-mile moderate trail from Elk Prairie Campground that will \"Meander through one of the most heavily populated Roosevelt elk areas in the parks\""},{"name":"Stout Memorial Grove","source":"https://www.nps.gov/redw/planyourvisit/hiking-trails-north.htm","accessed":"2026-10-02","si":["senior","family","hiking","romance"],"booking_route":"none needed","commission_status":"none","tier_absent_reason":"not-sold","blurb":"a 0.5-mile loop at the east end of Howland Hill Road in Jedediah Smith Redwoods State Park, a \"Majestic example of an ancient coast redwood forest\" on the Smith River floodplain; \"After the initial descent from the parking lot, the trail is easy and flat\"; summer access also from Jedediah Smith Campground; no motor homes or trailers on Howland Hill Road"},{"name":"Grove of Titans","source":"https://home.nps.gov/redw/learn/news/upload/REDW-Visitor-Guide-2026.pdf","accessed":"2026-10-02","si":["hiking","family"],"booking_route":"none needed","commission_status":"none","tier_absent_reason":"not-sold","blurb":"a 1.7-mile out-and-back from the east end of Howland Hill Road, 1 to 1.5 hours with 137 feet of elevation, through old-growth redwoods; NPS Visitor Guide 2026: \"Limited parking, no motor homes or trailers on Howland Hill Road\""},{"name":"Boy Scout Tree Trail","source":"https://www.nps.gov/redw/planyourvisit/hiking-trails-north.htm","accessed":"2026-10-02","si":["hiking","adventure"],"booking_route":"none needed","commission_status":"none","tier_absent_reason":"not-sold","blurb":"5.5 miles out and back from the west end of Howland Hill Road, 3-4 hours with 900 feet of elevation, to Fern Falls and the Boy Scout Tree; \"Moderate, some steep grades and switchbacks\"; the NPS warns of \"Many vehicle break-ins at this trailhead\""},{"name":"Simpson-Reed Trail","source":"https://www.nps.gov/redw/planyourvisit/hiking-trails-north.htm","accessed":"2026-10-02","si":["senior","family"],"booking_route":"none needed","commission_status":"none","tier_absent_reason":"not-sold","blurb":"a 1-mile loop off Walker Road from US 199 in Jedediah Smith Redwoods State Park, \"Easy, level (Rated: barrier free)\" through old-growth redwoods with waysides; the 2026 Visitor Guide gives 0.8 mile and 50 feet of elevation; no motor homes or trailers on Walker Road"},{"name":"Damnation Creek Trail","source":"https://www.nps.gov/redw/planyourvisit/hiking-trails-north.htm","accessed":"2026-10-02","si":["hiking","adventure","ocean"],"booking_route":"none needed","commission_status":"none","tier_absent_reason":"not-sold","blurb":"2.2 miles one-way from milepost 16.0 on Highway 101 in Del Norte Coast Redwoods State Park down to the ocean; \"Strenuous, numerous steep grades and switchbacks. Trail drops 1,000 feet (16 percent grade)\"; NPS: \"Many vehicle break-ins at this trailhead\""},{"name":"Yurok Loop Trail and Lagoon Creek","source":"https://www.nps.gov/redw/planyourvisit/hiking-trails-north.htm","accessed":"2026-10-02","si":["family","ocean","culture","hiking"],"booking_route":"none needed","commission_status":"none","tier_absent_reason":"not-sold","blurb":"a 1-mile loop (1.25 miles in the 2026 Visitor Guide) from the Lagoon Creek picnic area on US 101, beach flowers and Lagoon Creek; the guide adds: \"From the loop, head south on the Coastal Trail 4 mi to reach the Klamath River Overlook\""},{"name":"Big Tree Wayside and Circle Trail","source":"https://home.nps.gov/redw/learn/news/upload/REDW-Visitor-Guide-2026.pdf","accessed":"2026-10-02","si":["senior","family"],"booking_route":"none needed","commission_status":"none","tier_absent_reason":"not-sold","blurb":"a 0.5-mile loop, 15 to 40 minutes with 22 feet of elevation, off the Newton B. Drury Parkway to the Big Tree; \"Connect with either the Cathedral Trees Trail or the Foothill Trail for a longer hike\""},{"name":"Revelation Trail, Prairie Creek Visitor Center","source":"https://home.nps.gov/redw/learn/news/upload/REDW-Visitor-Guide-2026.pdf","accessed":"2026-10-02","si":["senior","family"],"booking_route":"none needed","commission_status":"none","tier_absent_reason":"not-sold","blurb":"a 0.3-mile loop, 15 to 45 minutes with 9 feet of elevation, through old-growth redwoods, \"Developed specifically for the visually impaired\"; the visitor centre sits 6 miles north of Orick on the Newton B. Drury Scenic Parkway"},{"name":"Howland Hill Road","source":"https://home.nps.gov/redw/learn/news/upload/REDW-Visitor-Guide-2026.pdf","accessed":"2026-10-02","si":["senior","adventure","romance","family"],"booking_route":"none needed","commission_status":"none","tier_absent_reason":"not-sold","blurb":"a scenic drive of 10 miles one-way, about 45 minutes, that will \"Follow a winding dirt road through old-growth redwoods in Jedediah Smith Redwoods State Park\"; mostly unpaved, two-way and narrow; motor homes, RVs and trailers not advised; it reaches Stout Grove, Grove of Titans and Boy Scout Tree"},{"name":"Newton B. Drury Scenic Parkway","source":"https://home.nps.gov/redw/learn/news/upload/REDW-Visitor-Guide-2026.pdf","accessed":"2026-10-02","si":["senior","family","wildlife","romance"],"booking_route":"none needed","commission_status":"none","tier_absent_reason":"not-sold","blurb":"\"A not-to-be-missed alternative to US 101\" that \"passes through the heart of the old-growth redwood forest in Prairie Creek Redwoods State Park\": paved, two-way, 10 miles one-way, about 30 minutes, no commercial vehicles; home to the Prairie Creek Visitor Center and Big Tree Wayside"},{"name":"Coastal Drive Loop and High Bluff Overlook","source":"https://home.nps.gov/redw/learn/news/upload/REDW-Visitor-Guide-2026.pdf","accessed":"2026-10-02","si":["ocean","culture","wildlife","senior"],"booking_route":"none needed","commission_status":"none","tier_absent_reason":"not-sold","blurb":"a 9-mile loop, about 45 minutes, mostly paved with a one-way northbound section; \"This narrow road with steep grade and sharp curves offers panoramic views of the Pacific Ocean and Klamath River Estuary\", passing High Bluff Overlook and a World War II radar station; motor homes, RVs and trailers prohibited"},{"name":"Klamath River Overlook","source":"https://home.nps.gov/redw/learn/news/upload/REDW-Visitor-Guide-2026.pdf","accessed":"2026-10-02","si":["ocean","wildlife","culture","romance"],"booking_route":"none needed","commission_status":"none","tier_absent_reason":"not-sold","blurb":"an overlook at the end of Requa Road above the mouth of the Klamath River, reached also by the Coastal Trail 4 miles south of the Yurok Loop; the Visitor Guide notes \"Requa Road motor homes and trailers not advised\" and that lands within one mile of each side of the Klamath River for 43 miles upstream compose the Yurok Reservation"},{"name":"Jedediah Smith Campground","source":"https://www.nps.gov/redw/cabins.htm","accessed":"2026-10-02","si":["family","group","hiking"],"booking_route":"ReserveCalifornia.com or 1-800-444-7275, at least 48 hours and up to 6 months ahead","commission_status":"unknown","tier_absent_reason":"not-sold","blurb":"a year-round state park campground on US 199, 9 miles northeast of Crescent City, beside the Hiouchi Visitor Center and a summer-only campground store; RVs to 25 feet, trailers to 21 feet; one of two campgrounds with four ADA-accessible cabins that sleep six with \"electricity; heaters and lights\" but no kitchen or bathroom; $35 a night for developed sites"},{"name":"Mill Creek Campground","source":"https://home.nps.gov/redw/learn/news/upload/REDW-Visitor-Guide-2026.pdf","accessed":"2026-10-02","si":["family","group"],"booking_route":"ReserveCalifornia.com or 1-800-444-7275, at least 48 hours and up to 6 months ahead","commission_status":"unknown","tier_absent_reason":"not-sold","blurb":"the spring-to-fall campground in Del Norte Coast Redwoods State Park, RVs to 28 feet and trailers to 24 feet, $35 a night for developed sites"},{"name":"Elk Prairie Campground","source":"https://www.nps.gov/redw/cabins.htm","accessed":"2026-10-02","si":["wildlife","family","group"],"booking_route":"ReserveCalifornia.com or 1-800-444-7275, at least 48 hours and up to 6 months ahead","commission_status":"unknown","tier_absent_reason":"not-sold","blurb":"a year-round campground in Prairie Creek Redwoods State Park, RVs to 27 feet and trailers to 24 feet, with four ADA-accessible bunk cabins and park wifi at the campground kiosk; the Elk Prairie Trail starts here through \"one of the most heavily populated Roosevelt elk areas in the parks\""},{"name":"Gold Bluffs Beach Campground","source":"https://home.nps.gov/redw/learn/news/upload/REDW-Visitor-Guide-2026.pdf","accessed":"2026-10-02","si":["ocean","wildlife","family","adventure"],"booking_route":"ReserveCalifornia.com or 1-800-444-7275; summer day-use reservation also required for Gold Bluffs Beach","commission_status":"unknown","tier_absent_reason":"not-sold","blurb":"a year-round beachfront campground off Davison Road in Prairie Creek Redwoods State Park, RVs to 24 feet and trailers prohibited, with a hiker/biker-only backcountry site inside it (\"$5 per person, per night\"); Roosevelt elk are frequently seen at Gold Bluffs Beach; NPS: \"Sneaker waves are difficult to spot, and within 30-seconds they will run hundreds of feet up the beach slope\""},{"name":"Redwood Creek Trail and the backcountry camps","source":"https://home.nps.gov/redw/learn/news/upload/REDW-Visitor-Guide-2026.pdf","accessed":"2026-10-02","si":["expedition","hiking","adventure"],"booking_route":"free backcountry permit online, at least 48 hours ahead; \"No phone reservations are made for backcountry permits\" (nps.gov/redw/planyourvisit/permits.htm)","commission_status":"none","tier_absent_reason":"not-sold","blurb":"8 miles to Tall Trees Grove, moderate to strenuous, from off Bald Hills Road; \"Redwood Creek runs high and fast during the winter. Foot bridges across the creek have been removed until the summer season\"; designated backcountry camps include DeMartin (10 sites), Flint Ridge (8), Little Bald Hills (5), 44 Camp (4), Elam Camp (3) and dispersed Redwood Creek gravel bars; free online permits only"},{"name":"Enderts Beach and Crescent Beach Overlook","source":"https://www.nps.gov/redw/planyourvisit/hiking-trails-north.htm","accessed":"2026-10-02","si":["ocean","hiking","family","wildlife"],"booking_route":"none needed","commission_status":"none","tier_absent_reason":"not-sold","blurb":"the Last Chance section of the Coastal Trail, 0.6 mile one-way and \"Moderate, some steep grades\", from the end of Enderts Beach Road south of Crescent City; the Visitor Guide lists Roosevelt elk on Enderts Beach Road and warns \"powerful ''sneaker'' waves can occur at any time\""},{"name":"Roosevelt elk viewing","source":"https://home.nps.gov/redw/learn/news/upload/REDW-Visitor-Guide-2026.pdf","accessed":"2026-10-02","si":["wildlife","family","senior"],"booking_route":"none needed","commission_status":"none","tier_absent_reason":"not-sold","blurb":"elk \"are frequently seen by adoring visitors near Elk Prairie, Elk Meadow, Gold Bluffs Beach, Bald Hills Road, and Enderts Beach Road\"; the NPS: \"elk can be agressive, especially the males during the fall elk rut and the females during spring calving season. Stay back at least 75 ft (25 m)\""},{"name":"Visitor centres, Junior Ranger and ranger programmes","source":"https://home.nps.gov/redw/learn/news/upload/REDW-Visitor-Guide-2026.pdf","accessed":"2026-10-02","si":["family","culture","senior"],"booking_route":"none needed","commission_status":"none","tier_absent_reason":"not-sold","blurb":"five visitor and information centres - Crescent City Bookstore (1111 Second Street), Hiouchi, Prairie Creek, Kuchel (2 miles south of Orick on US 101) and Chah-pekw O'' Ket''-toh \"Stone Lagoon\" - with maps, Junior Ranger books, passport stamps, and a Bark Ranger programme for pets; ranger programme calendar by QR code or at a visitor centre; park stores run by the Redwood Parks Conservancy"},{"name":"Trees of Mystery, Klamath","source":"https://www.treesofmystery.net/","accessed":"2026-10-02","si":["family","adventure","culture","senior"],"booking_route":"phone/email (1-800-638-3389, tofm@treesofmystery.net); no online engine seen on the homepage","commission_status":"unknown","tier_absent_reason":"not-sold","blurb":"a roadside attraction at 15500 US-101, Klamath, operating since 1946: the SkyTrail, where you \"Glide through the forest in enclosed gondolas\", the Redwood Canopy Trail, old-growth trails, the Paul Bunyan and Babe statues, and the End of the Trail Museum, \"One of the largest private collections of artifacts\"; Blue Ox Cafe and Motel Trees on site"},{"name":"Historic Requa Inn, Klamath River mouth","source":"https://www.requainn.com/","accessed":"2026-10-02","si":["romance","culture","senior","culinary"],"booking_route":"ResNexus, or 707-482-1425","commission_status":"unknown","tier_absent_reason":"not-sold","blurb":"\"Built in 1914, the plain, almost utilitarian arts and crafts Inn\" where \"the river meets the ocean\" at Requa; every room different, many with river views, some with claw-foot tubs; seasonal breakfast; the inn states the four redwood parks \"are all within a 40-minute radius of the Inn\""},{"name":"Kayak Trinidad","source":"https://www.kayaktrinidad.com/","accessed":"2026-10-02","si":["adventure","ocean","wildlife","family"],"booking_route":"phone/email ((707) 329-0085, reservations@kayaktrinidad.com); no engine seen on the homepage","commission_status":"unknown","tier_absent_reason":"not-sold","blurb":"\"Coastal Northern California''s Premiere Paddlesports Outfitters\", over 25 years, at Scenic Drive and Main Street in Trinidad, running a Trinidad Bay \"Whales & Wildlife\" kayak tour, a Big Lagoon Wildlife Tour and Sunday Social Paddles, \"for all levels of paddler\""},{"name":"Elk Meadow Cabins, Orick","source":"https://www.visitredwoods.com/listing/elk-meadow-cabins/679/","accessed":"2026-10-02","si":["family","wildlife","group","romance"],"booking_route":"own site elkmeadowcabins.com or (707) 302-8393 (homepage did not load this session)","commission_status":"unknown","tier_absent_reason":"not-sold","blurb":"vacation rental cabins on a 27-acre meadow at 7 Valley Green Camp Rd, about 2 miles north of Orick off Highway 101, where Roosevelt elk graze on the property; each with a \"fully stocked kitchen with cooking & eating utensils\", dishwasher, laundry and satellite TV; weddings take a minimum of 6 cabins for 2+ nights"},{"name":"SeaQuake Brewing, Crescent City","source":"https://www.seaquakebrewing.com/","accessed":"2026-10-02","si":["culinary","group","family"],"booking_route":"phone (707) 465-4444","commission_status":"unknown","tier_absent_reason":"not-sold","blurb":"a brewery and restaurant at 400 Front St, Crescent City, pouring year-round and seasonal craft beers and kombucha alongside \"brick oven pizzas, local grass-fed burgers, locally caught fish dishes, our famous cheese curds\""},{"name":"Mystic Forest Campground, Klamath","source":"https://www.hipcamp.com/discover/california/mystic-forest-campground","accessed":"2026-10-02","si":["family","group"],"booking_route":"Hipcamp (instant book)","commission_status":"unknown","tier_absent_reason":"not-sold","blurb":"a small family-run campground on 50 acres of forest \"sprinkled with redwood trees\" between Klamath and Crescent City, with 15 tent-only sites among 23 on Hipcamp, plus \"restrooms, showers, a game room, a mini golf course, horseshoes, and a half-mile trail\"; 98% recommended across 875 reviews"},{"name":"The Fairy Forest, Trinidad","source":"https://www.hipcamp.com/en-US/land/california-the-fairy-forest-2ejhqp18","accessed":"2026-10-02","si":["glamping","romance"],"booking_route":"Hipcamp","commission_status":"unknown","tier_absent_reason":"not-sold","blurb":"a single 12x14 ft canvas glamping tent for up to four on 4 acres of old-growth and roughly 120-year-old redwoods a mile from Trinidad, with a queen bed, heating, an outdoor heated shower, fire pit and greenhouse seating; no potable water; camped on since the 1950s; 95% recommended across 278 reviews"},{"name":"Ravens Roost, Crescent City","source":"https://www.hipcamp.com/en-US/land/california-ravens-roost-2-nelhrv25","accessed":"2026-10-02","si":["glamping","romance"],"booking_route":"Hipcamp","commission_status":"unknown","tier_absent_reason":"not-sold","blurb":"a bell-tent glamping site for up to three with a \"Vintage horse trailer that has been converted into a charming bathhouse\", fire pit, hammock and swinging sofa, heater, mini fridge, Keurig and WiFi; Star Host, 100% recommended (13 reviews)"},{"name":"Redwood Cathedral Treehouse (Redwood Retreat), Crescent City","source":"https://www.hipcamp.com/en-US/land/california-redwood-retreat-y0zhzdzq","accessed":"2026-10-02","si":["glamping","adventure","romance"],"booking_route":"Hipcamp","commission_status":"unknown","tier_absent_reason":"not-sold","blurb":"a two-story treehouse platform 22 feet above the forest floor inside a \"cathedral tree\", with an 8-foot geodesic dome, composting toilet and a dumbwaiter for gear; bring your own water, flashlights and bedding; 97% recommended across 318 reviews"},{"name":"Redwood Creek Buckarettes horseback rides, Orick","source":"https://www.visitredwoods.com/listing/redwood-creek-buckarettes-horseback-rides/407/","accessed":"2026-10-02","si":["adventure","family","group"],"booking_route":"phone (707) 499-2943; redwoodcreekbuckarettes.com (not fetched)","commission_status":"unknown","tier_absent_reason":"not-sold","blurb":"guided rides into Redwood National Park from the Orick Rodeo Grounds, daily May through November: the 1.5-hour Goose Pen Ride (\"get your picture taken on your horse inside one of these giant wonders\"), the 2-hour Majestic Ride to \"a majestic grove of untouched old growth redwoods\", and a 4-hour Picnic Ride with lunch"},{"name":"Turtle Rocks Oceanfront Inn, Trinidad","source":"https://www.visitredwoods.com/listing/turtle-rocks-oceanfront-inn/461/","accessed":"2026-10-02","si":["romance","ocean","senior","wildlife"],"booking_route":"own site turtlerocksinn.com or (707) 677-3707 (engine not checked)","commission_status":"unknown","tier_absent_reason":"not-sold","blurb":"an inn on three oceanfront acres in a wind-protected cove south of Sue-Meg State Park, rooms averaging 500 square feet, each with a \"private glass-paneled deck overlooking the Pacific Ocean\" and the offshore Turtle Rocks sea stacks; daily gourmet breakfast buffet 8:30-10:00"},{"name":"Lost Whale Bed & Breakfast Inn, Trinidad","source":"https://www.visitredwoods.com/listing/lost-whale-inn/306/","accessed":"2026-10-02","si":["romance","wellness","ocean","culinary","family"],"booking_route":"own site lostwhaleinn.com or (707) 677-3425 (engine not checked)","commission_status":"unknown","tier_absent_reason":"not-sold","blurb":"a bluff-top inn above Abalone Cove that Sunset Magazine called \"one of the ten most romantic inns in the country\", with a private trail to two miles of secluded beaches, tidepools, sea otters and a sea lion colony, a 24-hour ocean-view hot tub, in-room spa services, and breakfasts and afternoon wine receptions using the inn''s own produce; children welcome; two-night minimum June 15 to September 15"},{"name":"Sunset Restaurant, Trinidad","source":"https://www.visitredwoods.com/listing/sunset-restaurant/451/","accessed":"2026-10-02","si":["culinary","romance","ocean"],"booking_route":"phone (707) 825-2770","commission_status":"unknown","tier_absent_reason":"not-sold","blurb":"a restaurant at Cher-Ae Heights Casino, 27 Scenic Drive, perched above Trinidad Bay with \"brilliant views of the Pacific shoreline\"; seafood-led with whole steamed ruby red trout, spicy prawn and sausage penne and smokehouse ribs, and a bar for craft cocktails and house-infused spirits"},{"name":"Samoa Cookhouse, Samoa (Eureka)","source":"https://www.visitredwoods.com/listing/samoa-cookhouse/444/","accessed":"2026-10-02","si":["culinary","culture","family","group"],"booking_route":"walk-in; (707) 442-1659","commission_status":"unknown","tier_absent_reason":"not-sold","blurb":"\"the last surviving cookhouse of the West\", serving lumber-camp meals \"since 1890\": \"Your food is brought to the table in large bowls and platters, allowing you to help yourself and pass it around\", with a complimentary museum of logging relics and private rooms for groups up to 160; 5 minutes from Eureka over the Samoa Bridge. STATUS TO CONFIRM: the Visit Redwoods listing carries a note \"Temporarily closed for renovations as of August 2023\", while a search result from samoacookhouse.net showed Wednesday-Sunday hours"},{"name":"Humboldt Bay Oyster Tours and Humboldt Bay Provisions, Eureka","source":"https://humboldtbayoystertours.com/","accessed":"2026-10-02","si":["culinary","ocean","group"],"booking_route":"FareHarbor (fareharbor.com/humboldtbayoystertours/items/35313/); 707-836-3168","commission_status":"unknown","tier_absent_reason":"not-sold","blurb":"a \"4 Hour Boat Tour and Tasting\" for up to six, departing 11 AM from Humboldt Bay Provisions at 205 G St in Old Town Eureka, touring the bay''s oyster aquaculture by motorboat, with \"12 oysters prepared for them at Humboldt Bay Provisions\" per guest; the tasting room and oyster bar was \"established in 2012\""},{"name":"Chart Room Restaurant, Crescent City Harbor","source":"https://ccharbor2.specialdistrict.org/faq","accessed":"2026-10-02","si":["culinary","ocean","family"],"booking_route":"walk-in; (707) 464-5993","commission_status":"unknown","tier_absent_reason":"not-sold","blurb":"named by the Crescent City Harbor District as \"a beloved waterfront seafood spot known for its hearty clam chowder\", at 130 Anchor Way on the harbor, where the district lists sea lion and seal viewing, sport fishing and whale watching"},{"name":"Schmidt''s House of Jambalaya, Crescent City Harbor","source":"https://ccharbor2.specialdistrict.org/faq","accessed":"2026-10-02","si":["culinary","group"],"booking_route":"phone (707) 465-1465","commission_status":"unknown","tier_absent_reason":"not-sold","blurb":"a \"New Orleans-style bistro that offers a delightful mix of Cajun and Creole classics\" at 110 Anchor Way on Crescent City Harbor (Harbor District listing)"},{"name":"Redwood Harbor Village RV and Bayside RV, Crescent City Harbor","source":"https://ccharbor2.specialdistrict.org/faq","accessed":"2026-10-02","si":["family","ocean"],"booking_route":"not observed (operator sites not fetched)","commission_status":"unknown","tier_absent_reason":"not-sold","blurb":"the two RV parks the Crescent City Harbor District lists at the harbor, beside the California Coastal Trail for walking and biking and the harbor''s free Wi-Fi"}],"faq":[{"q":"Does Redwood National Park charge an entrance fee?","a":"No. The NPS states the park is free to visit and has no entrance stations. California State Parks charge day-use fees, cash only, at Jedediah Smith Day-Use Area, Gold Bluffs Beach/Fern Canyon and Elk Prairie Picnic Area; federal and California State Park pass holders do not pay them.","source":"https://www.nps.gov/redw/planyourvisit/fees.htm","accessed":"2026-10-02"},{"q":"Do I need a permit for Fern Canyon?","a":"From May 15 to September 15, yes. The NPS requires a free Gold Bluffs Beach day-use permit, which also covers Fern Canyon trailhead parking, booked online only.","source":"https://www.nps.gov/redw/planyourvisit/permits.htm","accessed":"2026-10-02"},{"q":"How do I visit Tall Trees Grove?","a":"With a free Tall Trees Trailhead permit, required year-round and booked online. The trail is 4.5 miles round trip with an 800-foot elevation gain, off Bald Hills Road; the NPS says to plan 4 hours.","source":"https://www.nps.gov/redw/planyourvisit/hiking-trails-south.htm","accessed":"2026-10-02"},{"q":"Where can I see Roosevelt elk?","a":"The NPS names Elk Prairie, Elk Meadow, Gold Bluffs Beach, Bald Hills Road and Enderts Beach Road, and asks visitors to stay back at least 75 feet, more in the fall rut and spring calving season.","source":"https://home.nps.gov/redw/learn/news/upload/REDW-Visitor-Guide-2026.pdf","accessed":"2026-10-02"},{"q":"Are there cabins in the park?","a":"Yes, eight ADA-accessible cabins, four at Elk Prairie and four at Jedediah Smith campgrounds. Each sleeps six with electricity, heat and lights but no kitchen or bathroom; bring your own bedding. Book on ReserveCalifornia.","source":"https://www.nps.gov/redw/cabins.htm","accessed":"2026-10-02"},{"q":"What is the weather like?","a":"The NPS gives coastal temperatures of mid-40s to low-60s F year-round, with most of the 60-80 inches of annual rain falling October to April and summer fog along the coast.","source":"https://www.nps.gov/redw/planyourvisit/weather.htm","accessed":"2026-10-02"}],"seo":{"meta_title":"Redwood National Park: Tall Trees, Fern Canyon, Elk & Where to Stay | TravelWell","meta_description":"Tall Trees and Fern Canyon permits, Roosevelt elk, free entry, park campgrounds and cabins, and where to stay and eat from Crescent City to Trinidad and Eureka.","slug":"redwood-national-park-california","primary_keyword":"Redwood National Park","jsonld_type":"TouristDestination"},"hero":{"query":"Redwood National Park, California"}}'::jsonb, 96),
  ('lassen-volcanic-california', '12A', 'Lassen Volcanic National Park', 'United States', 'Boiling mud, Lassen Peak and Cinder Cone', 'future', 'verified', 'mountainValley', 'Northern California & Wine Country', '{"hiking","adventure","family","group","senior","parks"}', '{"dramatic","rugged","alpine","wild"}', '{}', null, null, '{"safety":{"posture":"book-freely","source":"https://www.gov.uk/foreign-travel-advice/usa","verified":"2026-10-08"},"jewels":[{"name":"Bumpass Hell Trail","source":"https://www.nps.gov/thingstodo/hikebumpasshell.htm","accessed":"2026-10-03","si":["hiking","family","adventure"],"booking_route":"none needed - park trail, covered by the entrance fee","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":1,"blurb":"\"Bumpass Hell Trail provides access to the largest hydrothermal area in the park.\" 3 miles round trip, about 2 hours; \"the trail drops 300 feet into the basin where a boardwalk provides an up-close view of the hydrothermal features.\" Season \"Approximately late July through October\". \"Stay on established trails and boardwalks in/around the basin.\""},{"name":"Lassen Peak Trail","source":"https://www.nps.gov/thingstodo/hikelassenpeak.htm","accessed":"2026-10-03","si":["hiking","adventure"],"booking_route":"none needed - park trail","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":2,"blurb":"\"Round-Trip Distance: 5 miles (8 km)\", start 8,500 ft, gain 1,957 ft, 4-5 hours, summer and fall; the route \"climbs through twisted mountain hemlock and whitebark pine trees on sand-like cinders\" then \"steepens into series of switchbacks along a rocky ridge to the summit.\""},{"name":"Sulphur Works","source":"https://www.nps.gov/thingstodo/visitsulphurworks.htm","accessed":"2026-10-03","si":["senior","family","hiking"],"booking_route":"none needed - roadside stop on the park highway","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":3,"blurb":"\"Sulphur Works is the easiest of the park''s hydrothermal areas to access. This hydrothermal area is an otherworldly place of vibrant colors, pungent scents, and shifting ground.\" \"The sidewalk to Sulphur Works is paved and accessible to wheelchairs.\" Reached by vehicle in summer and fall only."},{"name":"Cinder Cone Trail","source":"https://www.nps.gov/places/cinder_cone.htm","accessed":"2026-10-03","si":["hiking","adventure"],"booking_route":"none needed - park trail","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":4,"blurb":"\"Hike to the base or summit of the dramatic Cinder Cone volcano via this popular trail in the Butte Lake Area\": 2.4 miles to the base, 4 miles round trip to the summit, 846 ft of gain from 6,061 to 6,907 ft, past \"the Fantastic Lava Beds and the colorful Painted Dunes\"; open \"Approximately June through November\"."},{"name":"Lassen Park Highway scenic drive","source":"https://www.nps.gov/lavo/planyourvisit/things2do.htm","accessed":"2026-10-03","si":["motoring","senior","family"],"booking_route":"none needed - private vehicle entrance fee at the gate","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities","move"],"draw_rank":5,"blurb":"\"Take the one-hour drive along the 30-mile park highway.\" The NPS notes many sights \"can be seen from the main park road (Highway 89).\" Closed to through traffic by snow approximately November through April."},{"name":"Manzanita Lake Loop","source":"https://www.nps.gov/lavo/planyourvisit/hiking_lassen_park.htm","accessed":"2026-10-03","si":["family","hiking","wildlife","senior"],"booking_route":"none needed - park trail","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":6,"blurb":"\"Enjoy scenic views and wildlife watching on this 1.7-mile loop.\" Manzanita Lake Campground beside it is \"within walking distance of the scenic Manzanita Lake, a popular fishing and family destination\" with \"impressive views of Lassen Peak\"."},{"name":"Junior Ranger programme","source":"https://www.nps.gov/lavo/learn/kidsyouth/beajuniorranger.htm","accessed":"2026-10-03","si":["family","hiking"],"booking_route":"none needed - booklet at the visitor centers","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":7,"blurb":"\"The activities in the Junior Ranger booklet are best-suited to kids age 5 to 12.\" \"Kids pick up a Junior Ranger Activity Booklet at the Loomis Museum (summer only) or Kohm Yah-mah-nee Visitor Center\" and \"receive a Lassen Volcanic National Park Junior Ranger badge\" once a ranger reviews it."},{"name":"Kohm Yah-mah-nee Visitor Center","source":"https://www.nps.gov/lavo/planyourvisit/hours.htm","accessed":"2026-10-03","si":["senior","family"],"booking_route":"none needed - free with park entry","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":8,"blurb":"\"Open 7 days/week\", \"9:30 am - 4:30 pm\", year-round; \"The visitor center is fully accessible with tactile exhibits including a relief map of the park\"."},{"name":"Loomis Museum","source":"https://www.nps.gov/lavo/planyourvisit/hours.htm","accessed":"2026-10-03","si":["culture","family","senior"],"booking_route":"none needed - free with park entry","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":9,"blurb":"\"2026 season - May 21 - November 2 Thursdays - Mondays (closed Tuesdays and Wednesdays)\", \"9:30 am - 4:30 pm\"; one of the two places to pick up the Junior Ranger booklet in summer."},{"name":"Devastated Area Interpretive Trail","source":"https://www.nps.gov/lavo/planyourvisit/hiking_lassen_park.htm","accessed":"2026-10-03","si":["senior","family","hiking"],"booking_route":"none needed - park trail","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":10,"blurb":"\"Discover the history of the Devastated Area on this short walk with trailside signs.\" \"Accessible parking spaces and vault toilets are available at the trailhead.\""},{"name":"Lily Pond Trail","source":"https://www.nps.gov/lavo/planyourvisit/hiking_lassen_park.htm","accessed":"2026-10-03","si":["family","hiking","wildlife"],"booking_route":"none needed - park trail","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":11,"blurb":"\"This half-mile, self-led interpretive walk explores the rich diversity of plant and animal life in this unique volcanic landscape.\""},{"name":"Juniper Lake","source":"https://www.nps.gov/lavo/planyourvisit/placestogo.htm","accessed":"2026-10-03","si":["adventure","hiking"],"booking_route":"none needed - outlying park area","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":12,"blurb":"The NPS calls it the \"largest lake in the park\" with \"crystal clear snow-fed waters\"; its 18-site campground is listed as closed for maintenance."},{"name":"Fishing in Lassen''s lakes and streams","source":"https://www.nps.gov/lavo/planyourvisit/things2do.htm","accessed":"2026-10-03","si":["adventure","family"],"booking_route":"none needed in the park (licence rules not read in this build)","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":13,"blurb":"\"Numerous lakes and streams provide plentiful opportunities for fishing.\""},{"name":"Winter snowshoeing and skiing","source":"https://www.nps.gov/lavo/planyourvisit/winter.htm","accessed":"2026-10-03","si":["ski","adventure","family"],"booking_route":"none needed - winter entrance fee only; backcountry camping needs a wilderness permit","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":14,"blurb":"When Highway 89 closes \"when snow settles in\", the park offers \"snowshoeing and cross-country skiing and areas for sledding and snowplay\" and, for the experienced, \"backcountry ski and snowboard\". \"Self-contained vehicle camping is allowed\" at the Southwest Parking Area."},{"name":"Ranger-led programmes","source":"https://www.nps.gov/lavo/planyourvisit/things2do.htm","accessed":"2026-10-03","si":["family","senior","group"],"booking_route":"none needed - programme calendar on nps.gov (not read)","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":15,"blurb":"\"Learn about Lassen with a ranger. A variety of programs are typically offered late-May through September.\" Summer adds \"field seminars\"."},{"name":"Manzanita Lake Campground","source":"https://www.recreation.gov/api/camps/campgrounds/234039","accessed":"2026-10-03","si":["family","hiking","motoring"],"booking_route":"Recreation.gov or (877) 444-6777","commission_status":"none","commission":"venue","tier_absent_reason":"not-established","wells":["stay"],"draw_rank":16,"blurb":"\"Manzanita Lake Campground (elevation 5,900 ft.) is the largest campground in Lassen Volcanic National Park\" - 179 sites, $26 full service / $15 dry camping; every site has \"one bear-resistant storage locker\". Stay limit \"14 nights\". Reservations via recreation.gov or (877) 444-6777."},{"name":"Manzanita Lake Group Campground","source":"https://www.recreation.gov/api/camps/campgrounds/233372","accessed":"2026-10-03","si":["group","family"],"booking_route":"Recreation.gov","commission_status":"none","commission":"venue","tier_absent_reason":"not-established","wells":["stay"],"draw_rank":17,"blurb":"\"located at the west end of Loop B in Manzanita Lake Campground, the largest campground in Lassen Volcanic National Park\"; \"Campsite capacity is 15 persons per site and a maximum of 4 vehicles.\""},{"name":"Summit Lake, Butte Lake and Warner Valley campgrounds","source":"https://www.nps.gov/lavo/planyourvisit/camping-in-campgrounds.htm","accessed":"2026-10-03","si":["hiking","family","adventure"],"booking_route":"Recreation.gov or (877) 444-6777","commission_status":"none","commission":"venue","tier_absent_reason":"not-established","wells":["stay"],"draw_rank":18,"blurb":"Summit Lake North 46 sites ($24), Summit Lake South 48 sites ($22 / $15 dry), Butte Lake 101 sites ($22 / $15 dry), Warner Valley 17 sites ($21), Southwest Walk-In 21 sites ($16). \"Reservations are required for all campgrounds except Juniper Lake and Southwest Walk-in.\""},{"name":"Manzanita Lake Camping Cabins","source":"https://www.recreation.gov/api/camps/campgrounds/233257","accessed":"2026-10-03","si":["family","glamping","group"],"booking_route":"Recreation.gov","commission_status":"none","commission":"hotel","tier_absent_reason":"not-established","wells":["stay"],"draw_rank":19,"blurb":"\"Situated near the northwest entrance to the park, the rustic Manzanita Lake Camping Cabins\" come as \"a one-room cabin that sleeps three\", \"a two-room cabin that sleeps six\" and \"a one-room bunkhouse that sleeps up to eight people\"; no electricity, running water or linens; open mid-May through mid-October."},{"name":"Drakesbad Guest Ranch","source":"http://lassenlodging.com/drakesbad/","accessed":"2026-10-03","si":["romance","family","hiking","senior"],"booking_route":"concessioner by email / lassenlodging.com","commission_status":"unknown","commission":"hotel","tier_absent_reason":"not-established","wells":["stay","eat","activities"],"draw_rank":20,"blurb":"\"a secluded getaway lodge at the southeast end of Lassen Volcanic National Park, featuring 19 traditional lodge and bungalow units\"; season \"June 12th - October 12th\"; two-night minimum; \"All meals are included\"; guests go \"hiking, horseback riding, swimming, fishing\" with rides to Terminal Geyser, Devils Kitchen and Boiling Springs Lake. Operated by Snow Mountain LLC, an NPS-authorized concessioner."},{"name":"Backcountry camping by wilderness permit","source":"https://www.nps.gov/lavo/planyourvisit/wilderness-permit-information.htm","accessed":"2026-10-03","si":["adventure","hiking"],"booking_route":"Recreation.gov wilderness permit","commission_status":"none","commission":"venue","tier_absent_reason":"does-not-compete","wells":["activities"],"draw_rank":21,"blurb":"\"Wilderness permits for backcountry camping must be obtained prior to your visit to the park\" through Recreation.gov; \"Permits can be reserved a maximum of 90 days prior to the start date\"; \"$6 per permit non-refundable Recreation.gov administration fee\" plus \"$5 per-trip, per-person fee (16 years and older)\"."},{"name":"Bear canister for the backcountry","source":"https://www.nps.gov/lavo/planyourvisit/wilderness-permit-information.htm","accessed":"2026-10-03","si":["hiking","adventure"],"booking_route":"affiliate referral to BearVault (AvantLink)","commission_status":"commissioned","commission":"affiliate","tier_absent_reason":"does-not-compete","commission_pct_low":8,"commission_pct_high":8,"commission_basis":"published","wells":["gear"],"draw_rank":22,"blurb":"NPS: \"All food, trash, toiletries, and other scented items\" must be stored in approved bear-resistant containers; \"Hanging food is not permitted.\" Canisters are mandatory \"from April 16 - November 30\" and go \"100 feet (or 70 big steps) from both your tent and cooking area.\""},{"name":"Water, sun cover and layers for Lassen Peak","source":"https://www.nps.gov/thingstodo/hikelassenpeak.htm","accessed":"2026-10-03","si":["hiking","adventure","ski"],"booking_route":"affiliate referral to rei.com (AvantLink)","commission_status":"commissioned","commission":"affiliate","tier_absent_reason":"does-not-compete","commission_pct_low":5,"commission_pct_high":5,"commission_basis":"published","wells":["gear"],"draw_rank":23,"blurb":"NPS: \"Carry plenty of water, take breaks often\" and \"Carry extra layers for warmth\"; \"Sun Exposure is considerable on Lassen Peak Trail. Tree shade may be found in the first mile after which limited shade is available.\" For winter: \"layers, waterproof gear and outerwear, and sun protection\"."},{"name":"Footwear and trekking poles for Bumpass Hell","source":"https://www.nps.gov/thingstodo/hikebumpasshell.htm","accessed":"2026-10-03","si":["hiking","senior","family"],"booking_route":"affiliate referral to LEKI USA (AvantLink)","commission_status":"commissioned","commission":"affiliate","tier_absent_reason":"does-not-compete","commission_pct_low":10,"commission_pct_high":10,"commission_basis":"published","wells":["gear"],"draw_rank":24,"blurb":"NPS: \"Hikers are encouraged to wear or bring a hat and carry water\" and wear \"proper footwear (good tread, ankle support, closed toe)\", \"using trekking poles to help maintain balance\"; on Lassen Peak, \"Wear proper footwear and consider using trekking poles\" for snow."},{"name":"Wildland Trekking - Best of Lassen Volcanic Basecamp","source":"https://wildlandtrekking.com/trips/best-of-lassen-volcanic-camping-tour/","accessed":"2026-10-03","si":["group","hiking","adventure","family"],"booking_route":"own website booking (wildlandtrekking.com)","commission_status":"unknown","commission":"operator","tier_absent_reason":"does-not-compete","wells":["activities"],"draw_rank":25,"blurb":"A guided \"5 days, 4 nights\" basecamp trip from Sacramento for \"2-7 Guests\", \"12 and older\": \"Summit Lassen Peak\", Bumpass Hell, Brokeoff Mountain, Cinder Cone and the Fantastic Lava Beds; \"All meals are included from breakfast on Day 1 through lunch on the last day\"; tent, pad, sleeping bag, day pack and trekking poles supplied. Wildland is part of the Intrepid Group."},{"name":"Outdoor Adventure Club - Lassen backcountry ski guiding","source":"https://outdooradventureclub.com/?p=6638","accessed":"2026-10-03","si":["ski","adventure","group"],"booking_route":"contact via the club website","commission_status":"unknown","commission":"guide","tier_absent_reason":"does-not-compete","wells":["activities"],"draw_rank":26,"blurb":"\"we''ve been permitted and insured to guide backcountry skiing, splitboarding, and AIARE avalanche classes in Lassen for over 20 years\"; Group Weekends staying at their Mineral cabin (Intro and Intermediate) and private guiding \"starting at $550/day for 1-2 skiers\"."},{"name":"Outdoor Adventure Club - ski, splitboard and avalanche gear rental","source":"https://outdooradventureclub.com/backcountry-ski-and-splitboard-rentals-for-lassen-national-park/","accessed":"2026-10-03","si":["ski","adventure"],"booking_route":"contact via the club website","commission_status":"unknown","commission":"operator","tier_absent_reason":"does-not-compete","wells":["gear"],"draw_rank":27,"blurb":"Rents \"backcountry ski, splitboard and avalanche gear\" including \"beacons, shovels, and probes\" from \"our cabin in the town of Mineral\", for guests registered on a trip or staying at the Mineral house; \"advance planning is suggested\" as \"supplies are limited\"."},{"name":"Manzanita Lake Camper Store","source":"http://lassenlodging.com/food-service/","accessed":"2026-10-03","si":["family","adventure"],"booking_route":"walk-in at the store","commission_status":"unknown","commission":"operator","tier_absent_reason":"does-not-compete","wells":["gear","eat","shop"],"draw_rank":28,"blurb":"Near the northwest entrance: \"beverages, snacks, organic salads, and deli sandwiches\"; season \"May 21-October 12, daily 8 am-8 pm\". The NPS lists \"Food and beverages, camping supplies, and gifts\" plus watercraft rentals, gasoline, showers and laundry."},{"name":"Lassen Cafe & Gift","source":"http://lassenlodging.com/food-service/","accessed":"2026-10-03","si":["culinary","family","group","senior"],"booking_route":"walk-in; group lunches by phone (530) 595-3555","commission_status":"unknown","commission":"venue","tier_absent_reason":"does-not-compete","wells":["eat"],"draw_rank":29,"blurb":"In the Kohm Yah-mah-nee Visitor Center at the southwest entrance: \"salads, fresh fruits, hot or cold sandwiches, as well as a variety of beverages (including espresso drinks) and soft-serve ice cream\"; patio with mountain views and a fireplace inside; group lunches on request at (530) 595-3555."},{"name":"Highlands Ranch Resort","source":"https://www.highlandsranchresort.com/","accessed":"2026-10-03","si":["romance","culinary","senior"],"booking_route":"own website or 530-595-3388","commission_status":"unknown","commission":"hotel","tier_absent_reason":"not-established","wells":["stay","eat"],"draw_rank":30,"blurb":"Mill Creek, on Hwy 36E in Lassen National Forest, \"approximately 10 minutes east of the park\": 7 newly built cottages and an American Bistro with full bar and a large wood-burning fireplace; summer (May 20-Nov 1) daily 8 AM-9 PM, winter Thursday-Sunday. 530-595-3388."},{"name":"Mill Creek Resort","source":"https://www.millcreekresort.net/","accessed":"2026-10-03","si":["glamping","family","group"],"booking_route":"ResNexus online booking, 530.595.4449 or email","commission_status":"unknown","commission":"hotel","tier_absent_reason":"not-established","wells":["stay"],"draw_rank":31,"blurb":"\"the off-the-beaten-path mountain resort\" in a historic 1930s lodge at 40271 Highway 172, Mill Creek: cabins with full kitchens, glamping tents, RV sites and vintage RV rentals; open year-round, pet-friendly, no Wi-Fi or cell service. Hipcamp lists it with \"Cabins, Glamping Tents, RV Spots\"."},{"name":"Lassen Glampsite (No Electricity)","source":"https://www.hipcamp.com/en-US/p/united-states/california/point-of-interest/bumpass-hell/glamping","accessed":"2026-10-03","si":["glamping","adventure"],"booking_route":"Hipcamp","commission_status":"unknown","commission":"affiliate","tier_absent_reason":"not-established","wells":["stay"],"draw_rank":32,"blurb":"Listed by Hipcamp among glamping near Bumpass Hell as a \"Glampsite Cabin\" in Lassen National Forest, 13 mi away."},{"name":"Cedar Lodge Motel & RV Park","source":"https://www.campspot.com/park/cedar-lodge-motel-and-rv-park-chester-ca","accessed":"2026-10-03","si":["motoring","family","group"],"booking_route":"Campspot","commission_status":"commissioned","commission":"affiliate","tier_absent_reason":"not-established","commission_pct_low":3,"commission_pct_high":3,"commission_basis":"published","wells":["stay"],"draw_rank":33,"blurb":"1487 County Road 324, Chester: \"just outside Lassen National Park\" and \"less than a mile from the pristine waters of Lake Almanor\"; 17 RV sites with water, sewer and 30/50-amp electric (11 full hook-up, 3 pull-through, an oversized family site for up to 4 RVs, 2 boondocking sites) plus 9 cabin and lodging units."},{"name":"Sacramento River RV Park","source":"https://www.campspot.com/c/rv-camping-in-california/near-lassen-volcanic-national-park","accessed":"2026-10-03","si":["motoring","family"],"booking_route":"Campspot","commission_status":"commissioned","commission":"affiliate","tier_absent_reason":"not-established","commission_pct_low":3,"commission_pct_high":3,"commission_basis":"published","wells":["stay"],"draw_rank":34,"blurb":"Redding, listed by Campspot near Lassen with waterfront, pool, fishing, dog park, playground, showers, laundry and dump station."},{"name":"North Shore Campground, Lake Almanor","source":"https://www.campspot.com/park/north-shore-campground-chester-ca","accessed":"2026-10-03","si":["family","motoring","group"],"booking_route":"Campspot","commission_status":"commissioned","commission":"affiliate","tier_absent_reason":"not-established","commission_pct_low":3,"commission_pct_high":3,"commission_basis":"published","wells":["stay"],"draw_rank":35,"blurb":"541 Catfish Beach Road, Chester: \"With over a mile of Lake Almanor shoreline, you''ll enjoy immaculate views, a peaceful environment, and many fun activities\"; 63 RV sites (30-amp, water), 30 tent sites and 5 cabins; boat launch, kayaking, playground, store, showers and laundry."},{"name":"McArthur-Burney Falls Memorial State Park","source":"https://www.parks.ca.gov/?page_id=455","accessed":"2026-10-03","si":["family","hiking","senior"],"booking_route":"California State Parks reservations","commission_status":"unknown","commission":"venue","tier_absent_reason":"not-established","wells":["stay","activities"],"draw_rank":36,"blurb":"A \"129-foot white-water falls on Burney Creek\", \"northeast of Redding, 6 miles north of Highway 299 on Highway 89 near Burney\"; tent, hike-and-bike and remote campsites and cabins (\"The cabins are closed during winter\"), camping $35 a night, day use \"$10.00\" per vehicle, \"8:00 a.m. to sunset\"."},{"name":"Hilton Garden Inn Redding","source":"https://hotelguides.com/attraction-maps/california/map-hotels-near-lassen-volcanic-national-park-ca.html","accessed":"2026-10-03","si":["family","senior","group"],"booking_route":"hilton.com (brand booking; not fetched)","commission_status":"commissioned","commission":"hotel","tier_absent_reason":"not-established","commission_pct_low":10,"commission_pct_high":10,"commission_basis":"benchmark","wells":["stay"],"draw_rank":37,"blurb":"Listed by HotelGuides at \"5050 Bechelli Lane, I-5, Exit 675, Redding, CA 96002\", \"44 miles from Lassen Volcanic National Park\". The brand page was not fetched, so nothing else about the property is stated here."},{"name":"Hampton Inn & Suites Redding","source":"https://hotelguides.com/attraction-maps/california/map-hotels-near-lassen-volcanic-national-park-ca.html","accessed":"2026-10-03","si":["family","senior","group"],"booking_route":"hilton.com (brand booking; not fetched)","commission_status":"commissioned","commission":"hotel","tier_absent_reason":"not-established","commission_pct_low":10,"commission_pct_high":10,"commission_basis":"benchmark","wells":["stay"],"draw_rank":38,"blurb":"Listed by HotelGuides at \"2160 Larkspur Lane, I-5, Exit 677, Redding, CA 96001\", \"45 miles from Lassen Volcanic National Park\". The brand page was not fetched, so nothing else about the property is stated here."},{"name":"TownePlace Suites by Marriott Redding","source":"https://hotelguides.com/attraction-maps/california/map-hotels-near-lassen-volcanic-national-park-ca.html","accessed":"2026-10-03","si":["family","senior","group"],"booking_route":"marriott.com (brand booking; not fetched)","commission_status":"commissioned","commission":"hotel","tier_absent_reason":"not-established","commission_pct_low":8,"commission_pct_high":10,"commission_basis":"published","wells":["stay"],"draw_rank":39,"blurb":"Listed by HotelGuides at \"2180 Larkspur Lane, I-5, Exit 677, Redding, CA 96002\", \"45 miles from Lassen Volcanic National Park\". The Marriott page was not fetched (the Sheraton Redding domain failed its certificate check), so nothing else about the property is stated here."},{"name":"Holiday Inn Express & Suites Red Bluff","source":"https://hotelguides.com/attraction-maps/california/map-hotels-near-lassen-volcanic-national-park-ca.html","accessed":"2026-10-03","si":["family","senior","group"],"booking_route":"ihg.com (brand booking; not fetched)","commission_status":"commissioned","commission":"hotel","tier_absent_reason":"not-established","commission_pct_low":10,"commission_pct_high":10,"commission_basis":"benchmark","wells":["stay"],"draw_rank":40,"blurb":"Listed by HotelGuides at \"2810 Main Street, I-5, Exit 650, Red Bluff, CA 96080\", \"44 miles from Lassen Volcanic National Park\". The IHG page was not fetched, so nothing else about the property is stated here."},{"name":"Red Onion Grill","source":"https://www.redoniongrill.com/","accessed":"2026-10-03","si":["culinary","romance","group"],"booking_route":"Toast online reservations or (530) 596-1800","commission_status":"unknown","commission":"venue","tier_absent_reason":"does-not-compete","wells":["eat"],"draw_rank":41,"blurb":"303 Peninsula Drive, Lake Almanor: \"craft-cocktails, farm-to-table eats\"; Wednesday-Sunday 5PM-8:30PM, closed Monday and Tuesday; (530) 596-1800; large groups via info@redoniongrill.com."},{"name":"Timber House Restaurant, Brewery & Lodge","source":"https://sierrarecmagazine.com/timber-house-restaurant-brewery/","accessed":"2026-10-03","si":["culinary","group"],"booking_route":"phone 530.815.8459","commission_status":"unknown","commission":"venue","tier_absent_reason":"does-not-compete","wells":["eat"],"draw_rank":42,"blurb":"501 Main Street, Chester: established in 1962, closed for years and reopened by Toni and Robert Vanella and Carol and Berton Bertagna - \"popular pub fare\", an on-site brewery with seasonal craft beers and a restored nine-room lodge; restaurant Friday-Monday, 11 a.m.-2 p.m. and 5-9 p.m."},{"name":"Kopper Kettle","source":"https://www.lakealmanorarea.com/restaurants","accessed":"2026-10-03","si":["culinary","family"],"booking_route":"walk-in / phone 530-258-2698","commission_status":"unknown","commission":"venue","tier_absent_reason":"does-not-compete","wells":["eat"],"draw_rank":43,"blurb":"243 Main Street, Chester; 530-258-2698; \"Breakfast, Lunch, Dinner\" (Lake Almanor Area Chamber listing)."},{"name":"St. Bernard Lodge","source":"https://www.lakealmanorarea.com/restaurants","accessed":"2026-10-03","si":["culinary","romance"],"booking_route":"phone 530-258-3382","commission_status":"unknown","commission":"venue","tier_absent_reason":"does-not-compete","wells":["eat"],"draw_rank":44,"blurb":"44801 Hwy 36 East; 530-258-3382; stbernardlodge.com; \"Breakfast, Lunch, Dinner, Cocktails\" (Lake Almanor Area Chamber listing)."},{"name":"Tantardino''s Pizzeria & Pasta","source":"https://www.lakealmanorarea.com/restaurants","accessed":"2026-10-03","si":["culinary","family","group"],"booking_route":"phone 530-596-3902","commission_status":"unknown","commission":"venue","tier_absent_reason":"does-not-compete","wells":["eat"],"draw_rank":45,"blurb":"441 Ponderosa Drive, Lake Almanor Peninsula; 530-596-3902; \"Lunch, Dinner, Cocktails\" (Lake Almanor Area Chamber listing)."},{"name":"Waganupa Brewing","source":"https://www.lakealmanorarea.com/restaurants","accessed":"2026-10-03","si":["culinary","group"],"booking_route":"walk-in","commission_status":"unknown","commission":"venue","tier_absent_reason":"does-not-compete","wells":["eat"],"draw_rank":46,"blurb":"401 Peninsula Dr #9, Lake Almanor Peninsula; listed for \"Beer\" (Lake Almanor Area Chamber listing)."}],"faq":[{"q":"How much is Lassen Volcanic National Park?","a":"The NPS lists \"Private Vehicle (Apr 16-Nov 30) $30.00\" and \"Private Vehicle (Dec 1-Apr 15) $10.00\"; motorcycles $25.00 / $10.00; per person $15.00 / $10.00; and \"Annual Entrance - Park $55.00\".","source":"https://www.nps.gov/lavo/planyourvisit/fees.htm","accessed":"2026-10-03"},{"q":"Can you camp in Lassen Volcanic National Park?","a":"Yes. Seven campgrounds are listed, from Manzanita Lake (179 sites) to Warner Valley (17 sites), at $15 to $26 a night; \"Reservations are required for all campgrounds except Juniper Lake and Southwest Walk-in\", via recreation.gov or (877) 444-6777. Backcountry camping needs a Recreation.gov wilderness permit.","source":"https://www.nps.gov/lavo/planyourvisit/camping-in-campgrounds.htm","accessed":"2026-10-03"},{"q":"Is Lassen Volcanic National Park dog friendly?","a":"Only where a car can go: \"A pet may go anywhere a car may go: roads and road shoulders (not snow-covered), campgrounds, picnic areas, and parking lots.\" \"Pets are not permitted on any hiking trail, in the park backcountry... in any body of water, or inside visitor centers or other park facilities.\" Leashes must be under six feet.","source":"https://www.nps.gov/lavo/planyourvisit/pets.htm","accessed":"2026-10-03"},{"q":"What is the best time to visit Lassen Volcanic National Park?","a":"Summer is \"The most popular season in the park\" with \"the widest selection of activities and services\"; \"Wildflowers peak in high elevation areas between July and September.\" Snow lingers: \"Bumpass Hell Trail remains closed due to snow coverage into July\".","source":"https://www.nps.gov/lavo/planyourvisit/summer.htm","accessed":"2026-10-03"},{"q":"When does Lassen Volcanic National Park close?","a":"The park itself does not close: \"Lassen Volcanic National Park is open 24 hours per day, 365 days per year.\" The park highway does - Highway 89 typically \"closes in mid- to late November\" for snow and has closed as early as October 18.","source":"https://www.nps.gov/lavo/planyourvisit/fall.htm","accessed":"2026-10-03"},{"q":"Can you drive through Lassen Volcanic National Park?","a":"In summer and fall, yes: \"Take the one-hour drive along the 30-mile park highway.\" The highway \"is closed to through traffic due to snow approximately November through April.\"","source":"https://www.nps.gov/thingstodo/visitsulphurworks.htm","accessed":"2026-10-03"},{"q":"Does Lassen Volcanic National Park have hot springs?","a":"It has hydrothermal areas, not bathing springs: \"Bumpass Hell Trail provides access to the largest hydrothermal area in the park.\" The NPS warns: \"Water and mud in hydrothermal areas is acidic. Do not put water or mud from park hydrothermal areas on your skin.\"","source":"https://www.nps.gov/thingstodo/hikebumpasshell.htm","accessed":"2026-10-03"},{"q":"What are things to do in Lassen Volcanic National Park with kids?","a":"The Junior Ranger programme: \"The activities in the Junior Ranger booklet are best-suited to kids age 5 to 12\", picked up \"at the Loomis Museum (summer only) or Kohm Yah-mah-nee Visitor Center\", with a badge on completion.","source":"https://www.nps.gov/lavo/learn/kidsyouth/beajuniorranger.htm","accessed":"2026-10-03"},{"q":"Do you need a permit for Lassen Volcanic National Park?","a":"For backcountry camping, yes: \"Wilderness permits for backcountry camping must be obtained prior to your visit to the park\" through Recreation.gov, and \"Permits can be reserved a maximum of 90 days prior to the start date.\"","source":"https://www.nps.gov/lavo/planyourvisit/wilderness-permit-information.htm","accessed":"2026-10-03"},{"q":"Can you fish in Lassen Volcanic National Park?","a":"Yes: \"Numerous lakes and streams provide plentiful opportunities for fishing.\"","source":"https://www.nps.gov/lavo/planyourvisit/things2do.htm","accessed":"2026-10-03"}],"seo":{"meta_title":"Lassen Volcanic National Park: Bumpass Hell, Lassen Peak & Camping | TravelWell","meta_description":"Bumpass Hell''s boardwalk, the 5-mile Lassen Peak climb, Cinder Cone, seven campgrounds, Drakesbad Guest Ranch, and where to camp, glamp and eat nearby.","slug":"lassen-volcanic-national-park-california","primary_keyword":"Lassen Volcanic National Park","jsonld_type":"TouristDestination"},"hero":{"query":"Lassen Volcanic National Park Bumpass Hell"}}'::jsonb, 97),
  ('olympic-washington', '12A', 'Olympic National Park', 'United States', 'A mountain ridge, a moss-hung rain forest and a wilderness coast, joined by one highway that loops the whole peninsula', 'future', 'verified', 'mountainValley', 'The Pacific Northwest', '{"hiking","ocean","wildlife","family","parks"}', '{"wild","coastal","rugged"}', '{}', null, null, '{"safety":{"posture":"book-freely","source":"https://www.gov.uk/foreign-travel-advice/usa","verified":"2026-10-08"},"jewels":[{"name":"Hurricane Ridge (road open; Day Lodge destroyed, rebuild no earlier than 2028)","source":"https://www.nps.gov/olym/planyourvisit/visiting-hurricane-ridge.htm","accessed":"2026-10-02","si":["hiking"],"tier_absent_reason":"not-sold","blurb":"\"the most easily accessed mountain area within Olympic National Park\", 17 miles south of Port Angeles; the conditions page shows the road open to the ridge with Obstruction Point and Hurricane Hill roads open; winter road scheduled Friday-Sunday and holiday Mondays with chains required; the 1952 Day Lodge burned in May 2023"},{"name":"Hurricane Hill Trail","source":"https://www.nps.gov/olym/planyourvisit/day-hiking-at-olympic.htm","accessed":"2026-10-02","si":["hiking"],"tier_absent_reason":"not-sold","blurb":"1.6 miles one way from the end of the Hurricane Ridge Road, about 700 feet of gain, to panoramic views"},{"name":"Hurricane Ridge astronomy programs and winter snowshoe walks","source":"https://www.nps.gov/olym/planyourvisit/ranger-led-programs.htm","accessed":"2026-10-02","si":["family"],"tier_absent_reason":"not-sold","blurb":"free ranger-led telescope evenings at the Ridge in summer, weather permitting, and ranger-guided snowshoe walks in winter"},{"name":"Hall of Mosses and Spruce Nature Trail, Hoh Rain Forest","source":"https://www.nps.gov/olym/planyourvisit/visiting-the-hoh.htm","accessed":"2026-10-02","si":["hiking"],"tier_absent_reason":"not-sold","blurb":"two loops from the Hoh visitor center - the 0.8-mile Hall of Mosses through maples \"draped with abundant club moss\" and the 1.2-mile Spruce Nature Trail by creek and river; the Hoh River Trail runs on, 18.5 miles out-and-back; visitor center closed January to early March"},{"name":"Marymere Falls and Mount Storm King, Lake Crescent","source":"https://www.nps.gov/olym/planyourvisit/day-hiking-at-olympic.htm","accessed":"2026-10-02","si":["hiking"],"tier_absent_reason":"not-sold","blurb":"0.9 miles one way to Marymere Falls from Storm King Ranger Station (first half-mile wheelchair accessible); the Mount Storm King spur is 2.1 miles one way and \"climbs 2,100 feet!\""},{"name":"Spruce Railroad Trail and the Olympic Discovery Trail","source":"https://www.nps.gov/olym/planyourvisit/day-hiking-at-olympic.htm","accessed":"2026-10-02","si":["family"],"tier_absent_reason":"not-sold","blurb":"4 miles one way along Lake Crescent''s north shore, paved, pets and bikes allowed, with a 6.5-mile paved extension west; part of the Olympic Discovery Trail that runs from Port Townsend to La Push"},{"name":"Sol Duc Falls","source":"https://www.nps.gov/olym/planyourvisit/visiting-the-sol-duc-valley.htm","accessed":"2026-10-02","si":["hiking"],"tier_absent_reason":"not-sold","blurb":"0.8 miles one way through old-growth forest from the end of the Sol Duc Road to the falls overlook"},{"name":"Salmon Cascades Overlook, Sol Duc Valley","source":"https://www.nps.gov/olym/planyourvisit/wildlife-viewing.htm","accessed":"2026-10-02","si":["wildlife"],"tier_absent_reason":"not-sold","blurb":"where \"visitors come to watch the determined coho salmon leap over the falls\"; the NPS gives late September to early October as the best viewing"},{"name":"High Divide Loop and Seven Lakes Basin","source":"https://www.nps.gov/olym/planyourvisit/wilderness-reservations.htm","accessed":"2026-10-02","si":["expedition"],"tier_absent_reason":"not-sold","blurb":"\"a popular 2-3 day hike\" from the Sol Duc; Sol Duc/Seven Lakes Basin is a wilderness quota area booked on Recreation.gov, with bear canisters required in all wilderness camp areas"},{"name":"Rialto Beach and Hole-in-the-Wall","source":"https://www.nps.gov/olym/planyourvisit/visiting-mora-and-rialto.htm","accessed":"2026-10-02","si":["ocean"],"tier_absent_reason":"not-sold","blurb":"drift logs, pounding surf and sea stacks; Hole-in-the-Wall is a sea-carved arch about 1.5 miles north; the NPS: \"Always check the tides! It''s possible to get stranded when certain areas of the coast become impassable when high tide rolls in.\""},{"name":"Second Beach, La Push","source":"https://www.nps.gov/olym/planyourvisit/day-hiking-at-olympic.htm","accessed":"2026-10-02","si":["ocean"],"tier_absent_reason":"not-sold","blurb":"a 0.7-mile hike from La Push Road to tide pools and sea stacks on the Olympic Wilderness Coast"},{"name":"Ruby Beach","source":"https://www.nps.gov/olym/planyourvisit/day-hiking-at-olympic.htm","accessed":"2026-10-02","si":["ocean"],"tier_absent_reason":"not-sold","blurb":"a 0.2-mile walk from Highway 101 down to the coast and its sea stacks"},{"name":"Kalaloch Beach 4 tide pools","source":"https://www.nps.gov/olym/planyourvisit/visiting-kalaloch-and-ruby-beach.htm","accessed":"2026-10-02","si":["ocean"],"tier_absent_reason":"not-sold","blurb":"the NPS: \"Beach 4 is an excellent location to tidepool looking for seastars, and anemones of various colors can be seen at low tides\"; \"Certain areas may become impassable during high tides and overland trails must be used.\""},{"name":"Ozette boardwalks to the coast","source":"https://www.nps.gov/olym/planyourvisit/visiting-ozette.htm","accessed":"2026-10-02","si":["adventure"],"tier_absent_reason":"not-sold","blurb":"\"Two three-mile boardwalk trails lead to the coast where seals and gray whales can be spotted during migratory months\"; a 15-site lakeside campground; wilderness permits and bear canisters are not available at Ozette Ranger Station"},{"name":"Elwha Valley: Madison Falls and the Olympic Hot Springs Road","source":"https://www.nps.gov/olym/planyourvisit/visiting-the-elwha.htm","accessed":"2026-10-02","si":["adventure"],"tier_absent_reason":"not-sold","blurb":"site of \"one of the largest ecosystem restoration projects in National Park Service history\"; closed to vehicles beyond the Madison Falls parking lot due to flood damage, open beyond it to bikes, walkers, stock and leashed pets"},{"name":"Lake Crescent Lodge","source":"https://www.nps.gov/olym/planyourvisit/lodging.htm","accessed":"2026-10-02","si":["senior"],"tier_absent_reason":"not-sold","blurb":"in-park cottages, cabins and lodge rooms on the glacially carved lake, season April 17, 2026 to January 1, 2027; rowboats for rent at the lodge"},{"name":"Log Cabin Resort, Lake Crescent","source":"https://www.nps.gov/olym/planyourvisit/lodging.htm","accessed":"2026-10-02","si":["family"],"tier_absent_reason":"not-sold","blurb":"camping, chalets, cabins and lodge rooms on the north shore, season May 15 to September 29, 2026 (closed now for the year); kayak and canoe rentals in season"},{"name":"Sol Duc Hot Springs Resort","source":"https://www.olympicnationalparks.com/sol-duc-hot-springs-resort","accessed":"2026-10-02","si":["wellness"],"tier_absent_reason":"not-sold","blurb":"rustic cabins (standard and kitchenette), naturally heated mineral pools and a freshwater pool, the Springs Restaurant; open March to November; Aramark concession"},{"name":"Kalaloch Lodge","source":"https://www.thekalalochlodge.com/","accessed":"2026-10-02","si":["romance"],"tier_absent_reason":"not-sold","blurb":"\"the only oceanfront lodge in Olympic National Park\" - main lodge rooms, bluff cabins and the Seacrest House, Creekside Restaurant; run by Delaware North as an authorized NPS concessioner"},{"name":"Lake Quinault Lodge (Olympic National Forest)","source":"https://www.olympicnationalparks.com/lake-quinault-lodge","accessed":"2026-10-02","si":["senior"],"tier_absent_reason":"not-sold","blurb":"built 1926 and marking 100 years in 2026; lakeside lodge rooms, indoor pool and sauna, Roosevelt Dining Room, kayak rentals; Aramark under a US Forest Service permit"},{"name":"Sol Duc Rainforest Retreat, near Lake Crescent (listing)","source":"https://www.hipcamp.com/en-US/land/washington-sol-duc-rainforest-retreat-nelhwq6w","accessed":"2026-10-02","si":["glamping"],"tier_absent_reason":"not-sold","blurb":"14 sites on 9 acres beside the Olympic Discovery Trail, about 1-1.5 miles from Lake Crescent, including canvas tents and yurts with tent decks, hot showers and covered outdoor kitchens - per its Hipcamp listing"},{"name":"Whiskey Creek Beach, near Port Angeles","source":"https://whiskeycreekbeachnw.com/","accessed":"2026-10-02","si":["glamping"],"tier_absent_reason":"not-sold","blurb":"beachfront cabins, glamping/tent sites and RV hookups on the Strait of Juan de Fuca, booked direct on its own site"},{"name":"Mike''s Beach Resort Glamping Village, Lilliwaup (Hood Canal, Staircase side)","source":"https://www.mikesbeachresort.com","accessed":"2026-10-02","si":["glamping"],"tier_absent_reason":"not-sold","blurb":"fully furnished camping tents with beds, heating, bedding, towels, outlets and wifi, plus a private BBQ and firepit at each site, alongside Hood Canal waterfront cabins at 38470 N US Hwy 101"},{"name":"Kalaloch Campground (NPS)","source":"https://www.nps.gov/olym/planyourvisit/camping.htm","accessed":"2026-10-02","si":["ocean"],"tier_absent_reason":"not-sold","blurb":"175 sites on the coast, open year-round; reservations on recreation.gov May 15 to September 20, 2026, first-come outside that window"},{"name":"Mora Campground (NPS)","source":"https://www.nps.gov/olym/planyourvisit/camping.htm","accessed":"2026-10-02","si":["ocean"],"tier_absent_reason":"not-sold","blurb":"94 sites about 3 miles from Rialto Beach, open year-round; reservations on recreation.gov May 15 to September 20, 2026, first-come otherwise"},{"name":"Hoh Rain Forest Campground (NPS)","source":"https://www.nps.gov/olym/planyourvisit/camping.htm","accessed":"2026-10-02","si":["family"],"tier_absent_reason":"not-sold","blurb":"year-round; reservations on recreation.gov June 12 to September 6, 2026, first-come outside that window"},{"name":"Sol Duc Hot Springs RV and Campground","source":"https://www.nps.gov/olym/planyourvisit/camping.htm","accessed":"2026-10-02","si":["family"],"tier_absent_reason":"not-sold","blurb":"82 sites in old-growth forest along the river; reservations on recreation.gov March 20 to November 1, 2026"},{"name":"Heart O'' the Hills Campground (NPS)","source":"https://www.nps.gov/olym/planyourvisit/camping.htm","accessed":"2026-10-02","si":["family"],"tier_absent_reason":"not-sold","blurb":"105 sites in old-growth forest 5 miles south of Port Angeles on the Hurricane Ridge road; first-come, first-served, year-round, walk-in only in heavy snow"},{"name":"First-come NPS campgrounds: Deer Park, Graves Creek, North Fork, Ozette, Queets, South Beach (and Staircase)","source":"https://www.nps.gov/olym/planyourvisit/camping.htm","accessed":"2026-10-02","si":["adventure"],"tier_absent_reason":"not-sold","blurb":"no reservations at Deer Park (self-register, June to mid-October), Graves Creek, North Fork, Ozette, Queets and South Beach (May 19 to October 10, 2026); Staircase takes recreation.gov reservations July 8 to September 29 and is first-come otherwise"},{"name":"Crescent Beach & RV Park, Port Angeles","source":"https://www.hipcamp.com/en-US/land/washington-crescent-beach-rv-88lhqkp7","accessed":"2026-10-02","si":["family"],"tier_absent_reason":"not-sold","blurb":"67 RV, tent and cabin sites on 18 acres behind a half-mile sandy beach at 2860 Crescent Beach Rd (address per the Port Angeles visitor bureau), open year-round, near the Tongue Point Marine Life Sanctuary tide pools"},{"name":"Elwha Dam RV Park, Port Angeles","source":"https://elwhadamrvpark.com/","accessed":"2026-10-02","si":["family"],"tier_absent_reason":"not-sold","blurb":"big-rig pull-throughs, tent sites, guest houses and e-bike rentals at 47 Lower Dam Rd, year-round, billed as an \"Olympic Basecamp\""},{"name":"John Wayne''s Waterfront Resort, Sequim","source":"https://www.hipcamp.com/en-US/land/washington-john-wayne-s-waterfront-resort-1-7rvhmqze","accessed":"2026-10-02","si":["family"],"tier_absent_reason":"not-sold","blurb":"89 RV and tent sites and 9 fully equipped bay-view cabins on 20 acres by Sequim Bay, on the Olympic Discovery Trail near John Wayne Marina - per its Hipcamp listing"},{"name":"Quileute Oceanside Resort, La Push","source":"https://quileuteoceanside.com/","accessed":"2026-10-02","si":["culture"],"tier_absent_reason":"not-sold","blurb":"owned and operated by the Quileute Tribe: oceanfront luxury and rustic cabins, apartments, ocean and riverview RV spots and tent sites at 330 Ocean Drive, \"no TVs or Wi-Fi\""},{"name":"Rain Forest Resort Village, Lake Quinault","source":"https://rainforestresort.com/","accessed":"2026-10-02","si":["family"],"tier_absent_reason":"not-sold","blurb":"Parkside Suites, Fireplace Cabins, the Village Inn and an RV campground on the lake shore, home of the \"World''s Largest Spruce Tree\" by its own account"},{"name":"Hoh River Rafters, Forks","source":"https://hohriverrafters.com/","accessed":"2026-10-02","si":["adventure"],"tier_absent_reason":"not-sold","blurb":"half-day Class II float trips on the Hoh at 9am or 2pm, March 1 to September 15, no experience needed; published at $150 per person"},{"name":"Olympic Hiking Co., Port Angeles","source":"https://www.hikeolympic.com/","accessed":"2026-10-02","si":["hiking"],"tier_absent_reason":"not-sold","blurb":"\"a commercially authorized tour company in Olympic National Park\" since 2016 - small-group and private guided hikes, guided backpacking, and coast trailhead shuttles such as Rialto to Ozette and Third Beach to Oil City"},{"name":"Experience Olympic, Port Angeles","source":"https://experienceolympic.com/","accessed":"2026-10-02","si":["wildlife"],"tier_absent_reason":"not-sold","blurb":"a \"Permittee of Olympic National Park\" since 2013, woman-owned: private guided nature days for birding, tidepooling (April-August low tides), the Elwha restoration, Hurricane Ridge, the Hoh and the coast"},{"name":"Elevate Outdoors, Port Angeles","source":"https://elevateoutdoors.us/","accessed":"2026-10-02","si":["adventure"],"tier_absent_reason":"not-sold","blurb":"kayak tours on Lake Crescent and Freshwater Bay, Olympic Discovery Trail bike tours and combination days, May to October; bike rentals by reservation year-round, at 220 E 1st Street"},{"name":"Puget Sound Express whale watching, Port Townsend","source":"https://www.pugetsoundexpress.com/","accessed":"2026-10-02","si":["wildlife"],"tier_absent_reason":"not-sold","blurb":"4-hour half-day whale watching April-November and a full-day San Juan Islands trip April-September from 227 Jackson Street; whale sightings on 99% of trips by its own account, with a free return trip if none"},{"name":"Quinault Rainforest Tour (Lake Quinault Lodge)","source":"https://www.olympicnationalparks.com/things-to-do/lake-quinault-lodge/tours-of-lake-quinault-rainforest/","accessed":"2026-10-02","si":["senior"],"tier_absent_reason":"not-sold","blurb":"a 3-hour guided shuttle tour 33 miles into the Quinault valley and the Valley of the Giants, year-round, 9:30 am departures, minimum 4 passengers; $55 plus tax"},{"name":"M.V. Coho ferry, Port Angeles to Victoria BC","source":"https://www.cohoferry.com/","accessed":"2026-10-02","si":["culture"],"tier_absent_reason":"not-sold","blurb":"Black Ball Ferry Line''s daily, year-round 90-minute crossing of the Strait of Juan de Fuca, 22.59 nautical miles"},{"name":"Hurricane Ridge Ski & Snowboard Area","source":"https://hurricaneridge.com/","accessed":"2026-10-02","si":["sports"],"tier_absent_reason":"not-sold","blurb":"a non-profit, locals-run lift area inside the park; 2026-27 season tentatively Saturdays, Sundays and Monday holidays, 10 am-4 pm, snow permitting, with ski school, tubing and snowshoeing"},{"name":"Purple Haze Lavender, Sequim","source":"https://www.purplehazelavender.com/","accessed":"2026-10-02","si":["culture"],"tier_absent_reason":"not-sold","blurb":"farm store at 180 Bell Bottom Rd, Wednesday-Sunday 10am-5pm; fields bloom from late June through July, some into September"},{"name":"Sequim Lavender Festival","source":"https://www.lavenderfestival.com/","accessed":"2026-10-02","si":["culture"],"tier_absent_reason":"not-sold","blurb":"the Sequim Lavender Growers Association''s festival of farm visits, u-pick, live music and 200+ artisan vendors; 2026 dates were July 17-19"},{"name":"Dungeness Crab Festival, October 9-11, 2026","source":"https://www.crabfestival.org/","accessed":"2026-10-02","si":["culture"],"tier_absent_reason":"not-sold","blurb":"a free three-day festival on the Port Angeles Waterfront City Pier - crab dinners from 14,000+ crabs, 75+ vendor booths, live music and Coast Guard boat tours"},{"name":"Finnriver Farm & Cidery, Chimacum","source":"https://www.finnriver.com/","accessed":"2026-10-02","si":["culinary","wine","family","group"],"booking_route":"walk-in Cider Garden; events and groups by phone 360-339-8478 or email","tier_absent_reason":"not-sold","blurb":"Certified Organic, Salmon Safe B Corp farm, orchard and cidery along a salmon stream; year-round Cider Garden (Wed-Sun 12-8pm) with draft ciders, Finnriver Kitchen, seasonal tours and weekend live music."},{"name":"Hama Hama Oyster Saloon and Farm Store, Lilliwaup (Hood Canal, Staircase side)","source":"https://www.hamahamaoysters.com/","accessed":"2026-10-02","si":["culinary","ocean","family","group"],"booking_route":"reservations recommended but not required; phone (360) 877-5811 or email","tier_absent_reason":"not-sold","blurb":"Sixth-generation family shellfish farm whose farm store has sold fresh shellfish since the 1970s; outdoor Oyster Saloon open weekends year round, oyster classes in winter."},{"name":"Finistere, Port Townsend","source":"https://www.restaurantfinistere.com/","accessed":"2026-10-02","si":["culinary","romance"],"booking_route":"Resy","tier_absent_reason":"not-sold","blurb":"Farm-to-table restaurant (''End of the Land'') on Lawrence Street, dinner Wednesday to Saturday 5-8pm with a 3-5pm happy hour."},{"name":"Alder Wood Bistro, Sequim","source":"https://www.alderwoodbistro.com/","accessed":"2026-10-02","si":["culinary","romance","family"],"booking_route":"Tock; groups of 7+ by email","tier_absent_reason":"not-sold","blurb":"Wood-fired pizza and contemporary dining, Wednesday to Saturday 4-8pm, with seasonal garden dining Memorial Day weekend through late September."},{"name":"Next Door Gastropub, Port Angeles","source":"https://www.nextdoorgastropub.com/","accessed":"2026-10-02","si":["culinary","group","family"],"booking_route":"no reservations; phone (360) 504-2613 to join a text waitlist","tier_absent_reason":"not-sold","blurb":"Elevated pub fare from fresh local ingredients with ten rotating taps of local, regional and artisan beer, plus a full cocktail bar."},{"name":"Pane d''Amore, Port Townsend and Sequim","source":"https://www.panedamore.com/","accessed":"2026-10-02","si":["culinary","family"],"booking_route":"walk-in","tier_absent_reason":"not-sold","blurb":"Artisan bakery dating to 2004 with shops in Port Townsend (Tue-Sat 7-6, Sun 7-3) and Sequim (Tue-Sat 8-2)."},{"name":"Dungeness Valley Creamery, Sequim","source":"https://www.dungenessvalleycreamery.com/","accessed":"2026-10-02","si":["culinary","family"],"booking_route":"not observed","tier_absent_reason":"not-sold","blurb":"Family-owned raw A2 Jersey dairy whose farm store at 1915 Towne Road sells raw milk and cream, eggs, cheeses, raw honey and Lopez Island ice cream."},{"name":"Chimacum Corner Farmstand, Chimacum","source":"https://www.chimacumcorner.com/","accessed":"2026-10-02","si":["culinary","family"],"booking_route":"walk-in","tier_absent_reason":"not-sold","blurb":"Rural natural grocery and nursery open daily 8am-7pm, stocking hyper-local produce, cheeses, sustainably caught seafood and dishes made daily in the Corner Kitchen."},{"name":"Jefferson County Farmers Markets (Port Townsend and Chimacum)","source":"https://www.jcfmarkets.org/","accessed":"2026-10-02","si":["culinary","family","culture"],"booking_route":"walk-in","tier_absent_reason":"not-sold","blurb":"Three markets with over 100 vendors combined: Port Townsend Saturday (9am-2pm April to October), Port Townsend Wednesday (3-6pm June to September) and Chimacum Sunday (10am-2pm May to October)."},{"name":"Port Angeles Farmers Market","source":"https://www.portangelesfarmersmarket.com/","accessed":"2026-10-02","si":["culinary","family","culture"],"booking_route":"walk-in","tier_absent_reason":"not-sold","blurb":"Year-round Saturday market at the Gateway Transit Center Pavilion, Lincoln and Front Streets downtown; summer hours 9:30am-2:30pm."},{"name":"Harbinger Winery, Port Angeles","source":"https://www.harbingerwinery.com/","accessed":"2026-10-02","si":["wine","romance"],"booking_route":"phone 360-452-4262 or email; no online booking observed","tier_absent_reason":"not-sold","blurb":"Small-batch Washington State winery with a tasting room at 2358 Highway 101 West, pouring unusual varietals alongside traditional favourites."},{"name":"Wind Rose Cellars, Sequim","source":"https://www.windrosecellars.com/","accessed":"2026-10-02","si":["wine","romance","culture"],"booking_route":"not observed","tier_absent_reason":"not-sold","blurb":"Italian-style winery (about 1,000 cases a year) pouring Barbera, Dolcetto, Sangiovese and Albarino in a tasting room and wine bar with live music and an art gallery."},{"name":"FairWinds Winery, Port Townsend","source":"https://www.fairwindswinery.com/","accessed":"2026-10-02","si":["wine","romance"],"booking_route":"walk-in; phone 360-385-6899","tier_absent_reason":"not-sold","blurb":"Winery making Washington wines including Aligote and Lemberger plus Port O''Call fortified wines, with walk-in tastings Friday to Sunday 12-5pm and barrel tastings."},{"name":"Propolis Brewing, Port Townsend","source":"https://enjoypt.com/port-townsend-dining-guide/","accessed":"2026-10-02","si":["culinary","group"],"booking_route":"not observed","tier_absent_reason":"not-sold","blurb":"Listed at 2457 Jefferson Street in the Port Townsend visitor guide''s breweries section; its own site (propolisbrewing.com, loaded 2026-10-02) describes seasonal botanical farmhouse ales."},{"name":"Admiralty Distillers, Port Townsend","source":"https://www.admiraltydistillers.com/","accessed":"2026-10-02","si":["culinary","group"],"booking_route":"not observed","tier_absent_reason":"not-sold","blurb":"Port Townsend distiller of premium whisky and fruit brandy."}],"faq":[{"q":"Is Highway 101 open around Olympic National Park?","a":"Not continuously in October 2026. The NPS states US 101 at the Hoh River Bridge, south of Forks, is closed 5 a.m. Thursday, Oct. 1 to noon Tuesday, Oct. 6 and 5 a.m. Thursday Oct. 8 to noon Tuesday, Oct. 13, with no detour across the Hoh River. The Hoh Rain Forest stays reachable from Forks.","source":"https://www.nps.gov/olym/planyourvisit/hwy-101-closure-at-hoh-river-bridge.htm","accessed":"2026-10-02"},{"q":"Is the Hurricane Ridge Day Lodge open?","a":"No. The NPS states the 1952 Day Lodge was destroyed by fire in May 2023. A design contract was awarded in September 2025 and construction may start in 2028 at the earliest. The road to the ridge is open; in winter it is scheduled Friday through Sunday and holiday Mondays, weather permitting, with tire chains required.","source":"https://www.nps.gov/olym/learn/management/hurricane-ridge-day-lodge-reconstruction-project.htm","accessed":"2026-10-02"},{"q":"How do I reserve a campsite in Olympic National Park?","a":"Kalaloch, Mora, Hoh, Fairholme, Sol Duc and Staircase take recreation.gov reservations in set summer windows and are first-come outside them. Deer Park, Graves Creek, Heart O'' the Hills, North Fork, Ozette, Queets and South Beach are always first-come, first-served.","source":"https://www.nps.gov/olym/planyourvisit/camping.htm","accessed":"2026-10-02"},{"q":"How much does it cost to enter Olympic National Park?","a":"$30 per private vehicle for 7 days, $25 per motorcycle, $15 per person on foot or bike (under 16 free), or $55 for an Olympic Annual Pass. The park does not accept cash.","source":"https://www.nps.gov/olym/planyourvisit/fees.htm","accessed":"2026-10-02"},{"q":"Do I need a permit to backpack in Olympic?","a":"Yes. Wilderness permits are created through Recreation.gov; quota areas include the Ozette Coast, Seven Lakes Basin and Royal Basin. Summer-season permits (May 15 to October 15) are released April 15 at 7:00 am Pacific. Bear canisters are required in all wilderness camp areas.","source":"https://www.nps.gov/olym/planyourvisit/wilderness-reservations.htm","accessed":"2026-10-02"},{"q":"What does the park say about tides on the coast?","a":"The NPS states that \"Several points along the coast are only passable at lower tides\" and advises carrying a tide chart, available at visitor centers and coastal ranger stations.","source":"https://www.nps.gov/olym/planyourvisit/tides-and-your-safety.htm","accessed":"2026-10-02"}],"seo":{"meta_title":"Olympic National Park: Hurricane Ridge, Hoh Rain Forest & Coast | TravelWell","meta_description":"Hurricane Ridge''s status, the Hoh and Lake Crescent trails, Rialto and Ruby Beach, how each campground books, and where to stay from Kalaloch Lodge to Sequim.","slug":"olympic-national-park-washington","primary_keyword":"Olympic National Park","jsonld_type":"TouristDestination"},"hero":{"query":"Olympic National Park, Washington"}}'::jsonb, 98)
