insert into public.destinations (id, region_code, name, country, line, status, depth, img, sub_region, si, feel, tier_range, price_band, draw_rank, data, position) values
  ('mount-rainier-washington', '12A', 'Mount Rainier National Park', 'United States', 'A glaciated volcano with wildflower meadows at Paradise and Sunrise, a year-round historic inn at Longmire, guided summit climbs from Ashford, and treehouses, yurts and Airstreams at the gates', 'future', 'verified', 'mountainValley', 'The Pacific Northwest', '{"hiking","expedition","glamping","family","parks"}', '{"alpine","dramatic","wild"}', '{}', null, null, '{"safety":{"posture":"book-freely","source":"https://www.gov.uk/foreign-travel-advice/usa","verified":"2026-10-08"},"jewels":[{"name":"Paradise and the Henry M. Jackson Memorial Visitor Center","source":"https://www.nps.gov/mora/planyourvisit/paradise.htm","accessed":"2026-10-02","si":["hiking","family","senior"],"booking_route":"none needed - entrance fee only; no timed entry in 2026","commission_status":"unknown","tier_absent_reason":"not-sold","blurb":"the park''s high meadow hub at 5,400 feet, 19 miles from the Nisqually Entrance, with exhibits, film, ranger programmes and cafeteria; visitor centre usually daily May to early October, weekends and holidays mid-October through April; average 640 inches of snow a year"},{"name":"Skyline Trail, Paradise","source":"https://www.nps.gov/mora/planyourvisit/paradise.htm","accessed":"2026-10-02","si":["hiking","adventure","romance"],"booking_route":"none needed","commission_status":"unknown","tier_absent_reason":"not-sold","blurb":"a 5.5-mile loop through subalpine meadows with views of Mount Rainier, glaciers and the Tatoosh Range; NPS: \"Snow can linger on trails well into June or even July\""},{"name":"Wildflower season at Paradise and Sunrise","source":"https://www.nps.gov/mora/planyourvisit/wildflower-status.htm","accessed":"2026-10-02","si":["hiking","romance","senior","family"],"booking_route":"none needed","commission_status":"unknown","tier_absent_reason":"not-sold","blurb":"\"many flowers will be blooming by mid-July, and by the first of August the meadows should be very impressive\"; 2026 reports ended September 3"},{"name":"Sunrise, Burroughs Mountain and Mount Fremont Lookout","source":"https://www.nps.gov/mora/planyourvisit/sunrise.htm","accessed":"2026-10-02","si":["hiking","adventure","wildlife"],"booking_route":"none needed","commission_status":"unknown","tier_absent_reason":"not-sold","blurb":"\"the highest point that can be reached by vehicle\" in the park at 6,400 feet, with Burroughs Mountain (4.7 or 7 miles) and the 5.6-mile Mount Fremont Lookout trail; Sunrise Road closed to private vehicles for the rest of 2026, open to walkers and cyclists"},{"name":"Longmire Historic District","source":"https://www.nps.gov/mora/planyourvisit/longmire.htm","accessed":"2026-10-02","si":["culture","senior","family","hiking"],"booking_route":"none needed","commission_status":"unknown","tier_absent_reason":"not-sold","blurb":"park headquarters from 1899 on James Longmire''s former homestead and mineral springs resort; the 1916 headquarters museum, a Wilderness Information Center and the Trail of the Shadows past the springs, open year-round"},{"name":"Carbon River temperate rainforest","source":"https://www.nps.gov/mora/planyourvisit/carbon-river-and-mowich.htm","accessed":"2026-10-02","si":["hiking","adventure","wildlife"],"booking_route":"none needed for day use; Ipsut Creek requires a wilderness permit","commission_status":"unknown","tier_absent_reason":"not-sold","blurb":"a corner of the park whose rainfall makes it \"resemble that of a temperate rainforest\"; the road \"was washed out by the 2006 Flood and is closed to vehicles past to the park boundary\"; Ipsut Creek Campground 5 miles in, open year-round; Chenuis Falls 7.4 miles round trip"},{"name":"Mowich Lake","source":"https://www.nps.gov/mora/planyourvisit/campgrounds.htm","accessed":"2026-10-02","si":["adventure","hiking"],"booking_route":"Wilderness Permit required","commission_status":"unknown","tier_absent_reason":"not-sold","blurb":"a subalpine lake reached via State Route 165, \"generally open mid-July to mid-October\"; in 2026 the 13 walk-in tent pads \"are not accessible by vehicle\" because of the Fairfax Bridge closure"},{"name":"Ohanapecosh old-growth forest and Silver Falls","source":"https://www.nps.gov/mora/planyourvisit/ohanapecosh.htm","accessed":"2026-10-02","si":["hiking","culture","wellness"],"booking_route":"none needed","commission_status":"unknown","tier_absent_reason":"not-sold","blurb":"old-growth Douglas-fir, red cedar and hemlock in the southeast corner, named for a Taidnapam (Upper Cowlitz) habitation site; in 2026 the campground and visitor centre are closed and Silver Falls \"cannot be hiked as a loop\" (reach it from Stevens Canyon Road, 1.2 mi, or SR 123, 0.6 mi); Grove of the Patriarchs closed"},{"name":"Timed entry: none in 2026","source":"https://www.nps.gov/mora/planyourvisit/fees.htm","accessed":"2026-10-02","si":["family","senior"],"booking_route":"none needed - pay at entrance; digital America the Beautiful pass via Recreation.gov","commission_status":"unknown","tier_absent_reason":"not-sold","blurb":"\"Mount Rainier National Park will not implement a timed entry reservation for any portion of the park in 2026\"; $30 private vehicle for 7 days, cashless entrances"},{"name":"Summit climbing permits","source":"https://www.nps.gov/mora/planyourvisit/climbing.htm","accessed":"2026-10-02","si":["expedition","adventure","sports"],"booking_route":"Pay.gov fee, then in-person registration","commission_status":"unknown","tier_absent_reason":"not-sold","blurb":"\"Each person in your party must pay $82\" (Climbing Cost Recovery Fee) via Pay.gov, then register in person at a wilderness information station within 24 hours in summer; NPS: \"Severe winter-like storms on the mountain are not uncommon during the summer\""},{"name":"Wilderness permits and the Wonderland Trail","source":"https://www.nps.gov/mora/planyourvisit/wilderness-permit.htm","accessed":"2026-10-02","si":["expedition","hiking","adventure"],"booking_route":"Recreation.gov (lottery and reservations); walk-up at Wilderness Information Centers","commission_status":"unknown","tier_absent_reason":"not-sold","blurb":"a permit is required year-round for every backcountry night; early access lottery opens in February, general reservations April 25; $12 per person per night plus $6 Recreation.gov fee; about a third of sites held for walk-up permits; Wonderland currently closed Carbon River Suspension Bridge to White River Campground"},{"name":"Ranger snowshoe walks, Paradise","source":"https://www.nps.gov/mora/planyourvisit/rangerprograms.htm","accessed":"2026-10-02","si":["family","adventure","senior"],"booking_route":"walk-in (first-come, first-served)","commission_status":"unknown","tier_absent_reason":"not-sold","blurb":"a 2-hour, 1.5-mile walk at 11 am, snowshoes provided, 25 people maximum, sign-up one hour before at the Jackson Visitor Center; 2026-27 \"Details coming soon\""},{"name":"Paradise Inn","source":"https://www.nps.gov/mora/planyourvisit/lodging.htm","accessed":"2026-10-02","si":["senior","romance","culture","hiking"],"booking_route":"own site (mtrainierguestservices.com, returned 403 this session) or 360-569-2275; engine not observed","commission_status":"unknown","tier_absent_reason":"not-sold","blurb":"the 1916 concessioner-run hotel at 5,420 feet with dining room and Sunday brunch, \"generally open mid-May through early October\", run by Rainier Guest Services"},{"name":"National Park Inn, Longmire","source":"https://www.nps.gov/mora/planyourvisit/restaurants.htm","accessed":"2026-10-02","si":["senior","romance","culture"],"booking_route":"own site (mtrainierguestservices.com) or 360-569-2275; engine not observed","commission_status":"unknown","tier_absent_reason":"not-sold","blurb":"the park''s year-round inn at 2,700 feet, with \"the only in-park dining facility that is open all year\""},{"name":"Alexander''s Lodge yurts, Ashford","source":"https://www.alexanderslodge.com/","accessed":"2026-10-02","si":["glamping","romance","culture"],"booking_route":"own site (direct reservations); 360-569-2300","commission_status":"unknown","tier_absent_reason":"not-sold","blurb":"a 1912 country inn with lodge rooms, two kitchen cabin suites and \"rustic yurts positioned 200 feet into the forest\" with shared bath; trout pond and a 20-minute trail to Copper Creek"},{"name":"Ashford Lodge vintage campers","source":"https://visitrainier.com/ashford-lodge/","accessed":"2026-10-02","si":["glamping","romance","group"],"booking_route":"own site ashfordlodge.co (Hospitable assets observed; engine not confirmed)","commission_status":"unknown","tier_absent_reason":"not-sold","blurb":"four year-round cabin-style suites plus three vintage camper trailers for glamping (Darla, Lois, Layla), summer season only, with hot showers, WiFi and a hot tub"},{"name":"Treehouse Mt. Rainier, Ashford","source":"https://treehousemtrainier.com/","accessed":"2026-10-02","si":["glamping","romance"],"booking_route":"Lodgify (treehousemtrainier.lodgify.com)","commission_status":"unknown","tier_absent_reason":"not-sold","blurb":"a 420-square-foot treehouse for two, 16 feet up among eight Douglas firs, designed by Pete Nelson''s Treehouse Masters team"},{"name":"Iron & Vine Treehouse, Ashford","source":"https://visitrainier.com/iron-and-vine-treehouse-2/","accessed":"2026-10-02","si":["glamping","romance"],"booking_route":"Airbnb (airbnb.com/h/ironandvinetreehouse); also VRBO","commission_status":"unknown","tier_absent_reason":"not-sold","blurb":"a canopy treehouse among Douglas firs and vine maples with kitchen, fireplace, record player and a suspended loft net; ships-ladder loft not suitable for children under 12"},{"name":"Happy Tails - The Huckleberry Yurt, Ashford","source":"https://visitrainier.com/happy-tails/","accessed":"2026-10-02","si":["glamping","romance"],"booking_route":"own site (happytailsmtrainier.com); engine not observed","commission_status":"unknown","tier_absent_reason":"not-sold","blurb":"a remodelled tiny cabin and yurt property on 6.6 acres under fir and cedar, sleeping three"},{"name":"The Alpine Airstream, Ashford","source":"https://visitrainier.com/alpine-airstream-glamping/","accessed":"2026-10-02","si":["glamping","romance"],"booking_route":"Airbnb","commission_status":"unknown","tier_absent_reason":"not-sold","blurb":"a 25-foot Airstream for two on half an acre of Douglas fir by the Nisqually River, with kitchen, hot tub, fire pit and river access"},{"name":"Wellspring, Ashford","source":"https://visitrainier.com/wellspring/","accessed":"2026-10-02","si":["glamping","wellness","romance","group"],"booking_route":"own site (wellspringspa.com); engine not observed","commission_status":"unknown","tier_absent_reason":"not-sold","blurb":"\"a woodland retreat and spa at the base of Mt Rainier\" on ten forest acres with log cabins, lodge rooms, camper cabins, a treehouse and a 30-foot yurt, plus a labyrinth and troll bridge"},{"name":"All Provided & Stress Free Camping, Ashford","source":"https://www.hipcamp.com/en-US/land/washington-all-provided-stress-free-camping-9mxhm0n2","accessed":"2026-10-02","si":["glamping","family","group"],"booking_route":"Hipcamp","commission_status":"unknown","tier_absent_reason":"not-sold","blurb":"furnished canvas and Coleman tents on 17 acres with bedding, heaters, shared kitchen and Starlink WiFi; honey-bucket toilets, showers at Alder Lake Park"},{"name":"Stargazer Dome at Wildlin Farm, Mineral","source":"https://visitrainier.com/the-stargazer-dome/","accessed":"2026-10-02","si":["glamping","romance"],"booking_route":"Airbnb","commission_status":"unknown","tier_absent_reason":"not-sold","blurb":"a two-storey geodome for two with king bed, kitchen, stargazing patio and a bay window facing Mt. Rainier; from $335 a night, two-night minimum"},{"name":"Lavender Passion Flower Farm, Mineral","source":"https://visitrainier.com/lavender-passion-flower-farm/","accessed":"2026-10-02","si":["glamping","romance","wellness"],"booking_route":"own site (lavenderpassionff.com); engine not observed","commission_status":"unknown","tier_absent_reason":"not-sold","blurb":"a lavender farm with a bungalow, cottage and glamping dome, shared bathhouse with outdoor shower, a rain-proof dining bubble and summer garden tours; walk to Mineral Lake"},{"name":"Wildfern Grove, Buckley","source":"https://www.hipcamp.com/en-US/land/washington-wildfern-grove-qeohrd5o","accessed":"2026-10-02","si":["glamping","wellness"],"booking_route":"Hipcamp","commission_status":"unknown","tier_absent_reason":"not-sold","blurb":"five hand-painted yurts, a bell tent and a Zome cabin on 40 forest acres of an intentional community, with a cedar hot tub, community kitchen and yoga space"},{"name":"Packwood Vintage Trailers","source":"https://whitepassbyway.com/listings/cozy-vintage-trailer-in-heart-of-packwood-2-of-3/","accessed":"2026-10-02","si":["glamping","romance"],"booking_route":"Airbnb","commission_status":"unknown","tier_absent_reason":"not-sold","blurb":"retro trailers in the heart of Packwood with king beds, propane heat and an outdoor hot shower"},{"name":"Cougar Rock Campground","source":"https://www.nps.gov/mora/planyourvisit/campgrounds.htm","accessed":"2026-10-02","si":["family","hiking"],"booking_route":"Recreation.gov","commission_status":"unknown","tier_absent_reason":"not-sold","blurb":"the park''s main reservable campground near Longmire: 178 individual and 5 group sites, late May to late September, with some first-come sites; the RV dump and fill station is closed for 2026"},{"name":"White River Campground","source":"https://www.nps.gov/mora/planyourvisit/campgrounds.htm","accessed":"2026-10-02","si":["family","hiking"],"booking_route":"Recreation.gov Scan and Pay (first-come)","commission_status":"unknown","tier_absent_reason":"not-sold","blurb":"88 sites, \"First-come, first-served only\" through the Recreation.gov app''s Scan and Pay; \"OPEN until early October, weather permitting\""},{"name":"Ohanapecosh Campground (closed 2026)","source":"https://www.nps.gov/mora/planyourvisit/campgrounds.htm","accessed":"2026-10-02","si":["family"],"booking_route":"closed","commission_status":"unknown","tier_absent_reason":"not-sold","blurb":"179 individual sites, \"CLOSED for 2026\" for a rehabilitation project running through November 2026"},{"name":"La Wis Wis Campground (Gifford Pinchot National Forest)","source":"https://whitepassbyway.com/listings/la-wis-wis-campground/","accessed":"2026-10-02","si":["family","hiking"],"booking_route":"Recreation.gov (campgrounds/233877)","commission_status":"unknown","tier_absent_reason":"not-sold","blurb":"a Forest Service campground with old-growth trees at the confluence of the Ohanapecosh and Clear Fork Cowlitz rivers, potable water, no utilities, group sites"},{"name":"Mounthaven Resort, Ashford","source":"https://visitrainier.com/mounthaven-resort/","accessed":"2026-10-02","si":["family","glamping","group"],"booking_route":"rezStream for cabins; \"we do not currently take RV reservations online\" - RV by phone/email","commission_status":"unknown","tier_absent_reason":"not-sold","blurb":"12 family cabins sleeping 2-9 and 16 RV sites on 7 cedar acres with two creeks and a pond, plus the Willow Camping Cabin"},{"name":"ELKAMP, Mineral","source":"https://www.elkamp.com/","accessed":"2026-10-02","si":["family","glamping"],"booking_route":"Campspot (campspot.com/book/elkamp)","commission_status":"unknown","tier_absent_reason":"not-sold","blurb":"25 old-growth forest sites with 30/50-amp RV hookups, tent sites, cabins and a 2018 Airstream rental, open mid-March through November"},{"name":"Packwood RV Park & Campground","source":"https://whitepassbyway.com/listings/packwood-rv-park-campground/","accessed":"2026-10-02","si":["family"],"booking_route":"own reservation system (engine not observed); (360) 494-5145","commission_status":"unknown","tier_absent_reason":"not-sold","blurb":"year-round, 77 RV sites with 30-amp full hookups and pull-throughs to 40 feet, plus tent sites on nearly 8 wooded acres at 12985 US Hwy 12"},{"name":"Alder Lake Park (Tacoma Power), Eatonville","source":"https://www.mytpu.org/community-environment/parks-recreation/alder-lake-park/","accessed":"2026-10-02","si":["family","group"],"booking_route":"GoingToCamp (tacomapower.goingtocamp.com)","commission_status":"unknown","tier_absent_reason":"not-sold","blurb":"35 full-hookup, 48 water-and-electric and 62 tent sites plus group camps; main loop open year-round except December 19-30"},{"name":"Mineral Lake Lions Den Campground","source":"https://www.visitrainier.com/pg/lodging","accessed":"2026-10-02","si":["family"],"booking_route":"not observed","commission_status":"unknown","tier_absent_reason":"not-sold","blurb":"\"94 campsites for tent and RV camping\" in Mineral, listed by Visit Rainier"},{"name":"RMI Expeditions, Ashford","source":"https://www.rmiguides.com/","accessed":"2026-10-02","si":["expedition","adventure","sports"],"booking_route":"own site; 1 (888) 892-5462","commission_status":"unknown","tier_absent_reason":"not-sold","blurb":"an NPS-authorized guide service founded over 55 years ago and based in Ashford; Mount Rainier Four Day Climb $2,595-$2,995, plus Five Day, Emmons, Kautz, Fuhrer Finger and Little Tahoma ($3,195) programmes"},{"name":"International Mountain Guides, Ashford","source":"https://www.mountainguides.com/","accessed":"2026-10-02","si":["expedition","adventure"],"booking_route":"own registration portal (signup.mountainguides.com)","commission_status":"unknown","tier_absent_reason":"not-sold","blurb":"an NPS-authorized guide service at 31111 SR 706 E operating \"since 1986\", now showing 2027 Mt. Rainier dates"},{"name":"Alpine Ascents International","source":"https://www.alpineascents.com/climbs/mount-rainier/","accessed":"2026-10-02","si":["expedition","adventure"],"booking_route":"own registration portal; 206.378.1927","commission_status":"unknown","tier_absent_reason":"not-sold","blurb":"a Seattle-based \"authorized mountain guide service of Mount Rainier National Park\" running 3-Day Muir, 4-Day Kautz and 4-Day Emmons climbs"},{"name":"Whittaker Mountaineering and BaseCamp, Ashford","source":"https://www.whittakermountaineering.com/pages/visit-basecamp","accessed":"2026-10-02","si":["adventure","expedition","culinary","group"],"booking_route":"not observed; (360) 569-2142","commission_status":"unknown","tier_absent_reason":"not-sold","blurb":"mountaineering, camping, winter and e-bike gear rental, Whittaker''s Bunkhouse with private rooms and bunks, the BaseCamp Bar & Grill and the Bunkhouse Cafe espresso stop for climbers"},{"name":"Mt. Rainier Scenic Railroad, Elbe","source":"http://mtrainierrailroad.com/","accessed":"2026-10-02","si":["family","culture","senior","group"],"booking_route":"Peek (book.peek.com)","commission_status":"unknown","tier_absent_reason":"not-sold","blurb":"restored steam locomotives on a logging-heritage line run by the Western Forest Industries Museum since 2022; Halloween trains (adults $40) and Steam into Christmas November 21-December 23 (adults from $48)"},{"name":"Northwest Trek Wildlife Park","source":"https://visitrainier.com/?s=northwest+trek","accessed":"2026-10-02","si":["wildlife","family","senior"],"booking_route":"not observed (nwtrek.org returned 403)","commission_status":"unknown","tier_absent_reason":"not-sold","blurb":"a 725-acre wildlife park with a free-roaming area of moose, bison and more toured by vehicle, fall Elk Bugling Tours, and Thomas Dambo''s Trolls exhibition October 15, 2026-January 24, 2027"},{"name":"Evergreen Escapes","source":"https://www.evergreenescapes.com/","accessed":"2026-10-02","si":["hiking","senior","group"],"booking_route":"Peek (book.peek.com)","commission_status":"unknown","tier_absent_reason":"not-sold","blurb":"\"The Pacific Northwest''s Original Outdoor Tour Outfitter Est. 2006\", running small-group Mount Rainier day trips and a 2-day tour from Seattle, a Rainier and Yakima Valley wine tour and a Longmire tour"},{"name":"Tours Northwest","source":"https://www.toursnorthwest.com/","accessed":"2026-10-02","si":["senior","family","group"],"booking_route":"FareHarbor (fareharbor.com/embeds/book/toursnorthwest)","commission_status":"unknown","tier_absent_reason":"not-sold","blurb":"a family-owned Seattle operator of 30+ years running a 10-11 hour Mt Rainier Tour from Seattle year-round, from $211, ages 5+, with SeaTac pickup"},{"name":"Wildberry Restaurant, Ashford","source":"http://www.rainierwildberry.com/html/wildberry.html","accessed":"2026-10-02","si":["culinary","culture","expedition","family"],"booking_route":"walk-in; Clover online ordering for pickup","commission_status":"unknown","tier_absent_reason":"not-sold","blurb":"\"A Taste of Two Worlds\" - an American mountain menu with select Nepalese dishes, run by Angdawa and Lhakpa Gelu Sherpa at 37718 SR 706 E; open May-October, closed Thursdays"},{"name":"Copper Creek Inn, Ashford","source":"https://www.coppercreekinn.com/","accessed":"2026-10-02","si":["culinary","romance","family"],"booking_route":"own online reservation system (engine not named); 360-569-2799","commission_status":"unknown","tier_absent_reason":"not-sold","blurb":"a historic resort known for its from-scratch restaurant and blackberry pie, with 12 woodland cabins and suites on 11 acres, many with hot tubs"},{"name":"Longmire Springs Brewing, Packwood","source":"https://visitrainier.com/longmire-springs-brewery/","accessed":"2026-10-02","si":["culinary","group","hiking"],"booking_route":"walk-in","commission_status":"unknown","tier_absent_reason":"not-sold","blurb":"an independent brewery at 112 Norman Way with a rotating lineup, live music, trivia, markets and food trucks; family and dog friendly"},{"name":"Headworks Brewing, Enumclaw","source":"https://headworksbrewing.com/","accessed":"2026-10-02","si":["culinary","group","family"],"booking_route":"reserved seating via own site; 253-263-5318","commission_status":"unknown","tier_absent_reason":"not-sold","blurb":"a family- and pet-friendly brewery at 1110 Marshall Avenue, home to Burger Buds, open daily"},{"name":"Mill Haus Cider Co, Eatonville","source":"https://drinkmillhaus.com/","accessed":"2026-10-02","si":["culinary","group"],"booking_route":"walk-in","commission_status":"unknown","tier_absent_reason":"not-sold","blurb":"award-winning craft cider \"in the foothills of Mount Rainier\", taproom since 2021 at 303 Center St E, with flatbreads, sliders and tacos"},{"name":"Rockridge Orchards & Cidery, Enumclaw","source":"https://visitrainier.com/rockridge-orchards-cidery/","accessed":"2026-10-02","si":["culinary","wine","family"],"booking_route":"walk-in","commission_status":"unknown","tier_absent_reason":"not-sold","blurb":"a family farm making sweet and hard ciders, wines and spirits, with a year-round produce stand and 47 brews for growler fills at 40709 264th Avenue SE"},{"name":"Pursuit Distilling Company, Enumclaw","source":"https://visitrainier.com/pursuit-distilling-company/","accessed":"2026-10-02","si":["culinary","culture"],"booking_route":"walk-in","commission_status":"unknown","tier_absent_reason":"not-sold","blurb":"a tasting room at 2321 Cole St with a one-of-a-kind continuous still, run by descendants of a Northwest timber family"},{"name":"Stringtown Cellars and Lavender Farm, Eatonville","source":"https://visitrainier.com/stringtown-cellars-lavender-farm/","accessed":"2026-10-02","si":["wine","culinary","romance"],"booking_route":"walk-in; call (360) 832-4743 for hours","commission_status":"unknown","tier_absent_reason":"not-sold","blurb":"wine tasting, a lavender gift shop and you-pick lavender (bloom typically July and August) at 39610 Eatonville Cutoff Rd"},{"name":"Elbe Market","source":"https://visitrainier.com/elbe-junction/","accessed":"2026-10-02","si":["culinary","family"],"booking_route":"walk-in","commission_status":"unknown","tier_absent_reason":"not-sold","blurb":"a 1906 country store serving coffee and ice cream beside Howard, a 12-foot Bigfoot statue in a cowboy hat"},{"name":"Historic Hotel Packwood","source":"https://www.historichotelpackwood.com/","accessed":"2026-10-02","si":["culture","romance","hiking"],"booking_route":"own online reservations; engine not observed","commission_status":"unknown","tier_absent_reason":"not-sold","blurb":"nine rooms with William Morris wallpapers at 104 Main Street West, an \"eco-conscious boutique experience\""},{"name":"Stormking Cabins & Spa, Ashford","source":"https://www.stormkingspa.com/","accessed":"2026-10-02","si":["romance","wellness"],"booking_route":"Cloudbeds (hotels.cloudbeds.com)","commission_status":"unknown","tier_absent_reason":"not-sold","blurb":"seven private cabins with hot tubs, fireplaces and on-site massage at 37311 SR 706 E; $360-$425 a night for two"}],"faq":[{"q":"Do I need a timed entry reservation for Mount Rainier in 2026?","a":"No. The NPS states that timed entry reservations are currently not required anywhere in the park and that the park will not implement a timed entry reservation for any portion of the park in 2026.","source":"https://www.nps.gov/mora/planyourvisit/fees.htm","accessed":"2026-10-02"},{"q":"Can I drive to Sunrise right now?","a":"No. As of the NPS update of September 24, 2026, Sunrise and Sunrise Road remain open to pedestrians and bicyclists and closed to private vehicles for the remainder of the 2026 season.","source":"https://www.nps.gov/mora/planyourvisit/conditions.htm","accessed":"2026-10-02"},{"q":"When are the wildflowers best?","a":"The NPS says that in most years many flowers are blooming by mid-July and by the first of August the meadows should be very impressive.","source":"https://www.nps.gov/mora/planyourvisit/wildflower-status.htm","accessed":"2026-10-02"},{"q":"What does it cost to climb Mount Rainier?","a":"The NPS climbing fee is $82 per person, plus $12 per person per night for a wilderness permit in summer. Guided climbs are offered by three authorized services; RMI posts its Four Day Climb at $2,595-$2,995.","source":"https://www.nps.gov/mora/planyourvisit/climbing.htm","accessed":"2026-10-02"},{"q":"Is there lodging inside the park?","a":"Yes. The National Park Inn at Longmire is open year-round and the 1916 Paradise Inn is generally open mid-May through early October, both run by Rainier Guest Services.","source":"https://www.nps.gov/mora/planyourvisit/lodging.htm","accessed":"2026-10-02"},{"q":"Which park campgrounds take reservations?","a":"Cougar Rock is reservable on Recreation.gov with some first-come sites; White River is first-come only; Ohanapecosh is closed for 2026; Mowich Lake walk-in sites need a wilderness permit.","source":"https://www.nps.gov/mora/planyourvisit/campgrounds.htm","accessed":"2026-10-02"}],"seo":{"meta_title":"Mount Rainier National Park: Paradise, Sunrise, Summit Climbs & Glamping | TravelWell","meta_description":"No timed entry in 2026. Paradise wildflowers, the Skyline Trail, guided summit climbs from Ashford, current closures, and treehouses, yurts and domes at the gates.","slug":"mount-rainier-national-park-washington","primary_keyword":"Mount Rainier National Park","jsonld_type":"TouristDestination"},"hero":{"query":"Mount Rainier National Park, Washington"}}'::jsonb, 99),
  ('crater-lake-oregon', '12A', 'Crater Lake National Park', 'United States', 'Caldera rim of America''s deepest lake', 'future', 'verified', 'mountainValley', 'The Pacific Northwest', '{"motoring","hiking","senior","family","group","parks"}', '{"dramatic","alpine","serene","remote"}', '{}', null, null, '{"safety":{"posture":"book-freely","source":"https://www.gov.uk/foreign-travel-advice/usa","verified":"2026-10-08"},"jewels":[{"name":"Scenic Rim Drive","source":"https://www.nps.gov/crla/planyourvisit/scenic-rim-drive.htm","accessed":"2026-10-03","si":["motoring","senior","family","hiking"],"booking_route":"none needed - included in the park entrance fee","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":1,"blurb":"\"33 miles (53 km) of lake views, panoramic vistas, forests and meadows\" with \"30 overlooks with ample car parking\" and \"access to five picnic areas, hikes of various difficulty, geologic formations and several waterfalls\"; \"Allow a minimum of two hours (including sight-seeing stops) to circumnavigate the lake\". West and East Rim Drives close around November 1 and \"reopen in stages beginning in May (depending on snowfall)\"."},{"name":"Sinnott Memorial Overlook","source":"https://www.nps.gov/crla/planyourvisit/things2do.htm","accessed":"2026-10-03","si":["culture","senior","family"],"booking_route":"none needed - included in the park entrance fee","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":2,"blurb":"At Rim Village: \"The oldest and most popular viewpoint in the park built specifically to offer a united view of the beauty the geologic story.\" Summer ranger programmes include \"Short talks on a variety of subjects at the Sinnott Memorial Overlook in Rim Village\"."},{"name":"Crater Lake Lodge","source":"https://explorecraterlake.com/stay-at-crater-lake/crater-lake-lodge/","accessed":"2026-10-03","si":["romance","senior","group","culture"],"booking_route":"own website booking or (866) 292-6720","commission_status":"unknown","commission":"hotel","tier_absent_reason":"not-established","wells":["stay"],"draw_rank":3,"blurb":"\"Opened in 1915\", \"71 hotel rooms and the Crater Lake Dining Room\" at Rim Village; 2026 season \"May 15th, 2026 - October 13th, 2026\"; \"ADA Bed Options\" in Standard Lodge Rooms. Run by the park concessioner, Explor Crater Lake; late-afternoon ranger talks are given \"on the patio with lake views or indoors near the fireplace\" (NPS ranger programmes page)."},{"name":"Garfield Peak Trail","source":"https://www.nps.gov/crla/planyourvisit/hiking.htm","accessed":"2026-10-03","si":["hiking","adventure"],"booking_route":"none needed - park trail","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":4,"blurb":"3.6 miles, 1,010 feet of gain: \"Trail begins in the trees but quickly opens to a meadow. Switchbacks weave views of the lake and valleys, craggy peaks and scree slopes.\" Most high trails are \"snow and ice covered December into June.\""},{"name":"Watchman Peak Trail","source":"https://www.nps.gov/crla/planyourvisit/hiking.htm","accessed":"2026-10-03","si":["hiking","family","romance"],"booking_route":"none needed - park trail","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":5,"blurb":"1.6 miles, 420 feet of gain, Moderate: \"An extremely crowded trail especially at sunset. Moderate ascent to a fire lookout.\""},{"name":"Mount Scott Trail","source":"https://www.nps.gov/crla/planyourvisit/hiking.htm","accessed":"2026-10-03","si":["hiking","adventure"],"booking_route":"none needed - park trail","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":6,"blurb":"4.4 miles, 1,250 feet of gain to \"The park''s highest peak at 8,929 ft (2,721 m) and the oldest at 425,000 years old.\""},{"name":"Crater Lake Trolley","source":"https://www.craterlaketrolley.net/","accessed":"2026-10-03","si":["senior","family","group","motoring"],"booking_route":"Peek (\"book your tour with Peek\") or 541-882-1896; day-of tickets at Rim Village (NPS)","commission_status":"unknown","commission":"operator","tier_absent_reason":"does-not-compete","wells":["activities","move"],"draw_rank":7,"blurb":"A park concessioner running \"daily trolley tours\" of the \"historic 33-mile Rim Drive\", \"typically begin in July and run through mid-September\", \"five to seven stops at significant overlooks\" (NPS). Its own site: tours \"LAST 2 HOURS\" and \"START AT THE RIM VILLAGE NEAR THE CRATERLAKE LODGE\"; Adults $44.00, Seniors (65+) and Military $42.00, Children 6-13 $25.00, under 6 free; one wheelchair per trolley with a day''s notice."},{"name":"Mazama Campground","source":"https://explorecraterlake.com/stay-at-crater-lake/mazama-campground/","accessed":"2026-10-03","si":["family","motoring","hiking","group"],"booking_route":"Recreation.gov (reservations July 1 - October 1, 2026); first come first serve late May - June 30, 2026","commission_status":"none","commission":"venue","tier_absent_reason":"not-established","wells":["stay"],"draw_rank":8,"blurb":"\"The 214 campsites each feature a picnic table, fire ring with a grill and a bear-resistant food locker\"; Tent $35.00, RV no hookups $35.00, electricity $48.00, full hookups $57.00; restrooms, gas station, potable water, dump station and \"showers that are available in Loop F\"; the Mazama Camper Store stocks \"groceries, propane, firewood, and gasoline.\" Operated by Explor Crater Lake."},{"name":"The Cabins at Mazama Village","source":"https://explorecraterlake.com/stay-at-crater-lake/the-cabins-at-mazama-village/","accessed":"2026-10-03","si":["family","senior"],"booking_route":"own website booking (iqwebbook) or (866) 292-6720","commission_status":"unknown","commission":"hotel","tier_absent_reason":"not-established","wells":["stay"],"draw_rank":9,"blurb":"2026 season \"May 8th, 2026 - October 4th, 2026\"; Standard cabins with \"2 Queen Beds\" and a \"private bath that feature a shower\", ADA cabins with \"1 Queen Bed\"; \"no phone, TV, and air conditioning.\" Beside Annie Creek Restaurant and the Mazama Village Store."},{"name":"Junior Ranger programme","source":"https://www.nps.gov/crla/planyourvisit/ranger-programs.htm","accessed":"2026-10-03","si":["family","wildlife"],"booking_route":"none needed - ask at a visitor center","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":10,"blurb":"\"Stop by a visitor center and ask for a Junior Ranger Book\"; children complete the required pages, return to the visitor center and \"receive a badge\". The NPS things-to-do page: \"Each day during summer, four times a day, kids get to discover Crater Lake National Park with a ranger.\""},{"name":"Ranger-guided snowshoe walks","source":"https://www.nps.gov/crla/planyourvisit/ranger-programs.htm","accessed":"2026-10-03","si":["ski","family","senior","group"],"booking_route":"none sold - contact the park, 541-594-3000, for schedules","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":11,"blurb":"\"Ranger-guided snowshoe walks are offered most years from late November through the end of April\"; \"No previous snowshoeing experience is necessary\"; \"Aside from the park entry fee, there is no cost for the snowshoe walk and snowshoes are provided free\"."},{"name":"Godfrey Glen Trail","source":"https://www.nps.gov/crla/planyourvisit/hiking.htm","accessed":"2026-10-03","si":["senior","family","hiking"],"booking_route":"none needed - park trail","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":12,"blurb":"1.1 miles, 50 feet of gain: \"An old trail with a new accessibility surface\", \"Recommended for all terrain wheelchairs with assistance\"; the accessibility page calls it \"the park''s fully accessible trail\". One of the few trails where leashed pets are allowed."},{"name":"Plaikni Falls Trail","source":"https://www.nps.gov/crla/planyourvisit/hiking.htm","accessed":"2026-10-03","si":["hiking","family","senior"],"booking_route":"none needed - park trail","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":13,"blurb":"2.0 miles, 100 feet of gain: \"An easy stroll through a forest to a waterfall fed by snowmelt\"; \"Accessible to all-terrain wheelchairs except for the last 1/4\"."},{"name":"The Pinnacles","source":"https://www.nps.gov/crla/planyourvisit/hiking.htm","accessed":"2026-10-03","si":["hiking","senior","family"],"booking_route":"none needed - park trail","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":14,"blurb":"0.8 miles, 10 feet of gain: \"Easy forest walk above a canyon filled with volcanic spires (pinnacles)\"; \"Accessible to all-terrain wheelchairs\"."},{"name":"Castle Crest Wildflower Trail","source":"https://www.nps.gov/crla/planyourvisit/hiking.htm","accessed":"2026-10-03","si":["wildlife","hiking","family"],"booking_route":"none needed - park trail","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":15,"blurb":"0.5 miles, 100 feet of gain: \"The trail loops around a spring-fed meadow which hosts over 200 wildflower species.\""},{"name":"Cleetwood Cove Trail (closed 2026-2028)","source":"https://www.nps.gov/crla/planyourvisit/cleetwood-cove.htm","accessed":"2026-10-03","si":["hiking","adventure"],"booking_route":"none - closed 2026-2028","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":16,"blurb":"\"a steep and strenuous hike. In 1.1 miles (1.7 km) the trail drops 700 feet (213 meters)\" - the only route to the shore, where \"Swimming, wading and fishing are permitted in the lake\" and boat tours leave. 🔴 \"This trail will be closed for a major rehabilitation project for the 2026, 2027, and 2028 seasons.\""},{"name":"Backcountry camping and the Pacific Crest Trail","source":"https://www.nps.gov/crla/planyourvisit/backcountry_camping.htm","accessed":"2026-10-03","si":["adventure","hiking"],"booking_route":"free permit in person at the Ranger Station, no more than 1 day ahead","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":17,"blurb":"\"A backcountry camping permit is required year-round for all overnight trips in the park.\" \"Permits are issued free of charge\" and \"must be obtained in person. They are not available over the phone, or more than 1 day in advance. The Ranger Station is located 100 yards southwest of the Steel Visitor Center.\" The Pacific Crest Trail crosses the park and is one of the few trails open to leashed pets."},{"name":"Crater Lake Lodge Dining Room","source":"https://explorecraterlake.com/dining/crater-lake-lodge-dining-room/","accessed":"2026-10-03","si":["culinary","romance","group"],"booking_route":"online reservations (Toast Tables) or (866) 292-6720","commission_status":"unknown","commission":"venue","tier_absent_reason":"does-not-compete","wells":["eat"],"draw_rank":18,"blurb":"Breakfast 7:00-10:00 am, lunch 11:00 am-2:00 pm, dinner 4:00-9:00 pm, \"May 15th, 2026 - October 13th, 2026\"; dinner reservations recommended up to a week ahead; parties of 12 or more are group reservations; small plates in the Great Hall and on the Terrace between meals; a certified green restaurant."},{"name":"Annie Creek Restaurant","source":"https://explorecraterlake.com/dining/annie-creek-restaurant/","accessed":"2026-10-03","si":["family","culinary"],"booking_route":"walk-in (no reservation method on the page)","commission_status":"unknown","commission":"venue","tier_absent_reason":"does-not-compete","wells":["eat"],"draw_rank":19,"blurb":"Mazama Village: \"Specialty sandwiches, pizza and, soups are some of the featured menu items\"; breakfast 7:00-10:30 am, lunch and dinner 11:00 am-9:00 pm, \"May 22nd, 2026 - October 1st, 2026\"; with the Annie Creek Scoop Shop, 11:00 am-7:00 pm."},{"name":"Rim Village Cafe","source":"https://explorecraterlake.com/dining/rim-village-cafe/","accessed":"2026-10-03","si":["family","senior"],"booking_route":"walk-in","commission_status":"unknown","commission":"venue","tier_absent_reason":"does-not-compete","wells":["eat"],"draw_rank":20,"blurb":"\"grab-and-go food like sandwiches, salads and snacks\"; 10:00 am-5:00 pm until May 15, then 9:00 am-8:00 pm from May 15, 2026; \"Closed for Christmas Day\"."},{"name":"Cosmos - Exploring the Pacific Northwest (9 days)","source":"https://www.tourradar.com/t/52232","accessed":"2026-10-03","si":["group","senior","motoring"],"booking_route":"TourRadar (tour code 8570|9)","commission_status":"commissioned","commission":"operator","tier_absent_reason":"does-not-compete","commission_pct_low":7,"commission_pct_high":7,"commission_basis":"published","wells":["activities","move"],"draw_rank":21,"blurb":"An escorted \"Exploring the Pacific Northwest\" by Cosmos, 9 days \"From Seattle to Portland\", \"All Ages Welcome\", from $2,389 (double occupancy); Day 5 \"Bend to Medford\" includes \"Crater Lake National Park visit\" and \"Crater Lake viewing.\""},{"name":"Crater Lake Resort, Fort Klamath","source":"https://www.craterlakeresort.com/","accessed":"2026-10-03","si":["family","motoring","glamping"],"booking_route":"own website booking (Newbook) or (541) 381-2349","commission_status":"unknown","commission":"hotel","tier_absent_reason":"not-established","wells":["stay"],"draw_rank":22,"blurb":"\"50711 OR-62, Fort Klamath, Oregon\", \"7 miles from the south gate of Crater Lake National Park\"; \"13 Cabins\" with \"full kitchens, decks, BBQs\", RV and tent sites, glamping tents, and \"Free canoes on Fort Creek\" with \"paddles and life jackets included\"; \"Open year-round\"."},{"name":"Crater Lake Resort glamping bell tents","source":"https://www.craterlakeresort.com/glamping","accessed":"2026-10-03","si":["glamping","family","romance"],"booking_route":"own website booking (Newbook) or (541) 381-2349","commission_status":"unknown","commission":"hotel","tier_absent_reason":"not-established","wells":["stay"],"draw_rank":23,"blurb":"\"4 Glamping Sites\" of \"Brand-new canvas bell tents\": \"1 queen bed + 2 twin beds\", \"Real linens. Real pillows. Lanterns inside.\"; \"No electricity, no water in-tent\"; \"Open May 15 - October 15\"; deposit of the first night, full refund if cancelled 30+ days before arrival."},{"name":"Crater Lake Resort RV Park","source":"https://www.craterlakeresort.com/rv-park","accessed":"2026-10-03","si":["motoring","family"],"booking_route":"own website booking (Newbook) or (541) 381-2349","commission_status":"unknown","commission":"hotel","tier_absent_reason":"not-established","wells":["stay"],"draw_rank":24,"blurb":"\"Full: water, 30/50-amp power, sewer. Partial: water + power.\" \"Most sites accommodate rigs up to 35 feet. All sites are back-in only\"; bathhouse with hot showers, \"On-site laundry\", Tesla Supercharger, general store; \"Open year-round\"; \"From $57/night\" partial, \"From $73.67/night\" full hookup."},{"name":"Diamond Lake RV Park","source":"https://diamondlake.net/stay-at-diamond-lake/rv-park/","accessed":"2026-10-03","si":["motoring","family","group"],"booking_route":"Campspot (campspot.com/book/diamondlakerv) or 541-793-3318","commission_status":"commissioned","commission":"affiliate","tier_absent_reason":"not-established","commission_pct_low":3,"commission_pct_high":3,"commission_basis":"published","wells":["stay"],"draw_rank":25,"blurb":"\"We have 110 full hookup sites with either 30 or 50 amp service\"; laundry, restrooms and showers; \"At just seven miles from Crater Lake National Park and three miles from The Lodge\"; \"All vehicles must be parked before dark.\" 541-793-3318."},{"name":"Diamond Lake Resort","source":"https://www.diamondlake.net/","accessed":"2026-10-03","si":["family","ski","adventure","group"],"booking_route":"own website booking (ResNexus) or (541) 793-3333","commission_status":"unknown","commission":"hotel","tier_absent_reason":"not-established","wells":["stay","activities"],"draw_rank":26,"blurb":"Cabins (\"rustic to luxury\") and motel & studios on Diamond Lake, \"located only seven miles\" from Crater Lake National Park; summer boat, bike, kayak and paddleboard rentals; winter cross-country skiing, cat skiing on Mt. Bailey, snow tubing, ice fishing and snowmobile rentals. 350 Resort Drive, Diamond Lake; (541) 793-3333."},{"name":"Diamond Lake Resort bike and boat rentals","source":"https://diamondlake.net/summer-recreation/bike-rentals/","accessed":"2026-10-03","si":["family","adventure"],"booking_route":"phone 541-793-3333 ext. 5 or in person at the Marina Store","commission_status":"unknown","commission":"operator","tier_absent_reason":"does-not-compete","wells":["gear","activities"],"draw_rank":27,"blurb":"\"Our fleet of ''Diamond Back'' mountain bikes are a great way to venture around the lake\" on a \"12 mile paved loop around Diamond Lake\"; \"1/2 Day (4 Hours): $30 plus $5/additional hour\" or \"$22/hour\"; the Marina Store also rents boats, paddle boats, patio boats, kayaks and paddleboards. Reserve at 541-793-3333 ext. 5."},{"name":"Diamond Lake Campground (Umpqua National Forest)","source":"https://www.recreation.gov/api/camps/campgrounds/231980","accessed":"2026-10-03","si":["family","group","motoring"],"booking_route":"Recreation.gov","commission_status":"none","commission":"venue","tier_absent_reason":"not-established","wells":["stay"],"draw_rank":28,"blurb":"\"Meandering along most of the east shore of the mile-high Diamond Lake, this large campground boasts spectacular views of both Mount Bailey and Mount Thielsen\"; \"238 sites, including double and standard sites\"; accessible flush toilets and showers, amphitheater, boat ramp, dump station; 14-night maximum stay."},{"name":"Union Creek Campground (Rogue River-Siskiyou National Forest)","source":"https://www.recreation.gov/api/camps/campgrounds/119140","accessed":"2026-10-03","si":["hiking","family"],"booking_route":"Recreation.gov, plus first-come sites","commission_status":"none","commission":"venue","tier_absent_reason":"not-established","wells":["stay"],"draw_rank":29,"blurb":"\"constructed in 1934 by the Civilian Conservation Corp. The campground is located 18 miles west of Crater Lake National Park and in the midst of an old growth forest.\" \"There are 73 campsites\", \"not recommended for trailers over 28 feet long\"; first-come sites available; Rogue Gorge and Natural Bridge interpretive trails nearby."},{"name":"Rogue Gorge and Natural Bridge","source":"https://www.recreation.gov/api/camps/campgrounds/119140","accessed":"2026-10-03","si":["hiking","family","senior"],"booking_route":"none needed - public trails","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":30,"blurb":"Two Forest Service interpretive trails beside Union Creek Campground: \"Rogue Gorge\" and \"Natural Bridge\" both have trails \"with views of the Upper Rogue River\" (Recreation.gov, Union Creek Campground)."},{"name":"Union Creek Resort","source":"https://www.unioncreekoregon.com/lodging/lodging-at-union-creek/","accessed":"2026-10-03","si":["family","group","romance"],"booking_route":"own website booking (ahlsmsworld) or 866.761.6630","commission_status":"unknown","commission":"hotel","tier_absent_reason":"not-established","wells":["stay"],"draw_rank":31,"blurb":"Has \"welcomed guests and travelers since 1922\" at 56484 Highway 62, Prospect - a \"Basecamp to Crater Lake\"; renovated Union Creek Lodge rooms (2014), \"17 authentic log cabins\" and larger vacation-rental cabins for groups; cash-free. Winter snowshoeing, skiing and snowmobiling listed."},{"name":"Beckie''s Cafe","source":"https://www.unioncreekoregon.com/dining/beckies-cafe/","accessed":"2026-10-03","si":["culinary","family","senior"],"booking_route":"walk-in","commission_status":"unknown","commission":"venue","tier_absent_reason":"does-not-compete","wells":["eat"],"draw_rank":32,"blurb":"\"Serving since in 1926, Beckie''s Café is famous for good reason: delicious, home-style food, great service, an awesome location just minutes from Crater Lake National Park, and our celebrated Beckie''s pies, made fresh daily.\" \"Daily 8:00 AM to 7:00 PM\"; the cafe and resort are \"listed on the National Register of Historic Places.\""},{"name":"The Lodge at Diamond Lake - Cafe and Mt. Bailey Room","source":"https://diamondlake.net/dining/the-lodge/","accessed":"2026-10-03","si":["culinary","family"],"booking_route":"walk-in","commission_status":"unknown","commission":"venue","tier_absent_reason":"does-not-compete","wells":["eat"],"draw_rank":33,"blurb":"\"The Café and Mt. Bailey Room\" in the Lodge at Diamond Lake Resort: breakfast, lunch and dinner, summer \"7 days a week | 7am - 9pm\", winter weekdays 8am-8pm and weekends 8am-9pm."},{"name":"South Shore Pizza","source":"https://diamondlake.net/dining/the-lodge/","accessed":"2026-10-03","si":["family","culinary","group"],"booking_route":"walk-in","commission_status":"unknown","commission":"venue","tier_absent_reason":"does-not-compete","wells":["eat"],"draw_rank":34,"blurb":"Diamond Lake Resort''s second restaurant, about a mile from the lodge: \"fresh, hand-made pizzas, brews, sandwiches, ice cream and more\"."},{"name":"Fairfield Inn & Suites by Marriott Klamath Falls","source":"https://hotelguides.com/attraction-maps/oregon/map-hotels-near-crater-lake-national-park-or.html","accessed":"2026-10-03","si":["family","senior","group"],"booking_route":"marriott.com (brand booking; not fetched)","commission_status":"commissioned","commission":"hotel","tier_absent_reason":"not-established","commission_pct_low":8,"commission_pct_high":10,"commission_basis":"benchmark","wells":["stay"],"draw_rank":35,"blurb":"Listed by HotelGuides at \"460 Timbermill Drive, Klamath Falls, OR 97601\", \"51 miles from Crater Lake National Park\" - at the edge of the ~50-mile ring. Marriott''s own page was not fetched (marriott.com blocks this route), so nothing else about the property is stated here."},{"name":"Holiday Inn Express & Suites Klamath Falls","source":"https://hotelguides.com/attraction-maps/oregon/map-hotels-near-crater-lake-national-park-or.html","accessed":"2026-10-03","si":["family","senior","group"],"booking_route":"ihg.com (brand booking; not fetched)","commission_status":"commissioned","commission":"hotel","tier_absent_reason":"not-established","commission_pct_low":10,"commission_pct_high":10,"commission_basis":"benchmark","wells":["stay"],"draw_rank":36,"blurb":"Listed by HotelGuides at \"2430 South 6th Street, Klamath Falls, OR 97601\", \"53 miles from Crater Lake National Park\" - just beyond the ~50-mile ring. IHG''s own page was not fetched, so nothing else about the property is stated here."},{"name":"Hilton Garden Inn Medford","source":"https://hotelguides.com/attraction-maps/oregon/map-hotels-near-crater-lake-national-park-or.html","accessed":"2026-10-03","si":["family","senior","group"],"booking_route":"hilton.com (brand booking; not fetched)","commission_status":"commissioned","commission":"hotel","tier_absent_reason":"not-established","commission_pct_low":10,"commission_pct_high":10,"commission_basis":"benchmark","wells":["stay"],"draw_rank":37,"blurb":"Listed by HotelGuides at \"1000 Welcome Way, I-5, Exit 27, Medford, OR 97504\", \"54 miles from Crater Lake National Park\" - in Medford, whose airport the NPS names as \"The closest airport with commercial flights\". Hilton''s own page was not fetched, so nothing else about the property is stated here."},{"name":"Water and layers for the high rim","source":"https://www.nps.gov/crla/planyourvisit/safety.htm","accessed":"2026-10-03","si":["hiking","family","senior"],"booking_route":"affiliate referral to rei.com (AvantLink)","commission_status":"commissioned","commission":"affiliate","tier_absent_reason":"does-not-compete","commission_pct_low":5,"commission_pct_high":5,"commission_basis":"published","wells":["gear"],"draw_rank":38,"blurb":"NPS: \"Carry with you more water than you normally drink.\" \"Dress in layers and keep dry, warm clothes nearby\"; \"Wear appropriate clothing outdoors, including hats, mittens, coats and footwear.\" \"Arrange activities to minimize your exposure to lightning danger. This often means hiking early in the day.\""},{"name":"Sun clothing for the summer trails","source":"https://www.nps.gov/crla/planyourvisit/safety.htm","accessed":"2026-10-03","si":["hiking","family"],"booking_route":"affiliate referral to rei.com (AvantLink)","commission_status":"commissioned","commission":"affiliate","tier_absent_reason":"does-not-compete","commission_pct_low":5,"commission_pct_high":5,"commission_basis":"published","wells":["gear"],"draw_rank":39,"blurb":"NPS: \"Wear lightweight, loose-fitting and light-colored clothing if you''ll be out in the heat\"; at altitude, \"Upon arrival, take time to acclimate to avoid, headaches, dizziness, and fainting.\" \"All trails begin above 4,000 feet in elevation\" (hiking page)."},{"name":"Tire chains for the winter road","source":"https://www.nps.gov/crla/planyourvisit/safety.htm","accessed":"2026-10-03","si":["motoring","ski"],"booking_route":"affiliate referral to rei.com (AvantLink)","commission_status":"commissioned","commission":"affiliate","tier_absent_reason":"does-not-compete","commission_pct_low":5,"commission_pct_high":5,"commission_basis":"published","wells":["gear"],"draw_rank":40,"blurb":"NPS: \"Use tire chains or traction tires when posted as being required (during snowy or icy periods).\" The park averages \"41 ft (12.5 m) of snow at park headquarters\" a year (weather page); the South and West entrances on Highway 62 stay open year-round."},{"name":"Food storage for camp and backcountry","source":"https://www.nps.gov/crla/planyourvisit/safety.htm","accessed":"2026-10-03","si":["adventure","hiking"],"booking_route":"affiliate referral to bearvault.com (AvantLink)","commission_status":"commissioned","commission":"affiliate","tier_absent_reason":"does-not-compete","commission_pct_low":8,"commission_pct_high":8,"commission_basis":"published","wells":["gear"],"draw_rank":41,"blurb":"NPS: \"Keep all food securely stored and out of reach from wildlife.\" Mazama Campground sites carry \"a bear-resistant food locker\" (Explor Crater Lake); in the backcountry the camper carries the storage. Bears: \"there are only five months when bears are active but even then, seeing one is not likely\" (NPS FAQ)."}],"faq":[{"q":"What is the entrance fee for Crater Lake National Park?","a":"A private vehicle is \"$30.00\" from May 22 to October 31 and \"$20.00\" from November 1 to May 21; a motorcycle $25.00 / $15.00; \"Per Person $15.00\" for a hiker, cyclist or pedestrian. The park''s annual pass \"costs $55.\"","source":"https://www.nps.gov/crla/planyourvisit/fees.htm","accessed":"2026-10-03"},{"q":"Do you need reservations for Crater Lake National Park?","a":"Not to enter: \"Although an entrance fee or NPS pass is required to enter Crater Lake National Park, vehicle reservations are not needed.\" Lodging is another matter - the concessioner says \"Accommodations in Crater Lake are at capacity the entire season. Book as soon as possible in order to secure reservations.\"","source":"https://www.nps.gov/crla/planyourvisit/fees.htm","accessed":"2026-10-03"},{"q":"Can you swim in Crater Lake?","a":"Normally yes, from the shore at Cleetwood Cove: \"Swimming, wading and fishing are permitted in the lake.\" But the Cleetwood Cove Trail - the only route to the water - \"will be closed for a major rehabilitation project for the 2026, 2027, and 2028 seasons.\"","source":"https://www.nps.gov/crla/planyourvisit/cleetwood-cove.htm","accessed":"2026-10-03"},{"q":"Are there boat tours on Crater Lake?","a":"Not at present: \"Due to major rehabilitation work on the Cleetwood Trail and lakeshore facilities, boat tours will not be available in 2026 or 2027.\" The alternative the NPS names is the Crater Lake Trolley''s two-hour Rim Drive tour, which \"typically begin in July and run through mid-September\".","source":"https://www.nps.gov/crla/planyourvisit/boat-and-trolley-tours.htm","accessed":"2026-10-03"},{"q":"How deep is Crater Lake?","a":"\"Crater Lake is 1,943 feet deep. It''s the deepest lake in the United States and the deepest volcanic lake in the world.\"","source":"https://www.nps.gov/crla/faqs.htm","accessed":"2026-10-03"},{"q":"Is Crater Lake National Park open year-round?","a":"\"The park is open year-round, 24 hours a day.\" Roads close \"with the first big snowstorm, or on November 1, whichever comes first\"; \"Typically, plowing begins on West Rim Drive in mid-April and all roads are ready to open by mid-July.\"","source":"https://www.nps.gov/crla/planyourvisit/hours.htm","accessed":"2026-10-03"},{"q":"What is the closest airport to Crater Lake National Park?","a":"\"The closest airport with commercial flights is in Medford, Oregon (75 miles from Park Headquarters).\" From Medford, \"Follow Highway 62 to the park''s West Entrance. Open year-round.\" \"There is no public transportation in the vicinity of the park.\"","source":"https://www.nps.gov/crla/planyourvisit/directions.htm","accessed":"2026-10-03"},{"q":"What is the best time to visit Crater Lake National Park?","a":"\"Summers at Crater Lake are short but sunny. July, August, and September are your best bets for warm, dry weather.\" \"In May, June, and October, sunny days alternate with periods of rain and snow.\"","source":"https://www.nps.gov/crla/planyourvisit/weather.htm","accessed":"2026-10-03"},{"q":"Can you take dogs to Crater Lake National Park?","a":"In limited places: Mazama Campground and all picnic areas, along roads within 50 feet of pavement, parking areas and paved walkways, and only these trails - Lady of the Woods, Godfrey Glen, Annie Spur, Grayback Drive and the Pacific Crest Trail. \"All leashes must be a maximum of six feet\", and pets \"are not permitted on the Cleetwood Cove Trail.\"","source":"https://www.nps.gov/crla/planyourvisit/pets.htm","accessed":"2026-10-03"},{"q":"Can you camp in Crater Lake National Park?","a":"Yes. Mazama Campground has 214 sites with \"a picnic table, fire ring with a grill and a bear-resistant food locker\", first come first serve from late May to June 30, 2026 and on reservation from July 1 to October 1, 2026, \"booked through our Recreation.gov website link\". Backcountry camping needs a free permit obtained in person.","source":"https://explorecraterlake.com/stay-at-crater-lake/mazama-campground/","accessed":"2026-10-03"}],"seo":{"meta_title":"Crater Lake National Park: Rim Drive, Lodge & Where to Stay | TravelWell","meta_description":"America''s deepest lake at 1,943 ft: the 33-mile Rim Drive, Crater Lake Lodge, Mazama camping, and the 2026-2028 Cleetwood Cove closure. Book early.","slug":"crater-lake-national-park-oregon","primary_keyword":"Crater Lake National Park","jsonld_type":"TouristDestination"},"hero":{"query":"Crater Lake National Park Wizard Island from the rim"}}'::jsonb, 100),
  ('north-cascades-washington', '12A', 'North Cascades National Park', 'United States', 'Glacier peaks, Diablo Lake and roadless Stehekin', 'future', 'verified', 'mountainValley', 'The Pacific Northwest', '{"hiking","adventure","motoring","family","group","senior","parks"}', '{"dramatic","alpine","wild","remote"}', '{}', null, null, '{"safety":{"posture":"book-freely","source":"https://www.gov.uk/foreign-travel-advice/usa","verified":"2026-10-08"},"jewels":[{"name":"North Cascades Highway (State Route 20)","source":"https://www.nps.gov/noca/planyourvisit/north-cascades-highway.htm","accessed":"2026-10-03","si":["motoring","senior","family","hiking"],"booking_route":"none needed - a public state highway; no entrance fee","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":1,"blurb":"\"Drive approximately 30 miles across the park on the North Cascades Highway (State Route 20), and experience the old growth forests, cascading waterfalls, and mountain scenery of North Cascades. Allow at least an hour to drive this beautiful, winding road.\" Highlights by milepost: North Cascades Visitor Center (119.9), Newhalem (120.5), Gorge Creek Falls (123.4), Diablo Lake Overlook (131.7), Happy Creek Forest Walk (134.3), Ross Lake Overlooks (136)."},{"name":"Diablo Lake Overlook","source":"https://www.nps.gov/noca/faqs.htm","accessed":"2026-10-03","si":["motoring","senior","family"],"booking_route":"none needed - a free roadside overlook","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":2,"blurb":"At mile 131.7 of State Route 20: \"Enjoy stunning views of the lake and surrounding mountain peaks.\" The NPS names it the best roadside sunrise and sunset spot: \"The most easily accessible area along State Route 20 with the best views for sunset and sunrise is Diablo Lake Overlook.\""},{"name":"Cascade Pass Trail","source":"https://www.nps.gov/noca/planyourvisit/day-hiking.htm","accessed":"2026-10-03","si":["hiking","adventure"],"booking_route":"none needed for a day hike; overnight needs a backcountry permit via Recreation.gov","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":3,"blurb":"At the end of the Cascade River Road: \"7.4 miles (12 km) roundtrip / 1,700 ft (518 m) elevation gain\" - \"A popular day hike with spectacular views of peaks and glaciers.\" The NPS adds that the trailhead \"is typically open mid-July, road dependent\" and backcountry permits for the Cascade Pass area \"are very competitive, especially for Sahale Glacier camp.\""},{"name":"Stehekin and Lake Chelan National Recreation Area","source":"https://www.nps.gov/noca/planyourvisit/stehekin.htm","accessed":"2026-10-03","si":["adventure","hiking","culture","family"],"booking_route":"none needed to visit; reached by Lady of the Lake ferry, float plane or on foot","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":4,"blurb":"\"Nestled at the headwaters of Lake Chelan, the third deepest lake in the United States\"; \"There are no roads that lead into Stehekin. Connected to the outside world only by foot, boat, or plane.\" A hub for \"the 61,949-acre Lake Chelan National Recreation Area\". For 2026: \"The North Cascades Lodge at Stehekin is closed for the 2026 summer season\"; no cell reception, no ATM."},{"name":"Thunder Knob Trail","source":"https://www.nps.gov/noca/planyourvisit/day-hiking.htm","accessed":"2026-10-03","si":["hiking","family"],"booking_route":"none needed - free park trail","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":6,"blurb":"Mile Post 130: \"3.7 miles (6 km) roundtrip / 680 ft (207 m) elevation gain\" - \"A popular trail to a view of Diablo Lake.\""},{"name":"Happy Creek Forest Walk","source":"https://www.nps.gov/noca/planyourvisit/accessibility.htm","accessed":"2026-10-03","si":["senior","family","hiking"],"booking_route":"none needed - free park trail","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":7,"blurb":"Mile Post 134: \".03 mile (.05 km) loop / 42 ft (13 m) elevation gain\" - \"Stroll through the forest along a cascading creek\", with an optional 2.6-mile round-trip spur to a waterfall. The NPS lists it as a \"fully accessible boardwalk\" path: \"a 1/3 mile (1/2 kilometer) loop through ancient forest.\""},{"name":"North Cascades Visitor Center and Sterling Munro Trail","source":"https://www.nps.gov/noca/planyourvisit/visitorcenters.htm","accessed":"2026-10-03","si":["family","senior","group","hiking"],"booking_route":"none needed - free; group presentations by prior arrangement","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":8,"blurb":"Near milepost 120 by Newhalem: \"Relief map of the park and surrounding area, exhibit room featuring multimedia exhibits on the park''s natural and cultural history\"; a theater, \"Several short, accessible interpretive trails\", and \"Special presentations available for school and other groups by prior arrangement.\" From the Sterling Munro Boardwalk, \"View the Picket Range\". (360) 854-7200."},{"name":"Backcountry permits for the Stephen Mather Wilderness","source":"https://www.nps.gov/noca/planyourvisit/backcountry-reservations.htm","accessed":"2026-10-03","si":["adventure","hiking","group"],"booking_route":"Recreation.gov reservation, or walk-up permit at the Wilderness Information Center, 7280 Ranger Station Rd., Marblemount","commission_status":"unknown","commission":"venue","tier_absent_reason":"does-not-compete","wells":["activities"],"draw_rank":9,"blurb":"\"Backcountry permits are required year-round in North Cascades National Park for all overnight trips.\" About 60% of backcountry sites are reservable on Recreation.gov (2026: early-access lottery March 2-13, general on-sale April 29 at 7 am Pacific); the rest are walk-up permits from the Wilderness Information Center in Marblemount. Recreation fee \"Adults (16 and older) - $10 per person\", youth free, plus a \"$6 non-refundable\" reservation fee."},{"name":"Junior Ranger Program","source":"https://www.nps.gov/noca/learn/kidsyouth/index.htm","accessed":"2026-10-03","si":["family","group"],"booking_route":"none needed - free, at park visitor centers","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":10,"blurb":"\"A dynamic new Junior Ranger Program is now available for kids and families visiting their national park. Four age-appropriate booklets introduce the unique natural and cultural history of the North Cascades through a series of fun activities.\" Booklets and badges are picked up at park visitor and information centers."},{"name":"Colonial Creek North and South Campgrounds","source":"https://www.nps.gov/noca/planyourvisit/camping.htm","accessed":"2026-10-03","si":["hiking","family","motoring"],"booking_route":"Recreation.gov or 1-877-444-6777 in season; first-come, first-served outside it","commission_status":"unknown","commission":"venue","tier_absent_reason":"not-established","wells":["stay"],"draw_rank":11,"blurb":"\"Colonial Creek Campground is a remote, yet bustling campground nestled in old growth forest with trail and lake access\" on Diablo Lake; \"Colonial Creek - $24 per night\". Ten walk-in, tent-only sites (#64-#73) at Colonial Creek South stay open year-round, first-come, first-served, \"with no fee, no water, and no trash services\". RV dump station at Colonial Creek South in season."},{"name":"Ross Dam Trail","source":"https://www.nps.gov/noca/planyourvisit/day-hiking.htm","accessed":"2026-10-03","si":["hiking","family","culture"],"booking_route":"none needed - free park trail","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":12,"blurb":"Mile Post 134: \"2.5 miles (3.9 km) roundtrip / 532 ft (162 m) elevation gain\" - \"Hike this moderate trail to walk across the historic Ross Dam. Option for a longer hike or backpack along Ross Lake.\""},{"name":"Sourdough Mountain Trail","source":"https://www.nps.gov/noca/planyourvisit/day-hiking.htm","accessed":"2026-10-03","si":["hiking","adventure"],"booking_route":"none needed - free park trail","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":13,"blurb":"Mile Post 126: \"10.4 miles roundtrip (16.7 km) / 4,870 ft (1,484 m) elevation gain\" - \"A difficult trail with spectacular views of peaks and lakes.\""},{"name":"Hidden Lake Trail","source":"https://www.nps.gov/noca/planyourvisit/day-hiking.htm","accessed":"2026-10-03","si":["hiking","adventure","culture"],"booking_route":"none needed - free park trail","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":14,"blurb":"Off the Cascade River Road: \"9 miles (14.5 km) roundtrip / 2,900 ft (884 m) elevation gain\" - \"A steep hike to a small mountain lake and historic fire lookout.\""},{"name":"Newhalem Creek Campground","source":"https://www.nps.gov/noca/faqs.htm","accessed":"2026-10-03","si":["motoring","family","senior"],"booking_route":"Recreation.gov or 1-877-444-6777","commission_status":"unknown","commission":"venue","tier_absent_reason":"not-established","wells":["stay"],"draw_rank":15,"blurb":"\"Newhalem Campground is a comfortable facility close to town, the Visitor Center, and the Skagit River.\" The NPS says it \"has the most sites for larger RVs\" (sites that allow RVs \"can generally accommodate a total combined length of 20-50 feet\"); RV dump station near the exit in season; \"none of the campsites within the park have RV hookups\" and no park campground has showers."},{"name":"Goodell Creek Campground","source":"https://www.nps.gov/noca/planyourvisit/camping.htm","accessed":"2026-10-03","si":["hiking","river","family"],"booking_route":"Recreation.gov or 1-877-444-6777 in season; first-come, first-served outside it","commission_status":"unknown","commission":"venue","tier_absent_reason":"not-established","wells":["stay"],"draw_rank":16,"blurb":"\"Goodell Creek Campground is situated in lush, old growth forest on the banks of the Skagit River\"; \"Goodell Creek - $20 per night\". One of the campgrounds that \"remain open year-round for first-come, first-served camping outside the operational season with no fee, no water, and no trash services: Goodell Creek (19 sites)\"."},{"name":"Lower Goodell Creek Group Campground","source":"https://www.nps.gov/noca/planyourvisit/camping.htm","accessed":"2026-10-03","si":["group","family","hiking"],"booking_route":"Recreation.gov or 1-877-444-6777","commission_status":"unknown","commission":"venue","tier_absent_reason":"not-established","wells":["stay"],"draw_rank":17,"blurb":"\"Lower Goodell Creek Group campsite is a convenient campground on the banks of Goodell Creek that accommodates large groups.\" Group campsites can be reserved \"one year in advance\" on Recreation.gov, against six months for individual sites."},{"name":"Hozomeen","source":"https://www.nps.gov/noca/planyourvisit/directions.htm","accessed":"2026-10-03","si":["adventure","overland","hiking"],"booking_route":"none needed - free campground (nps.gov/noca/planyourvisit/fees.htm)","commission_status":"none","tier_absent_reason":"not-sold","wells":["stay","activities"],"draw_rank":18,"blurb":"\"Visit remote Hozomeen at the north end of Ross Lake\"; \"Hozomeen campground - Free.\" Reached only by \"The Silver-Skagit Road to Hozomeen\", which \"provides the only road access to the Ross Lake shoreline. This 37 mile (60 km) gravel road connects with B.C. Highway 1 (Exit 168) near Hope, British Columbia.\""},{"name":"Fishing in the Skagit and the park lakes","source":"https://www.nps.gov/noca/planyourvisit/fishing.htm","accessed":"2026-10-03","si":["river","wildlife","adventure"],"booking_route":"none needed in the park - a Washington State fishing licence is required (WDFW)","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":19,"blurb":"\"The Skagit River, one of Washington''s major watersheds, is home to seven species of anadromous fish (five salmon species, steelhead, and cutthroat trout) and freshwater trout and char.\" A Washington State licence is required and \"Fishing licenses are not sold at any visitor or information station in the park complex, and you must obtain a license before visiting.\""},{"name":"Ross Lake Resort","source":"https://www.rosslakeresort.com/stay","accessed":"2026-10-03","si":["adventure","romance","family"],"booking_route":"own website accommodation lottery list, plus a last-minute availability table","commission_status":"unknown","commission":"hotel","tier_absent_reason":"not-established","wells":["stay"],"draw_rank":5,"blurb":"\"In existence since 1952, Ross Lake Resort is nestled in the heart of the North Cascade Mountains and is comprised of fifteen floating cabins and a marina\"; \"There is no road access to Ross Lake Resort.\" 2026 season June 11 - October 31. It \"operates under a concession contract within North Cascades National Park\"; cabins are filled by an annual lottery list. The NPS names it as overnight lodging in the park, 206-486-3751."},{"name":"Ross Lake Resort Equipment Rentals","source":"https://www.rosslakeresort.com/equipment-rentals","accessed":"2026-10-03","si":["adventure","family","river"],"booking_route":"first-come, first-served reservations with the resort","commission_status":"unknown","commission":"operator","tier_absent_reason":"does-not-compete","wells":["gear","activities"],"draw_rank":20,"blurb":"\"We rent motorboats, canoes, kayaks, paddle boards, and fishing rods to all visitors to Ross Lake\"; \"All equipment rentals include life jackets/PFDs.\" Daily rates read: motor boat $190.00 + tax (fuel included), canoe $80.00 + tax, single kayak $90.00 + tax, double kayak $119.00 + tax. \"No day-use motor boat or canoe rentals Friday-Sunday or on holidays\"; no canoe or kayak rentals to parties with children under three."},{"name":"Skagit Tours - Diablo Lake boat tours","source":"https://ncascades.org/signup/programs/skagit-tours/","accessed":"2026-10-03","si":["senior","family","group"],"booking_route":"own website registration or (360) 854-2599","commission_status":"unknown","commission":"operator","tier_absent_reason":"does-not-compete","wells":["activities"],"draw_rank":21,"blurb":"\"North Cascades Institute, in partnership with Seattle City Light, offers visitors fun, interactive tours of the Upper Skagit Valley and North Cascades National Park.\" The Diablo Lake & Lunch Tour aboard the Alice Ross IV lasts 2.5-3 hours and ran \"Wednesday - Sunday, July 3 - September 7\" in 2026; afternoon and fall morning cruises last about 2 hours. \"Diablo Lake Boat Tours are wheelchair accessible!\" (360) 854-2599."},{"name":"Wildland Trekking - Ross Lake Traverse in the North Cascades","source":"https://wildlandtrekking.com/trips/ross-lake-backpacking-trip/","accessed":"2026-10-03","si":["group","hiking","adventure","senior"],"booking_route":"Wildland sells direct - own website or 800-715-4453","commission_status":"unknown","commission":"operator","tier_absent_reason":"does-not-compete","wells":["activities"],"draw_rank":22,"blurb":"A guided backpacking trip of \"5 Days, 4 Nights\", \"from $2835\": \"This multi-day hiking trip in North Cascades National Park begins with a pickup at your hotel in Seattle\", along Ruby Arm and over Hidden Hand Pass to Hozomeen Lake. \"Group Size 1-5 Guests\"; \"Trip Begins Seattle, WA\"; \"Permit applications open on February 1 each year.\" Wildland also lists a 4-day \"Wonders of the North Cascades\" and a 3-day \"Cascade Pass and Sahale Glacier\" trip. Wildland has been owned by Intrepid Travel since 26 January 2022 (handoff/US-PARKS-TOUR-OPERATORS-2026-10-03.json, via Skift)."},{"name":"North Cascades Environmental Learning Center","source":"https://ncascades.org/discover/north-cascades-environmental-learning-center/","accessed":"2026-10-03","si":["group","family","senior","wellness"],"booking_route":"own website (Base Camp lodging, Conferences & Retreats request form) or (360) 854-2599","commission_status":"unknown","commission":"hotel","tier_absent_reason":"not-established","wells":["stay","activities"],"draw_rank":23,"blurb":"\"A field campus in North Cascades National Park\" on the north shore of Diablo Lake, \"Operated by North Cascades Institute in partnership with the National Park Service and the City of Seattle\": 16 buildings, \"Overnight lodging for up to 92 participants\", \"A lakeside dining hall\", \"A dock on Diablo Lake for paddling adventures\" and \"ADA-accessible facilities and pathways\"; programmes include \"family camps, boat tours, photography and art retreats, conferences and group retreats.\""},{"name":"Lady of the Lake (Lake Chelan Boat Company)","source":"https://ladyofthelake.com/","accessed":"2026-10-03","si":["group","senior","family","adventure"],"booking_route":"own website ticketing (RESERVE YOUR TICKETS NOW)","commission_status":"unknown","commission":"operator","tier_absent_reason":"does-not-compete","wells":["move","activities"],"draw_rank":24,"blurb":"\"Year Round Ferry Service To Stehekin, Holden Village, & Upper Lake Chelan\": same-day round trips, overnight and one-way tickets, Stehekin activity packages, and private charters \"for all occasions: weddings, receptions, birthdays, reunions\". The NPS lists the Lake Chelan Boat Company among companies permitted in the park complex, 509-682-4584, and names passenger ferry service \"from Chelan on U.S. Route 97\"."},{"name":"North Cascades River Expeditions","source":"https://www.riverexpeditions.com/","accessed":"2026-10-03","si":["river","family","adventure","group"],"booking_route":"phone 1-800-634-8433 or email (rafting@cftinet.com)","commission_status":"unknown","commission":"operator","tier_absent_reason":"does-not-compete","wells":["activities"],"draw_rank":25,"blurb":"\"Family Friendly Whitewater: Upper Skagit\", plus Sauk, Methow and Tieton trips; \"We thank Mt. Baker-Snoqualmie National Forest, Wenatchee National Forest, and North Cascades National Park for allowing us to operate on their lands.\" Arlington, WA; 1-800-634-8433. The NPS lists it under \"Raft, Float, and Fishing Trips\"."},{"name":"North Cascades Mountain Guides","source":"https://www.ncmountainguides.com/","accessed":"2026-10-03","si":["adventure","ski","hiking"],"booking_route":"own website trip pages","commission_status":"unknown","commission":"guide","tier_absent_reason":"does-not-compete","wells":["activities"],"draw_rank":26,"blurb":"Climbing and skiing trips listed under \"North Cascades National Park\", \"Washington Pass\", \"Mount Shuksan\" and \"Mazama Rock Climbing\", plus AIARE avalanche courses and \"Crevasse Rescue and Glacier Travel\". The NPS lists it among permitted guides, 509-996-3194."},{"name":"Winthrop / N. Cascades National Park KOA Holiday","source":"https://koa.com/campgrounds/winthrop/","accessed":"2026-10-03","si":["motoring","family","group"],"booking_route":"koa.com online reservation or 1-509-996-2258","commission_status":"unknown","commission":"hotel","tier_absent_reason":"not-established","wells":["stay"],"draw_rank":27,"blurb":"\"Located at the base of the North Cascades National Park, Winthrop KOA is your basecamp\"; \"1 mile east of Winthrop on SR 20/Cascade Loop Scenic Hwy\", 1114 State Route 20. \"Open May 15 to October 25\"; \"RV Sites with a KOA Patio\", \"Deluxe Cabins with full baths\", \"Premium Tent Sites\", \"Group meeting facilities\"; check-in 3:00 pm, check-out 11:00 am. Reserve: 1-509-996-2258."},{"name":"Pearrygin Lake State Park","source":"https://parks.wa.gov/find-parks/state-parks/pearrygin-lake-state-park","accessed":"2026-10-03","si":["family","hiking","motoring"],"booking_route":"Washington State Parks reservations online or (888) 226-7688","commission_status":"unknown","commission":"venue","tier_absent_reason":"not-established","wells":["stay","activities"],"draw_rank":28,"blurb":"625 Bear Creek Rd, Winthrop: \"a perfect escape to enjoy camping, hiking, swimming, or even snowshoeing and Nordic skiing. With 1,186 acres to enjoy\"; amenities include accessible campsites, showers, a trailer dump, boat ramp and dock; cabins and a vacation house to rent. Discover Pass one-day $10, annual $45. (509) 996-2370."},{"name":"Bell tent glamping at Pearrygin Lake (Glamping Hub)","source":"https://glampinghub.com/unitedstatesofamerica/pacificwest/washington/winthrop/dreamy-washington-glamping-bell-tent-rental-lake-access-winthrop/","accessed":"2026-10-03","si":["glamping","family"],"booking_route":"Glamping Hub","commission_status":"none","commission":"affiliate","tier_absent_reason":"not-established","commission_basis":"published","wells":["stay"],"draw_rank":29,"blurb":"A Winthrop bell-tent rental \"Located directly on the shores of Pearrygin Lake State Park and 1 hour from North Cascades NP\"; the site has \"three fishing docks, a swimming beach, a kids'' playground\" and rents kayaks and paddleboards; check-in 2:00-10:00 PM, check-out 11:00 AM. Listed as new with no reviews."},{"name":"Sun Mountain Lodge","source":"https://www.sunmountainlodge.com/","accessed":"2026-10-03","si":["romance","wellness","group","senior"],"booking_route":"own website booking (Reserve)","commission_status":"unknown","commission":"hotel","tier_absent_reason":"not-established","wells":["stay","eat","beauty"],"draw_rank":30,"blurb":"Winthrop: \"With more than 1,500 acres of magnificent wilderness as your playground and Patterson Lake adjacent to thousands of acres of national forest and the North Cascades National Park, Sun Mountain Lodge offers outdoor adventures year-round\"; the Main Lodge, Mt. Gardner and Mt. Robinson buildings and cabins at Patterson Lake; \"a spa, multiple dining options, and outdoor adventures including, hiking, skiing, and horseback riding\"; meetings and weddings."},{"name":"Freestone Inn & Cabins","source":"https://www.freestoneinn.com/","accessed":"2026-10-03","si":["romance","family","ski"],"booking_route":"own website (CHECK AVAILABILITY)","commission_status":"unknown","commission":"hotel","tier_absent_reason":"not-established","wells":["stay"],"draw_rank":31,"blurb":"\"The Freestone Inn is located just 15 miles west of Winthrop in Mazama, Washington\"; lodge rooms with gas fireplaces and private decks, and pet-friendly cabins with \"apartment-sized kitchens\". \"Freestone Inn Restaurants are closed indefinitely.\""},{"name":"Hampton Inn Chilliwack","source":"https://hotelguides.com/attraction-maps/washington/map-hotels-near-north-cascades-national-park-wa.html","accessed":"2026-10-03","si":["family","senior","overland"],"booking_route":"hilton.com (brand booking; not fetched)","commission_status":"commissioned","commission":"hotel","tier_absent_reason":"not-established","commission_pct_low":10,"commission_pct_high":10,"commission_basis":"benchmark","wells":["stay"],"draw_rank":32,"blurb":"Listed by HotelGuides at \"8050 Lickman Road, Chilliwack, BC V2R 3Z9\", \"45 miles from North Cascades National Park\" - on the British Columbia side, where the NPS says the gravel Silver-Skagit Road to Hozomeen \"connects with B.C. Highway 1 (Exit 168) near Hope\". Hilton''s own page was not fetched, so nothing else about the property is stated here."},{"name":"Holiday Inn Express & Suites Chilliwack","source":"https://hotelguides.com/attraction-maps/washington/map-hotels-near-north-cascades-national-park-wa.html","accessed":"2026-10-03","si":["family","senior","overland"],"booking_route":"ihg.com (brand booking; not fetched)","commission_status":"commissioned","commission":"hotel","tier_absent_reason":"not-established","commission_pct_low":10,"commission_pct_high":10,"commission_basis":"benchmark","wells":["stay"],"draw_rank":33,"blurb":"Listed by HotelGuides at \"8114 Young Road, Chilliwack, BC V2P 0C4\", \"43 miles from North Cascades National Park\" - the British Columbia approach to Hozomeen and Ross Lake. IHG''s own page was not fetched, so nothing else about the property is stated here."},{"name":"Upriver Grill & Taproom","source":"https://uprivergrill.com/","accessed":"2026-10-03","si":["culinary","family"],"booking_route":"walk-in; phone 360.873.4221","commission_status":"unknown","commission":"venue","tier_absent_reason":"does-not-compete","wells":["eat"],"draw_rank":34,"blurb":"60084 State Rte 20, Marblemount: \"we believe that great food starts with fresh, locally sourced ingredients. Our menu features a delightful fusion of classic American dishes and innovative recipes\"; open \"Monday - Sunday 11 am to 8 pm\"; 360.873.4221. The Concrete chamber places it \"along Hwy 20 at the western gateway to North Cascades National Park\" and notes it is open seasonally."},{"name":"Mondo Restaurant","source":"https://concrete-wa.com/?p=4253","accessed":"2026-10-03","si":["culinary","family"],"booking_route":"walk-in; dine-in and takeout","commission_status":"unknown","commission":"venue","tier_absent_reason":"does-not-compete","wells":["eat"],"draw_rank":35,"blurb":"60102 State Rte 20, Marblemount: \"a cozy, casual eatery... serving a flavorful fusion of American and Korean-inspired cuisine\" - \"burgers, kimchi-influenced dishes, teriyaki plates, bibimbap, gyoza and more\"; listed hours 11:00 AM-8:30 PM Mon-Thu, 8:00 AM-9:00 PM Fri-Sun, \"hours may fluctuate seasonally\". (Concrete chamber listing; own site not fetched.)"},{"name":"Karina''s Deja Brew","source":"https://concrete-wa.com/?p=4283","accessed":"2026-10-03","si":["culinary","motoring"],"booking_route":"walk-up or drive-thru","commission_status":"none","commission":"venue","tier_absent_reason":"does-not-compete","wells":["eat"],"draw_rank":36,"blurb":"60103 State Rte 20, Marblemount: \"a charming, locally loved coffee shop and café nestled right on State Route 20\" with \"freshly brewed espresso drinks, specialty lattes... pastries, light bites, outdoor seating, and casual walk-up or drive-thru service\"; (360) 301-6950. (Concrete chamber listing.)"},{"name":"Stehekin Pastry Company","source":"https://www.stehekinpastry.com/","accessed":"2026-10-03","si":["culinary","family","hiking"],"booking_route":"walk-in bakery; cabins by email (stehekinreservations@gmail.com)","commission_status":"unknown","commission":"venue","tier_absent_reason":"does-not-compete","wells":["eat","stay"],"draw_rank":37,"blurb":"\"The Pastry Company is where the Valley Gathers. Every delicious item is made by hand\"; \"If you have been to Stehekin then most likely, you have been to the Pastry Company\"; it also rents the Stehekin Log Cabins and does event catering. Reached only by boat, plane or trail, like all of Stehekin."},{"name":"Old Schoolhouse Brewery","source":"https://www.oldschoolhousebrewery.com/","accessed":"2026-10-03","si":["culinary","hiking"],"booking_route":"walk-in","commission_status":"unknown","commission":"venue","tier_absent_reason":"does-not-compete","wells":["eat"],"draw_rank":38,"blurb":"Pub at 155 Riverside Avenue, Winthrop - \"Come Enjoy Winthrop''s Only Riverside Seating\" on the Chewuch River - with locations in Twisp and the Mazama Public House \"At the Trailhead in Mazama\"; open 7 days a week. Brewery 509-996-3183."},{"name":"Rocking Horse Bakery","source":"https://www.rockinghorsebakery.com/","accessed":"2026-10-03","si":["culinary","family"],"booking_route":"walk-in","commission_status":"none","commission":"venue","tier_absent_reason":"does-not-compete","wells":["eat"],"draw_rank":39,"blurb":"265 Riverside Avenue, Winthrop: \"Delectable handmade pastries, beautiful, smooth espresso drinks, signature breads, made-from-scratch sandwiches, and salads\"; \"Whenever possible, we use locally grown or produced ingredients.\" Current hours read: \"open from 7AM to 2PM Thursday through Monday.\" (509) 996-4241."},{"name":"Three Fingered Jack''s Saloon","source":"https://www.3fingeredjacks.com/","accessed":"2026-10-03","si":["culinary","culture","family"],"booking_route":"walk-in","commission_status":"unknown","commission":"venue","tier_absent_reason":"does-not-compete","wells":["eat"],"draw_rank":40,"blurb":"\"For decades, Three Fingered Jack''s has been serving locals and visitors in the heart of downtown Winthrop. What started as a historic saloon remains a gathering place\"; breakfast Friday-Sunday 7:00-10:30 AM, prime rib every Friday, full bar."},{"name":"The Mazama Store","source":"https://www.themazamastore.com/","accessed":"2026-10-03","si":["culinary","motoring"],"booking_route":"walk-in","commission_status":"none","commission":"venue","tier_absent_reason":"does-not-compete","wells":["eat","shop"],"draw_rank":41,"blurb":"\"A little bit of everything good\": 50 Lost River Road, Mazama, open \"EVERYDAY 7am-6pm\", with an outdoor bakery and espresso area, a weekly bread schedule, and \"24 Hour Gas | Diesel | Non-ethanol\" - the last fuel before the park''s eastern side, where the NPS warns there are no gas stations along State Route 20 within the park. 509-996-2855."},{"name":"Winthrop","source":"https://winthropwashington.com/","accessed":"2026-10-03","si":["culture","family","motoring"],"booking_route":"none needed - a town","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities","shop"],"draw_rank":42,"blurb":"The Methow Valley gateway on State Route 20: \"The Wild West''s last frontier, where every season brings a new adventure\"; spring \"Vibrant wildflowers offer the perfect backdrop for outdoor enthusiasts to explore our scenic trails\"; summer hiking and river rafting."},{"name":"Bear canister for the canister-only camps","source":"https://www.nps.gov/noca/planyourvisit/wilderness-trip-planner.htm","accessed":"2026-10-03","si":["hiking","adventure","wildlife"],"booking_route":"affiliate referral to BearVault (AvantLink)","commission_status":"commissioned","commission":"affiliate","tier_absent_reason":"does-not-compete","commission_pct_low":8,"commission_pct_high":8,"commission_basis":"published","wells":["gear"],"draw_rank":43,"blurb":"The NPS backcountry camp table marks Fisher and Thunder Basin \"No Campfires, Bear Canister Required\" and Desolation \"No Campfires, Bear Canisters Required\"; Junction and Heaton Stock list \"Hang/Canister\". \"Backcountry permits are required year-round in North Cascades National Park for all overnight trips.\""},{"name":"Warm, waterproof clothing and a tent","source":"https://www.nps.gov/noca/planyourvisit/weather.htm","accessed":"2026-10-03","si":["hiking","adventure"],"booking_route":"affiliate referral to rei.com (AvantLink)","commission_status":"commissioned","commission":"affiliate","tier_absent_reason":"does-not-compete","commission_pct_low":5,"commission_pct_high":5,"commission_basis":"published","wells":["gear"],"draw_rank":44,"blurb":"NPS: \"Storms are common: always be prepared for a few days of rain and wind. Warm, waterproof clothing and a tent are necessary for spring, fall and winter trips into the backcountry.\""},{"name":"Satellite communicator where cell service fails","source":"https://www.nps.gov/noca/faqs.htm","accessed":"2026-10-03","si":["hiking","adventure","motoring"],"booking_route":"affiliate referral to zoleo.com (AvantLink)","commission_status":"commissioned","commission":"affiliate","tier_absent_reason":"does-not-compete","commission_pct_low":10,"commission_pct_high":10,"commission_basis":"published","wells":["gear"],"draw_rank":45,"blurb":"NPS: \"There is limited cell phone reception in the park and cell service should never be relied on.\" It advises downloading \"the official National Park Service app to access the free offline maps\" before entering. In Stehekin: \"There is no cell phone reception.\""},{"name":"Ice axe for Copper Ridge and the high camps","source":"https://www.nps.gov/noca/planyourvisit/backcountry-reservations.htm","accessed":"2026-10-03","si":["adventure","hiking"],"booking_route":"affiliate referral to Black Diamond Equipment (AvantLink)","commission_status":"commissioned","commission":"affiliate","tier_absent_reason":"does-not-compete","commission_pct_low":7,"commission_pct_high":7,"commission_basis":"published","wells":["gear"],"draw_rank":46,"blurb":"NPS on Copper Ridge: camps \"remain snow covered into July\"; \"Attempting to access the ridge before the snow melts is dangerous. Visitors must be proficient with an ice axe for steep snow fields and be prepared for high creek crossings.\" At Cascade Pass, hazards include \"steep, icy slopes, uncertain river crossings, and flooded or snow-covered camps.\""}],"faq":[{"q":"Is North Cascades National Park free?","a":"Yes. The NPS states: \"There is no fee to enter North Cascades National Park Service Complex. There are no trailhead or parking fees for trails that begin on National Park Service lands.\" Adjacent U.S. Forest Service trailheads can require a Northwest Forest Pass, and campgrounds and backcountry permits carry their own fees.","source":"https://www.nps.gov/noca/faqs.htm","accessed":"2026-10-03"},{"q":"Do you need reservations for North Cascades National Park?","a":"Not to enter: \"No, there is no reservation system to enter the park. You are welcome to enter and exit the park at any time.\" Campsites do need one in season: \"Camping reservations are required during the operational season (mid-May to early September) and are only available online at recreation.gov or by calling 1-877-444-6777.\"","source":"https://www.nps.gov/noca/faqs.htm","accessed":"2026-10-03"},{"q":"What is the best time to visit North Cascades National Park?","a":"\"The best weather for visiting the North Cascades generally occurs between mid-June and late-September. Snow is off all but the highest trails by July.\" Spring and autumn are \"becoming more popular\" for car tours \"enticing for color and wildlife during the less busy ''shoulder seasons''.\"","source":"https://www.nps.gov/noca/planyourvisit/weather.htm","accessed":"2026-10-03"},{"q":"Can you camp in North Cascades National Park?","a":"Yes. \"All drive-in campgrounds along State Route 20 are on a reservation system through recreation.gov\" during the season (mid-May to early September); Goodell Creek, Gorge Lake and ten walk-in sites at Colonial Creek South stay open year-round first-come, first-served. \"There is no dispersed camping in the park complex\", and occupancy is limited to \"eight people, three tents, and two vehicles per site.\"","source":"https://www.nps.gov/noca/planyourvisit/camping.htm","accessed":"2026-10-03"},{"q":"Do you need a permit to backpack in North Cascades National Park?","a":"Yes: \"Backcountry permits are required year-round in North Cascades National Park for all overnight trips.\" Reserve on Recreation.gov and pick the permit up the day before the trip, or get a walk-up permit at the Wilderness Information Center in Marblemount.","source":"https://www.nps.gov/noca/planyourvisit/wilderness-trip-planner.htm","accessed":"2026-10-03"},{"q":"Where can you stay in North Cascades National Park?","a":"\"Overnight lodging within the park can be found at Ross Lake Resort and the North Cascades Lodge at Stehekin. Other lodging accommodations can be found in the Stehekin and Chelan areas as well as along State Route 20 in the Skagit River Valley west of the park and the Methow River Valley to the east.\" For 2026 the NPS adds that the North Cascades Lodge at Stehekin \"is closed for the 2026 summer season.\"","source":"https://www.nps.gov/noca/faqs.htm","accessed":"2026-10-03"},{"q":"Can you drive through North Cascades National Park?","a":"Yes, in season: \"Drive approximately 30 miles across the park on the North Cascades Highway (State Route 20)... Allow at least an hour to drive this beautiful, winding road, and add more time for stops along the way.\" The NPS says to check road conditions for seasonal closures before arriving.","source":"https://www.nps.gov/noca/planyourvisit/north-cascades-highway.htm","accessed":"2026-10-03"},{"q":"Is North Cascades National Park dog friendly?","a":"Only in parts: \"Pets are not allowed within the national park except leashed on the Pacific Crest Trail.\" Leashed pets are allowed within the Ross Lake and Lake Chelan National Recreation Areas, and \"pets are welcome in drive in campgrounds and picnic areas\". Leashes must be no longer than 6 feet.","source":"https://www.nps.gov/noca/planyourvisit/pets.htm","accessed":"2026-10-03"},{"q":"Where can you shower in North Cascades National Park?","a":"Not in the park campgrounds: \"No, none of the park campgrounds have showers. However, campers can pay to shower in the local communities. Some private campgrounds outside of the park have shower options for their campers or may have showers available for purchase for non-campers.\"","source":"https://www.nps.gov/noca/faqs.htm","accessed":"2026-10-03"},{"q":"Can you fish in North Cascades National Park?","a":"Yes, under Washington State rules: \"Visitors fishing within North Cascades National Park Service Complex must follow the fishing license requirements in accordance with the laws and regulations of the State of Washington.\" Licences \"are not sold at any visitor or information station in the park complex, and you must obtain a license before visiting.\"","source":"https://www.nps.gov/noca/planyourvisit/fishing.htm","accessed":"2026-10-03"}],"seo":{"meta_title":"North Cascades National Park: Diablo Lake, SR 20 & Stehekin | TravelWell","meta_description":"Free entry, the 30-mile North Cascades Highway, Diablo Lake, Cascade Pass, Ross Lake''s floating cabins, roadless Stehekin, and where to camp and stay nearby.","slug":"north-cascades-national-park-washington","primary_keyword":"North Cascades National Park","jsonld_type":"TouristDestination"},"hero":{"query":"Diablo Lake North Cascades National Park"}}'::jsonb, 101)
