insert into public.destinations (id, region_code, name, country, line, status, depth, img, sub_region, si, feel, tier_range, price_band, draw_rank, data, position) values
  ('silver-falls-oregon', '12A', 'Silver Falls State Park', 'United States', 'Trail of Ten Falls and South Falls', 'future', 'verified', 'mountainValley', 'The Pacific Northwest', '{"hiking","family","group","adventure","parks"}', '{"dramatic","serene","historic","family-friendly"}', '{}', null, null, '{"safety":{"posture":"book-freely","source":"https://www.gov.uk/foreign-travel-advice/usa","verified":"2026-10-08"},"jewels":[{"name":"Trail of Ten Falls","source":"https://stateparks.oregon.gov/index.cfm?do=park.profile&parkId=151","accessed":"2026-10-03","si":["hiking","adventure","family"],"booking_route":"none needed - a day-use parking permit is required, bought at the trailhead fee machines","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":1,"blurb":"\"a spectacular, nationally recognized hiking trail that weaves through a dense forested landscape\"; \"This 7.2 mile loop is considered to be a moderate hike, with an overall elevation change of 800 feet.\" It \"is a designated National Recreation Trail\" made of the Canyon Trail and Rim Trail; \"access to the Trail of Ten falls does not require a registration or timed entry.\""},{"name":"South Falls","source":"https://stateparks.oregon.gov/index.cfm?do=park.profile&parkId=151","accessed":"2026-10-03","si":["hiking","family"],"booking_route":"none needed - reached from the South Falls day-use area","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":2,"blurb":"\"Where else can you walk behind a waterfall? Check out the famous South Falls and see what a 177-foot curtain of water looks like from behind.\" \"South Falls can be viewed with a pet, though the trail to walk inbehind is not accessible.\""},{"name":"The four walk-behind falls","source":"https://stateparks.oregon.gov/index.cfm?do=park.profile&parkId=151","accessed":"2026-10-03","si":["hiking","adventure"],"booking_route":"none needed - on the Canyon Trail","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":3,"blurb":"\"There are four waterfalls that you are able to walk behind. South Falls is the famous one, though Lower South, North and Middle North all have an amphitheater that provides enough room for a trail. The water of Silver Creek flows over a thick basalt lava flow that is resting on softer, older rock.\""},{"name":"North Rim Trail and North Canyon day-use area","source":"https://stateparks.oregon.gov/index.cfm?do=park.profile&parkId=151","accessed":"2026-10-03","si":["senior","family","hiking"],"booking_route":"none needed - day-use parking permit at the North Canyon fee machine","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":4,"blurb":"\"The North Rim Trail opened in July 2023. The one-mile trail is highly accessible with a width of 6 or more feet of compacted surface. The trail includes a viewpoint of the North Falls.\" North Canyon has picnic tables, an \"ADA-accessible restroom and 59 new parking spots, including three that are ADA accessible\", and access to the Nature Play Area for kids."},{"name":"South Falls day-use area","source":"https://stateparks.oregon.gov/index.cfm?do=park.profile&parkId=151","accessed":"2026-10-03","si":["family","group","senior"],"booking_route":"none needed - day-use parking permit ($10 Oregon residents, $12 out-of-state)","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":5,"blurb":"\"spacious lawns, barbecue stands, picnic shelters, tables, a playground, horseshoe pits, an off-leash area for dogs, and a charming creek. Ever since the opening day in 1933, visitors have been using these grounds for potlucks, family reunions and weddings.\" The park FAQ adds a \"designated swimming area\" and EV charging stations in the parking area."},{"name":"Historic South Falls Lodge","source":"https://stateparks.oregon.gov/index.cfm?do=park.profile&parkId=151","accessed":"2026-10-03","si":["culture","senior","family"],"booking_route":"none needed - open to all park visitors","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":6,"blurb":"\"on rainy or snowy days there will be a fire to warm up next to and a café for warm food & snacks. Friendly volunteers welcome questions about park history, flora, fauna and are happy to recommend specific trails.\" Open \"9 a.m. - 6 p.m. daily\", a volunteer on duty 11 am-4 pm; \"Free public Wifi is available at the South Falls Lodge.\""},{"name":"Silver Falls State Park Campground","source":"https://stateparks.oregon.gov/index.cfm?do=park.profile&parkId=151","accessed":"2026-10-03","si":["family","motoring","hiking"],"booking_route":"oregonstateparks.reserveamerica.com or 800-452-5687","commission_status":"unknown","commission":"hotel","tier_absent_reason":"not-established","wells":["stay"],"draw_rank":7,"blurb":"\"The main campground has tent sites, RV spots and cabins\": \"48 electrical sites with water (18+ sites open year-round)\", \"43 tent sites with water nearby (seasonal May-Oct.)\", flush toilets and showers, a dump station ($10 fee). \"Silver Falls has a very popular, small campground, which is usually full on summer evenings and nice weekends throughout the rest of the year.\" \"Dispersed camping is not permitted at Silver Falls.\""},{"name":"Campground cabins","source":"https://stateparks.oregon.gov/index.cfm?do=park.profile&parkId=151","accessed":"2026-10-03","si":["family","senior"],"booking_route":"oregonstateparks.reserveamerica.com or 800-452-5687","commission_status":"unknown","commission":"hotel","tier_absent_reason":"not-established","wells":["stay"],"draw_rank":8,"blurb":"\"14 cabins (7 pet friendly, open year-round)\" in the main campground; \"Reservations are required for cabin stays\"; four cabins are listed as accessible."},{"name":"Howard Creek Horse Camp","source":"https://stateparks.oregon.gov/index.cfm?do=park.profile&parkId=151","accessed":"2026-10-03","si":["group","adventure"],"booking_route":"oregonstateparks.reserveamerica.com or 800-452-5687","commission_status":"unknown","commission":"hotel","tier_absent_reason":"not-established","wells":["stay"],"draw_rank":9,"blurb":"\"Howard Creek Horse Camp (seasonal May-September)\": \"5 primitive sites with horse stalls\" and a \"Group site for 24 people and 12 horses\". \"Silver Falls does not currently offer horse rentals. You may bring your own horses and enjoy the equestrian trails.\""},{"name":"Backcountry trails for boots, bikes, paws and hooves","source":"https://stateparks.oregon.gov/index.cfm?do=park.profile&parkId=151","accessed":"2026-10-03","si":["adventure","hiking","wildlife"],"booking_route":"none needed - day-use parking permit only","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":10,"blurb":"\"The park offers more than 35 miles of backcountry trails for mountain biking, hiking or horseback riding\"; \"the trails of Rackett Ridge, Perimeter and Buck Mountain loop provide remarkable scenery\". \"Bears and cougars live in the more remote park areas.\""},{"name":"Smith Creek Village cabins","source":"https://visitsilverfalls.com/family-cabins/","accessed":"2026-10-03","si":["family","group","glamping"],"booking_route":"own website booking (secure.webrez.com) or (866) 993-2557","commission_status":"unknown","commission":"hotel","tier_absent_reason":"not-established","wells":["stay"],"draw_rank":11,"blurb":"Inside the park, run by Visit Silver Falls (Guest Services, Inc., \"an authorized concessioner for Oregon State Parks\"): \"8 tiny cabins, 4 family cabins, 2 duplex cabins, 1 VIP cabin\"; the family cabins \"sleep up to 12 guests\", 2-night minimum, \"No air conditioning. No television\"; day-use parking \"included in the room rate\". Fall 2026: \"Save up to 25% off per night\" Sunday-Thursday, September-November."},{"name":"Davidson Ranch at Smith Creek Village","source":"https://visitsilverfalls.com/davidson-ranch/","accessed":"2026-10-03","si":["group","family","romance"],"booking_route":"phone (866)-993-2557 or email (Ranch reservations are not booked online)","commission_status":"unknown","commission":"hotel","tier_absent_reason":"not-established","wells":["stay"],"draw_rank":12,"blurb":"\"Located just 3 miles from the main grounds of Silver Falls State Park, this rustic, spacious ranch is designed for large group stays, reunions, retreats, and unforgettable weddings\": \"Accommodates up to 75 guests\", twin bunk beds, 2 bathrooms, a full kitchen, indoor and outdoor fire pits, parking for up to 30 vehicles. \"No pets, except trained ADA service animals.\""},{"name":"South Falls Cafe","source":"https://visitsilverfalls.com/southfallscafe/","accessed":"2026-10-03","si":["culinary","family","hiking"],"booking_route":"walk-in, no booking","commission_status":"none","commission":"venue","tier_absent_reason":"does-not-compete","wells":["eat"],"draw_rank":13,"blurb":"\"Tucked inside the historic South Falls Lodge\", \"Built in the 1940s from hand-cut stone and fir logs\": coffee and specialty drinks, made-to-order sandwiches and grab-n-go trail food, with vegetarian, vegan and gluten-free options. \"May 1 - October 31: 9:00 AM - 6:00 PM Daily\"; \"November 1 - April 30, 2027: 10:00 AM - 4:00 PM Daily\"."},{"name":"Bigleaf Market & Grill, Smith Creek Village","source":"https://visitsilverfalls.com/bigleafmarketandgrill/","accessed":"2026-10-03","si":["culinary","family"],"booking_route":"walk-in; holiday meal by reservation via visitsilverfalls.com","commission_status":"unknown","commission":"venue","tier_absent_reason":"does-not-compete","wells":["eat","shop"],"draw_rank":14,"blurb":"Breakfast burritos, flatbreads, snacks, \"Freshly Brewed Coffee & Specialty Espresso Drinks\", and a market of \"Oregon-made goods\" and \"campfire and picnic essentials\"; \"May 1 - October 31: 8am - 7pm Daily\", \"November 1 - April 30, 2027: 8am - 5:30pm Daily\". A Thanksgiving family-style meal is listed for November 26, 2026."},{"name":"Ten Falls Supply Co.","source":"https://visitsilverfalls.com/tenfallssupplyco/","accessed":"2026-10-03","si":["hiking","family"],"booking_route":"walk-in retail at South Falls","commission_status":"unknown","commission":"operator","tier_absent_reason":"does-not-compete","wells":["gear","shop"],"draw_rank":15,"blurb":"At the South Falls District, open daily 10:00am-4:00pm: \"all of your hiking essentials, including maps, water bottles, trail snacks, waterproof backpacks, and trekking poles\" before the Trail of Ten Falls - \"After you complete the 7.2 mile hike, swing back by to pick-up a tee shirt or sticker\"."},{"name":"Friends of Silver Falls Nature Store","source":"https://stateparks.oregon.gov/index.cfm?do=park.profile&parkId=151","accessed":"2026-10-03","si":["culture","senior"],"booking_route":"walk-in retail","commission_status":"unknown","commission":"venue","tier_absent_reason":"does-not-compete","wells":["shop"],"draw_rank":16,"blurb":"\"The Friends of SIlver Falls operate the Nature Store, located between South Falls and the South Falls Lodge\", with \"nature-based merchandise and local artisan crafts\"; annual state park passes are sold here too. 503.873.3495."},{"name":"Junior Ranger programs","source":"https://stateparks.oregon.gov/index.cfm?do=park.profile&parkId=151","accessed":"2026-10-03","si":["family","wildlife"],"booking_route":"none needed - see the park event calendar","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":17,"blurb":"\"Junior Ranger programs are held in the campground from June-August and can be found on the park''s event calendar. Junior Ranger activity books are available for all ages and can be picked up at the park office, the South Falls Lodge, and from the park hosts in the campground.\""},{"name":"Ranger-guided field trips","source":"https://stateparks.oregon.gov/index.cfm?do=park.profile&parkId=151","accessed":"2026-10-03","si":["group","family"],"booking_route":"state booking form (Microsoft Bookings) linked from the park page","commission_status":"unknown","commission":"guide","tier_absent_reason":"does-not-compete","wells":["activities"],"draw_rank":18,"blurb":"\"Guided field trips can be reserved by filling out the form\"; \"As of August 30, 2026, all Fall 2026 field trips have been booked. Field trip bookings for spring 2027 will be available starting October 1, 2026.\" Fall trips run Wednesday-Friday in October; spring trips Wednesday-Friday \"from mid-April to early June\"."},{"name":"Fishing in Silver Creek","source":"https://stateparks.oregon.gov/index.cfm?do=park.profile&parkId=151","accessed":"2026-10-03","si":["adventure","wildlife"],"booking_route":"none needed in the park - an ODFW licence is required","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":19,"blurb":"\"Fishing is available in Silver Creek. Parties must be licensed through Oregon Department of Fish and Wildlife and are encouraged to stay on trail.\""},{"name":"Silver Falls Marathon & Trail Runs","source":"https://visitsilverfalls.com/event/silver-falls-marathon-trail-runs/2026-10-16/","accessed":"2026-10-03","si":["sports","adventure","group"],"booking_route":"race registration linked from the event page (registration site not read)","commission_status":"unknown","commission":"venue","tier_absent_reason":"does-not-compete","wells":["activities"],"draw_rank":20,"blurb":"\"Friday, October 16 - Sunday, October 18, 2026\": \"The three-day event offers five race distances, from a 5K to a 50K\" - 5K, 7 Miler, Half Marathon, Marathon and 50K - \"with several races taking runners through some of the park''s signature waterfall scenery. Registration is limited, and individual race distances may sell out.\""},{"name":"Silver Falls Winter Festival","source":"https://stateparks.oregon.gov/index.cfm?do=park.profile&parkId=151","accessed":"2026-10-03","si":["family","culture"],"booking_route":"see the park event calendar (ticketing not stated)","commission_status":"unknown","commission":"venue","tier_absent_reason":"does-not-compete","wells":["activities"],"draw_rank":21,"blurb":"Listed on the park''s events: \"Silver Falls Winter Festival - Next happening Sat, Dec 12, 2026 at 10:00 AM\", with one other session."},{"name":"Headlamp for short winter days","source":"https://stateparks.oregon.gov/index.cfm?do=park.profile&parkId=151","accessed":"2026-10-03","si":["hiking","family"],"booking_route":"affiliate referral to the retailer (AvantLink); bought before the trip","commission_status":"commissioned","commission":"affiliate","tier_absent_reason":"does-not-compete","commission_pct_low":7,"commission_pct_high":7,"commission_basis":"published","wells":["gear"],"draw_rank":22,"blurb":"Oregon State Parks on winter at Silver Falls: \"The park also has very little nighttime lighting and bringing a flashlight or headlamp is highliy recommended.\" Winter gates close at 5:00pm November-January."},{"name":"Sturdy hiking shoes for the canyon descent","source":"https://stateparks.oregon.gov/index.cfm?do=park.profile&parkId=151","accessed":"2026-10-03","si":["hiking","adventure"],"booking_route":"affiliate referral to rei.com (AvantLink); bought before the trip","commission_status":"commissioned","commission":"affiliate","tier_absent_reason":"does-not-compete","commission_pct_low":5,"commission_pct_high":5,"commission_basis":"published","wells":["gear"],"draw_rank":23,"blurb":"Oregon State Parks on the Trail of Ten Falls: \"Listed as a moderate hike with 800 feet elevation variation, sturdy shoes and a camera are encouraged.\""},{"name":"Traction and rain layers for icy, wet trails","source":"https://stateparks.oregon.gov/index.cfm?do=park.profile&parkId=151","accessed":"2026-10-03","si":["hiking","senior"],"booking_route":"affiliate referral to rei.com (AvantLink); bought before the trip","commission_status":"commissioned","commission":"affiliate","tier_absent_reason":"does-not-compete","commission_pct_low":5,"commission_pct_high":5,"commission_basis":"published","wells":["gear"],"draw_rank":24,"blurb":"Oregon State Parks: \"winter months often bring either large amounts of rain or sub-freezing temperatures that can result in ice or snow\"; \"icy conditions are common on the park trails and roads. Due to potentially icy conditions, allow plenty of time if you plan to hike the trails and turn back if you do not feel comfortable.\""},{"name":"Silver Spur RV Park, Silverton","source":"https://www.silverspurrvpark.com/attractions-near-us/","accessed":"2026-10-03","si":["motoring","family","senior"],"booking_route":"own website (View Dates & Rates) or (503) 873-2020","commission_status":"unknown","commission":"hotel","tier_absent_reason":"not-established","wells":["stay"],"draw_rank":25,"blurb":"12622 Silverton Rd NE: daily sites \"all full hookups including electric up to 50 Amp, Water, Sewer, and Wi-Fi\", plus a cabin and bungalows and, in spring and summer, teepees; a lodge with fireplace, game room, catch-and-release fishing pond, hot tub and heated pool (spring/summer). Summer daily rates $70-$75 a site. \"Silver Falls State Park - Located about 12 miles from us\"."},{"name":"Grace Acres Scenic RV Camping, Mount Angel","source":"https://www.hipcamp.com/en-US/land/oregon-grace-acres-scenic-rv-camping-zwjhn2wn","accessed":"2026-10-03","si":["motoring","family"],"booking_route":"Hipcamp","commission_status":"unknown","commission":"affiliate","tier_absent_reason":"not-established","wells":["stay"],"draw_rank":26,"blurb":"Hipcamp listing: \"rentable gravel sites to campers seeking a pastoral farm setting\"; \"Gravel sites have 110 volt hook-up. Campfires allowed\", pets allowed, no water hookup; the host notes \"THE SHOWER IS UNAVAILABLE DUE TO RENOVATION!\" \"30 minutes from Silver Falls and Champoeg State Park.\""},{"name":"Creekside Camping with Showers, Molalla","source":"https://www.hipcamp.com/en-US/land/oregon-creekside-camping-with-showers-zwjhrexx","accessed":"2026-10-03","si":["group","family"],"booking_route":"Hipcamp","commission_status":"unknown","commission":"affiliate","tier_absent_reason":"not-established","wells":["stay"],"draw_rank":27,"blurb":"Hipcamp listing with \"4 separate sites\": a group campground \"with a kitchen and hot/cold potable water and 20 amps of power\" that \"can hold 8-10 large tents comfortably. Price includes up to 10 people\", plus a tiny creekside cabin and a retro trailer. A 2025 reviewer: \"It''s not too far from Silver Falls State Park\"."},{"name":"Crooked Finger Farms - The Bali House, Scotts Mills","source":"https://www.hipcamp.com/en-US/land/oregon-crooked-finger-farms-g2ejhxy1","accessed":"2026-10-03","si":["glamping","romance"],"booking_route":"Hipcamp","commission_status":"unknown","commission":"affiliate","tier_absent_reason":"not-established","wells":["stay"],"draw_rank":28,"blurb":"Hipcamp listing: \"a romantic Glamping escape in the beautifully curated converted greenhouse\" on a \"67-acre organic farm and equestrian facility\", with a wood-burning hot tub; private bathroom and kitchenette in the historic barn \"a short walk away\". The host points to \"Abiqua Falls just up the road, and ''The Trail of Ten Falls'' at Silver Falls St. Park\"; \"approximately 12 miles from the town of Silverton\"."},{"name":"Oregon Garden Resort, Silverton","source":"https://www.oregongardenresort.com/","accessed":"2026-10-03","si":["romance","wellness","family","senior"],"booking_route":"own website booking or phone","commission_status":"unknown","commission":"hotel","tier_absent_reason":"not-established","wells":["stay"],"draw_rank":29,"blurb":"Cottage-style guest rooms \"each featuring cozy fireplaces and private patios\"; outdoor pool and hot tub, Moonstone Spa, complimentary breakfast, EV charging, and \"free admission to The Oregon Garden, accessible through a private gate\"; pet-friendly rooms. The resort lists Silver Falls State Park among its local attractions and sits \"an hour''s drive from Portland\"."},{"name":"DoubleTree by Hilton Salem","source":"https://www.travelsalem.com/stay/","accessed":"2026-10-03","si":["family","senior","group"],"booking_route":"hilton.com (brand booking; not fetched)","commission_status":"commissioned","commission":"hotel","tier_absent_reason":"not-established","commission_pct_low":10,"commission_pct_high":10,"commission_basis":"published","wells":["stay"],"draw_rank":30,"blurb":"Listed by Travel Salem at \"1590 Weston Ct. NE Salem, Oregon 97301\", (971) 910-8610. Hilton''s own page was not fetched, so nothing else about the property is stated here."},{"name":"Hampton Inn & Suites Salem","source":"https://www.travelsalem.com/stay/","accessed":"2026-10-03","si":["family","senior"],"booking_route":"hilton.com (brand booking; not fetched)","commission_status":"commissioned","commission":"hotel","tier_absent_reason":"not-established","commission_pct_low":10,"commission_pct_high":10,"commission_basis":"published","wells":["stay"],"draw_rank":31,"blurb":"Listed by Travel Salem at \"510 Hawthorne Ave. SE Salem, Oregon 97301\", (503) 362-1300. Hilton''s own page was not fetched, so nothing else about the property is stated here."},{"name":"Home2 Suites by Hilton Salem","source":"https://www.travelsalem.com/stay/","accessed":"2026-10-03","si":["family","group"],"booking_route":"hilton.com (brand booking; not fetched)","commission_status":"commissioned","commission":"hotel","tier_absent_reason":"not-established","commission_pct_low":10,"commission_pct_high":10,"commission_basis":"published","wells":["stay"],"draw_rank":32,"blurb":"Listed by Travel Salem at \"390 Hawthorne Ave. SE Salem, Oregon 97301\", (503) 371-5920. Hilton''s own page was not fetched, so nothing else about the property is stated here."},{"name":"Holiday Inn Salem","source":"https://www.travelsalem.com/stay/","accessed":"2026-10-03","si":["family","group","senior"],"booking_route":"ihg.com (brand booking; not fetched)","commission_status":"commissioned","commission":"hotel","tier_absent_reason":"not-established","commission_pct_low":10,"commission_pct_high":10,"commission_basis":"benchmark","wells":["stay"],"draw_rank":33,"blurb":"Listed by Travel Salem at \"3301 Market St. NE Salem, Oregon 97301\", (503) 370-7888, home of the Capitol City Grill. IHG''s own page was not fetched, so nothing else about the property is stated here."},{"name":"The Grand Hotel in Salem","source":"https://www.travelsalem.com/stay/","accessed":"2026-10-03","si":["culture","senior"],"booking_route":"own website (linked from Travel Salem; not fetched)","commission_status":"unknown","commission":"hotel","tier_absent_reason":"not-established","wells":["stay"],"draw_rank":34,"blurb":"Listed by Travel Salem at \"201 Liberty St. SE Salem, Oregon 97301\", (503) 747-5743, an independent downtown hotel. Its own page was not fetched."},{"name":"Silver Falls Brewery Ale House, Silverton","source":"https://www.silverfallsbrewery.com/","accessed":"2026-10-03","si":["culinary","family","group"],"booking_route":"walk-in (no reservation method read)","commission_status":"unknown","commission":"venue","tier_absent_reason":"does-not-compete","wells":["eat"],"draw_rank":35,"blurb":"207 Jersey Street, Silverton: \"The Ale House, in the heart of charming downtown Silverton, serves locally sourced food and brews right on site, with an overlooking Brew Deck Bar\"; \"handcrafted burgers, sandwiches, fresh salads, and more - all made from scratch\", with vegetarian options."},{"name":"Garden View Restaurant and Fireside Lounge, Oregon Garden Resort","source":"https://www.oregongardenresort.com/dining","accessed":"2026-10-03","si":["culinary","romance"],"booking_route":"own website or phone","commission_status":"unknown","commission":"venue","tier_absent_reason":"does-not-compete","wells":["eat"],"draw_rank":36,"blurb":"\"Dine at the Garden View Restaurant and experience the flavors of the Pacific Northwest, then visit the Fireside Lounge with nightly live music. Indoor and seasonal patio seating\"; holiday buffets for Mother''s Day and Thanksgiving. Listed hours: Sunday-Thursday 11:30am-10pm, Friday-Saturday 11:30am-11pm."},{"name":"Benedictine Brewery and Taproom, Mt. Angel","source":"https://www.travelsalem.com/eat-drink/breweries/","accessed":"2026-10-03","si":["culinary","pilgrimage","culture"],"booking_route":"walk-in (terms not read)","commission_status":"unknown","commission":"venue","tier_absent_reason":"does-not-compete","wells":["eat"],"draw_rank":37,"blurb":"Listed by Travel Salem among the region''s breweries at \"400 Humpert Ln. NE Mt. Angel, Oregon 97362\", (971) 343-2772. Its own site opened on an age gate and was not read further."},{"name":"Lou''s Kitchen, Mt. Angel","source":"https://www.travelsalem.com/eat-drink/restaurants/?page=2","accessed":"2026-10-03","si":["culinary"],"booking_route":"phone (503) 845-5687 (reservation method not read)","commission_status":"unknown","commission":"venue","tier_absent_reason":"does-not-compete","wells":["eat"],"draw_rank":38,"blurb":"Listed by Travel Salem among the region''s restaurants at \"190 E Charles St. Mt. Angel, Oregon 97362\", (503) 845-5687. Menu and hours not read."},{"name":"The Oregon Garden, Silverton","source":"https://www.oregongarden.org/","accessed":"2026-10-03","si":["family","senior","culture"],"booking_route":"own website tickets (terms not read); free admission for Oregon Garden Resort guests","commission_status":"unknown","commission":"venue","tier_absent_reason":"does-not-compete","wells":["activities"],"draw_rank":39,"blurb":"\"a stunning botanical garden encompassing more than 130 acres, featuring specialty gardens which showcase the diverse botanical beauty of the Willamette Valley and the Pacific Northwest\" - \"from our Pet-Friendly Garden to our Children''s Garden\"; operations \"fully supported by the Oregon Garden Foundation, a 501(c)3 non-profit.\" Host of the Silverton Christmas Market, \"November 20 - December 31, 2026\" (Oregon Garden Resort)."},{"name":"The Gordon House (Frank Lloyd Wright), Silverton","source":"https://www.thegordonhouse.org/","accessed":"2026-10-03","si":["culture","senior"],"booking_route":"guided tour tickets via the own website (terms not read)","commission_status":"unknown","commission":"venue","tier_absent_reason":"does-not-compete","wells":["activities"],"draw_rank":40,"blurb":"\"the only Frank Lloyd Wright design built in Oregon\": designed in 1957 and built in 1963 in Wilsonville for Conrad and Evelyn Gordon, \"saved from demolition in the winter of 2001, deconstructed and painstakingly relocated 40 miles away to its current location in Silverton\", next to The Oregon Garden. Guided tours at 12pm, 1pm and 2pm."},{"name":"Mt. Angel Oktoberfest","source":"https://www.oktoberfest.org/","accessed":"2026-10-03","si":["culture","group","family","culinary"],"booking_route":"premium venue tickets via the own website","commission_status":"unknown","commission":"venue","tier_absent_reason":"does-not-compete","wells":["activities"],"draw_rank":41,"blurb":"\"The largest folk festival in the Northwest\": a German/Swiss festival in Mt. Angel with \"40+ nonprofit food booths\"; \"Only three premium entertainment venues have an admission: Biergarten, Weingarten and Alpinegarten. All others are free admission.\" The 2026 kick-off party was \"Sept 12, 2026\". Silver Spur RV Park: \"RV spaces in our park fill up almost a year in advance for this event\"."},{"name":"Silverton","source":"https://www.silvertonchamber.org/","accessed":"2026-10-03","si":["culture","family","culinary"],"booking_route":"none needed - a town","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":42,"blurb":"The gateway town: Visit Silver Falls puts the park \"just 25 minutes from Silverton\". The Silverton Chamber of Commerce: \"From majestic waterfalls to charming historic streets, Silverton offers unforgettable experiences for every visitor\", with trip-planning maps and guides."},{"name":"Silverton Reservoir","source":"https://www.silverspurrvpark.com/attractions-near-us/","accessed":"2026-10-03","si":["family","adventure"],"booking_route":"none needed - public reservoir","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":43,"blurb":"\"located on the Cascade foothills 2.5 miles east of Silverton. Locals enjoy swimming, boating (non-motorized), and fishing in this 68-acre impoundment.\""},{"name":"Gallon House Bridge","source":"https://www.silverspurrvpark.com/attractions-near-us/","accessed":"2026-10-03","si":["culture","motoring","senior"],"booking_route":"none needed - a public bridge","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":44,"blurb":"\"the last covered bridge (and the oldest) in Marion County. Built in 1916, locals dubbed it the Gallon House during the Prohibition era. The neighboring city of Mt. Angel allowed alcohol, whereas Silverton did not.\""}],"faq":[{"q":"How much does it cost to go to Silver Falls State Park?","a":"Oregon State Parks: \"A day-use parking permit for Silver Falls costs $10 for Oregon residents and $12 for out-of-state residents.\" Fee machines give no change - bring exact change or a Visa, AMEX or Mastercard. A campground pass doubles as the day-use permit, and National Park and America the Beautiful passes are not valid.","source":"https://stateparks.oregon.gov/index.cfm?do=park.profile&parkId=151","accessed":"2026-10-03"},{"q":"Do you need reservations for Silver Falls State Park?","a":"Not to hike. \"Though a parking permit is required, access to the Trail of Ten falls does not require a registration or timed entry.\" Camping and cabins are reserved at oregonstateparks.reserveamerica.com, \"6 months in advance\"; \"Reservations are required for cabin stays.\"","source":"https://stateparks.oregon.gov/index.cfm?do=park.profile&parkId=151","accessed":"2026-10-03"},{"q":"How long is the Silver Falls State Park hike?","a":"\"The full Trail of Ten Falls consists of Canyon Trail and Rim Trail, for a 7.2 mile loop.\" It \"is considered to be a moderate hike, with an overall elevation change of 800 feet. Several connecting trails with separate access points make shorter routes.\"","source":"https://stateparks.oregon.gov/index.cfm?do=park.profile&parkId=151","accessed":"2026-10-03"},{"q":"How many waterfalls are in Silver Falls State Park?","a":"The park concessioner describes the \"7.2-mile Trail of Ten Falls with 10 scenic waterfalls\"; \"You can walk behind 4 waterfalls. South Falls, Lower South Falls, North Falls and Middle North.\"","source":"https://visitsilverfalls.com/faqs/","accessed":"2026-10-03"},{"q":"Can you camp at Silver Falls State Park?","a":"Yes. \"The main campground has tent sites, RV spots and cabins\": 48 electrical sites with water, 43 tent sites (seasonal May-Oct.), 14 cabins, and the Howard Creek Horse Camp. Book at oregonstateparks.reserveamerica.com or 800-452-5687. \"Dispersed camping is not permitted at Silver Falls.\"","source":"https://stateparks.oregon.gov/index.cfm?do=park.profile&parkId=151","accessed":"2026-10-03"},{"q":"Can you have dogs at Silver Falls State Park?","a":"In most areas, on a leash no longer than six feet - but \"pets are not allowed on the Canyon Trail or on the connecting trails of Winter Trail, Maple Ridge Trail and Twin Falls Trail.\" There is an off-leash area in the South Falls day-use area, and \"Upper North Falls is a pet friendly waterfall!\"","source":"https://stateparks.oregon.gov/index.cfm?do=park.profile&parkId=151","accessed":"2026-10-03"},{"q":"Can you swim at Silver Falls State Park?","a":"The South Falls Day Use Area has a \"designated swimming area\", per Oregon State Parks. At Upper North Falls, a short trail \"leads to the base of the 65 foot cascade where on leash your pet can swim\".","source":"https://stateparks.oregon.gov/index.cfm?do=park.profile&parkId=151","accessed":"2026-10-03"},{"q":"Can you fish at Silver Falls State Park?","a":"\"Fishing is available in Silver Creek. Parties must be licensed through Oregon Department of Fish and Wildlife and are encouraged to stay on trail.\"","source":"https://stateparks.oregon.gov/index.cfm?do=park.profile&parkId=151","accessed":"2026-10-03"},{"q":"What are Silver Falls State Park''s hours?","a":"Gates at South Falls and North Canyon day use are locked outside: November-January 8:00am-5:00pm; February 8:00am-6:00pm; March 8:00am-8:00pm; April-August 7:00am-9:00pm; September 7:00am-8:00pm; October 8:00am-7:00pm. The Park Administration office is open Monday-Friday 8:30am-4:30pm.","source":"https://stateparks.oregon.gov/index.cfm?do=park.profile&parkId=151","accessed":"2026-10-03"},{"q":"When is the best time to visit Silver Falls State Park?","a":"The state names no single best season. For colour: \"Depending on the first frost, mid-October is usually the peak for Silver Falls State Park''s brief-but-spectacular fall color season.\" In winter, \"icy conditions are common on the park trails and roads.\" The concessioner advises \"early arrival recommended on weekends and holidays\" (visitsilverfalls.com).","source":"https://stateparks.oregon.gov/index.cfm?do=park.profile&parkId=151","accessed":"2026-10-03"}],"seo":{"meta_title":"Silver Falls State Park, Oregon: Trail of Ten Falls, Camping & Cabins | TravelWell","meta_description":"The 7.2-mile Trail of Ten Falls, four falls you can walk behind, the $10/$12 parking permit, campground and cabins booked 6 months out, and Silverton nearby.","slug":"silver-falls-state-park-oregon","primary_keyword":"Silver Falls State Park","jsonld_type":"TouristDestination"},"hero":{"query":"Silver Falls State Park South Falls"}}'::jsonb, 102),
  ('glacier-bay-alaska', '12A', 'Glacier Bay National Park', 'United States', 'Tidewater glaciers, whales and Bartlett Cove rainforest', 'future', 'verified', 'mountainValley', 'Alaska', '{"wildlife","expedition","adventure","hiking","family","senior","group","parks"}', '{"wild","remote","dramatic","serene"}', '{}', null, null, '{"safety":{"posture":"book-freely","source":"https://www.gov.uk/foreign-travel-advice/usa","verified":"2026-10-08"},"jewels":[{"name":"Glacier Bay Day Tour","source":"https://www.visitglacierbay.com/tours/glacier-bay-day-tour/","accessed":"2026-10-03","si":["wildlife","family","senior","group","expedition"],"booking_route":"own website booking (visitglacierbay.com) or (888) 229-8687","commission_status":"unknown","commission":"operator","tier_absent_reason":"does-not-compete","wells":["activities"],"draw_rank":1,"blurb":"\"the only scheduled day tour permitted inside Glacier Bay National Park & Preserve\": an \"8-hour tour\" by catamaran from Bartlett Cove, boarding 6:50 am, departing 7:15 am, returning \"around 3:30 pm daily\", to \"Margerie or Johns Hopkins Glaciers, two towering masses of ice and snow rising 245 feet above the ocean\"; \"narrated by a National Park Service Ranger\"; \"Lunch and a beverage are included\". Adult $273.57, child (3-12) $142.92. \"Advance Reservations Highly Recommended.\" NPS: runs May 22-September 7, 2026."},{"name":"Glacier Bay Lodge","source":"https://www.visitglacierbay.com/lodging-camping/glacier-bay-lodge/","accessed":"2026-10-03","si":["wildlife","senior","family","romance"],"booking_route":"own website booking (visitglacierbay.com) or (907) 697-4000 / (888) 229-8687; deposit of the first night at booking","commission_status":"unknown","commission":"hotel","tier_absent_reason":"not-established","wells":["stay"],"draw_rank":2,"blurb":"\"the only hotel accommodations inside the park!\" - \"Nestled under the spruce trees that line Bartlett Cove\" with \"magnificent sunset views of the Fairweather Mountain range\"; open \"May 21, 2026 - Sept 8, 2026\"; Standard, Deluxe and ADA Accessible rooms (ground level, roll-in shower); the NPS Visitor Center is on the second floor; \"Pets are not permitted\"."},{"name":"Tidewater glaciers from the cruise-ship deck","source":"https://www.nps.gov/glba/planyourvisit/cruising.htm","accessed":"2026-10-03","si":["expedition","senior","family","group","wildlife"],"booking_route":"booked with the cruise line, not the park","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":3,"blurb":"\"For over 100 years, most visitors to Glacier Bay enjoy the amazing landscape of Glacier Bay from the deck of large cruise ships\"; typically \"two ships per day travel up the West Arm to spend 4 or more hours in the glacier areas\", and \"National Park Service naturalists board the ship to share their knowledge about the park and its wildlife during a day-long cruise in the bay.\""},{"name":"Bartlett Cove Campground","source":"https://www.nps.gov/glba/planyourvisit/campground.htm","accessed":"2026-10-03","si":["hiking","adventure","family"],"booking_route":"none - free, first come first served, permit and orientation at the Visitor Information Station","commission_status":"none","tier_absent_reason":"not-sold","wells":["stay"],"draw_rank":4,"blurb":"\"The National Park Service maintains a free walk-in campground in Bartlett Cove\"; \"Advance reservations for the campground are not accepted. Camping is first come, first served.\" \"A permit and a brief orientation are required\"; \"All food and other scented items must be stored in one of the campground''s three food caches.\" The NPS gives a 14-day maximum stay; level, compacted paths and one \"wheelchair accessible vault toilet\"."},{"name":"Margerie and Johns Hopkins glaciers","source":"https://www.nps.gov/glba/faqs.htm","accessed":"2026-10-03","si":["expedition","wildlife","senior","family"],"booking_route":"none - reached by cruise ship, the day boat, a small ship or private vessel","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":5,"blurb":"\"There are 11 glaciers that reach the sea in Glacier Bay National Park and Preserve, 8 of which are within the bay\"; Margerie Glacier is approximately 55 nautical miles from Bartlett Cove and Johns Hopkins about 63; \"Glaciers flow forward about 3 - 6 feet each day\"."},{"name":"Humpback whales of the lower bay","source":"https://www.nps.gov/glba/faqs.htm","accessed":"2026-10-03","si":["wildlife","family","senior","expedition"],"booking_route":"none - seen from the day boat, ships and kayaks","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":6,"blurb":"\"Humpback whales are most commonly seen in the lower region of Glacier Bay; Sitakaday Narrows, Whidbey Passage and the waters around South Marble Island\"; black bears around Bartlett Cove, the Bartlett River and the Beardslee Islands, brown bears \"north of Tidal Inlet in the west arm\"."},{"name":"Sea kayaking and the camper drop-off","source":"https://www.nps.gov/glba/planyourvisit/kayaking.htm","accessed":"2026-10-03","si":["adventure","wildlife","expedition"],"booking_route":"drop-off booked with the day-boat concessioner; free backcountry permit at the Bartlett Cove Visitor Information Station","commission_status":"unknown","commission":"operator","tier_absent_reason":"does-not-compete","wells":["activities"],"draw_rank":7,"blurb":"\"Sea kayaking is an incredible way to experience the vast wilderness and solitude of Glacier Bay.\" Trips launch from Bartlett Cove or use \"drop-offs and/or pickups by the daily tour boat at designated camper dropoff locations upbay\"; advance reservations are recommended because kayak capacity is limited. \"Tides here are extreme (up to 25'' every 6 hours), and an understanding of tides is essential\"."},{"name":"Forest Trail loop","source":"https://www.nps.gov/glba/planyourvisit/hiking.htm","accessed":"2026-10-03","si":["hiking","family","senior"],"booking_route":"none needed - free park trail","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":8,"blurb":"\"1 mile loop\", \"30 min.-1.5 hours\": a loop through temperate rainforest and beach on dirt, gravel and boardwalk, with benches and viewing platforms in the spruce and hemlock forest."},{"name":"Bartlett River Trail","source":"https://www.nps.gov/glba/planyourvisit/hiking.htm","accessed":"2026-10-03","si":["hiking","wildlife"],"booking_route":"none needed - free park trail","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":9,"blurb":"\"4 miles round-trip\", \"4-5 hours\": along an intertidal lagoon through spruce and hemlock forest to the Bartlett River estuary; watch for coyotes, moose, bear, river otter and migratory waterfowl."},{"name":"Bartlett Lake Trail","source":"https://www.nps.gov/glba/planyourvisit/hiking.htm","accessed":"2026-10-03","si":["hiking","adventure"],"booking_route":"none needed - free park trail","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":10,"blurb":"\"8 miles round-trip\", \"7-8 hours\": branches from the Bartlett River Trail and climbs the moraine through moss-covered terrain; a less maintained trail requiring caution. \"Bring water, lunch and raingear.\""},{"name":"Tlingit Trail","source":"https://www.nps.gov/glba/planyourvisit/hiking.htm","accessed":"2026-10-03","si":["culture","senior","family","hiking"],"booking_route":"none needed - free park trail","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":11,"blurb":"\"1/2 mile one way\", an \"Easy stroll along the forested shoreline edge\" with views of Bartlett Cove, a traditional dugout canoe and a whale skeleton; the NPS accessibility page calls it a flat, accessible gravel pathway."},{"name":"Explore the Shore to Point Gustavus","source":"https://www.nps.gov/glba/planyourvisit/hiking.htm","accessed":"2026-10-03","si":["hiking","wildlife","family"],"booking_route":"none needed - free shoreline walk","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":12,"blurb":"Length \"Varies\" - up to six miles one way to Point Gustavus; shoreline walking that reveals intertidal life, birds, marine mammals and summer wildflowers. Wear \"sturdy shoes with good traction\" and be bear and moose aware."},{"name":"Junior Ranger programme","source":"https://www.nps.gov/glba/learn/kidsyouth/index.htm","accessed":"2026-10-03","si":["family","culture"],"booking_route":"none needed - free park programme","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":13,"blurb":"Children can \"Become a Junior Ranger\", or from home \"Become a Glacier Bay Web Ranger and earn a junior ranger prize\"; in person there are ranger-led activities, day boat tours, visitor center visits, hikes, beach exploration and the Tribal House, and special Junior Ranger programmes run through cruise-ship youth centers."},{"name":"Glacier Bay Visitor Center","source":"https://www.nps.gov/glba/planyourvisit/accessibility.htm","accessed":"2026-10-03","si":["senior","family","culture"],"booking_route":"none needed - free","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":14,"blurb":"Located upstairs in the historic Glacier Bay Lodge; \"The park visitor center, exhibits, and theater are located upstairs and accessible via elevator or stairs.\" Braille brochures, staff fluent in American Sign Language, and a half-mile boardwalk to Blackwater Pond that is \"accessible and easy to negotiate\"."},{"name":"Private vessel permits","source":"https://www.nps.gov/glba/faqs.htm","accessed":"2026-10-03","si":["yacht","sailing","expedition"],"booking_route":"free permit from the park","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":15,"blurb":"\"Boating permits are required to enter Glacier Bay during June, July and August\"; permits allow stays \"up to seven days\" and can be reserved \"up to 60 days before your trip\"; \"If you plan on enjoying Glacier Bay with your private vessel, a free permit is required.\""},{"name":"Rain gear and traction footwear","source":"https://www.nps.gov/glba/planyourvisit/hiking.htm","accessed":"2026-10-03","si":["hiking","family","senior"],"booking_route":"bought before the trip - gear retail","commission_status":"unknown","commission":"affiliate","tier_absent_reason":"does-not-compete","commission_pct_low":5,"commission_pct_high":5,"commission_basis":"published","wells":["gear"],"draw_rank":16,"blurb":"The kit the park names for its trails: wear \"sturdy shoes with good traction\" and bring rain gear; for the Bartlett Lake Trail, \"Bring water, lunch and raingear.\""},{"name":"Backcountry kit and bear-resistant food canisters","source":"https://www.nps.gov/glba/planyourvisit/kayaking.htm","accessed":"2026-10-03","si":["adventure","hiking"],"booking_route":"canisters loaned free by the park; other kit bought before the trip - gear retail","commission_status":"unknown","commission":"affiliate","tier_absent_reason":"does-not-compete","commission_pct_low":5,"commission_pct_high":5,"commission_basis":"published","wells":["gear"],"draw_rank":17,"blurb":"\"All food and other scented items must be properly stored in an approved bear-resistant food canister, provided by the park at no charge.\" Overnight users complete a 30-minute orientation, which provides tide tables, and carry the kit for tides \"up to 25'' every 6 hours\"."},{"name":"Fairweather Dining Room","source":"https://www.visitglacierbay.com/lodging-camping/dining/","accessed":"2026-10-03","si":["culinary","family","senior"],"booking_route":"walk-in at Glacier Bay Lodge","commission_status":"none","commission":"venue","tier_absent_reason":"does-not-compete","wells":["eat"],"draw_rank":18,"blurb":"\"At Glacier Bay Lodge, you''ll enjoy cuisine that''s as spectacular as the scenery surrounding you\" - local halibut and salmon; breakfast 6:00-9:00 am, lunch 12:00-3:00 pm, dinner 5:00-10:00 pm (final seating 9:45 pm), deck service 3:00-5:00 pm; a Kids menu; cashless."},{"name":"Gustavus","source":"https://gustavusak.com/","accessed":"2026-10-03","si":["culture","family","senior"],"booking_route":"none - a town","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":19,"blurb":"The gateway town: Gustavus is \"approximately 9.5 miles from Glacier Bay Lodge by road\" and has \"a number of popular inns, lodges, and B&B''s\" (NPS); \"a small coastal community, approximately 50 air miles west of Juneau, Alaska\" (Cottonwood Lodge). Its visitor association lists lodging, dining, fishing, kayaking, whale watching and flightseeing."},{"name":"UnCruise Glacier Bay Adventure Cruise","source":"https://www.uncruise.com/products/glacier-bay-adventure-cruise-with-2-days-in-glacier-bay","accessed":"2026-10-03","si":["group","expedition","senior","family","adventure","wildlife"],"booking_route":"own website booking (uncruise.com) and travel advisors","commission_status":"unknown","commission":"operator","tier_absent_reason":"does-not-compete","wells":["activities"],"draw_rank":20,"blurb":"\"Glacier Bay Adventure Cruise with 2 Days in Glacier Bay\": 7 nights round trip from Juneau aboard Wilderness Discoverer (76 guests) or Wilderness Adventurer (60 guests); \"Forget viewing a glacier from a crowded deck—we take you to shore in a skiff\"; \"kayak, skiff, hike glacial ridges, moraine walks, or even all-day paddle\"; airport transfers, meals, activities and \"port taxes & fees are included\"; from $4,900 per person (2027 Navigator Cabin, double); departures May-September; family-focused dates offered."},{"name":"Sea Wolf Adventures","source":"https://www.seawolfadventures.net/","accessed":"2026-10-03","si":["senior","group","expedition","wildlife"],"booking_route":"phone +1-907-957-1438, seawolfoffice@gmail.com or the Reserve Now form","commission_status":"unknown","commission":"operator","tier_absent_reason":"does-not-compete","wells":["activities"],"draw_rank":21,"blurb":"\"Active small ship cruising adventures\" on \"a comfortable 12 passenger expedition vessel\": \"Glacier Bay Adventures April-August\" and a \"Glacier Bay to Sitka adventure\", 6-day/5-night and 8-day/7-night trips; for \"people of all abilities\" on a \"universal accessible ship\". No prices on the page."},{"name":"Glacier Bay Sea Kayaks","source":"https://www.glacierbayseakayaks.com/","accessed":"2026-10-03","si":["adventure","family","wildlife","group"],"booking_route":"phone (907) 697-2257, info@glacierbayseakayaks.com, or the Day Trip Reservation Form","commission_status":"unknown","commission":"operator","tier_absent_reason":"does-not-compete","wells":["activities","gear"],"draw_rank":22,"blurb":"Based at Bartlett Cove: \"unguided (rentals) or guided day kayak adventures\" with \"full instruction\"; paddlers \"explore intertidal zones while viewing an abundance of wildlife\"; \"fiberglass sea touring kayaks\" for backcountry rental. Named by the NPS kayaking page for rentals and guided day trips."},{"name":"Alaska Mountain Guides - Glacier Bay Sea Kayaking Expedition","source":"https://www.alaskamountainguides.com/","accessed":"2026-10-03","si":["adventure","group","expedition"],"booking_route":"own website","commission_status":"unknown","commission":"operator","tier_absent_reason":"does-not-compete","wells":["activities"],"draw_rank":23,"blurb":"Leads \"remote wilderness sea kayaking expeditions in Glacier Bay National Park\"; a featured \"Glacier Bay Sea Kayaking Expedition\" and a promotion of \"15% off groups of 4+\" on the Glacier Bay Exploration tour. Trip length and dates were not on the page read."},{"name":"Hollywood Farms RV Park","source":"https://hollywoodfarmsrvpark.com/","accessed":"2026-10-03","si":["family","adventure"],"booking_route":"ResNexus online booking (linked from the own website)","commission_status":"unknown","commission":"hotel","tier_absent_reason":"not-established","wells":["stay"],"draw_rank":24,"blurb":"\"A NEW Alaskan RV Park made just for you!\"; listed by the Gustavus Visitors Association as \"located at the gateway to Glacier Bay National Park offering 9 sites\"; RV site and campground reservations are taken online."},{"name":"Glacier Bay Domes","source":"https://gustavusak.com/listing/glacier-bay-domes/","accessed":"2026-10-03","si":["glamping","romance","family"],"booking_route":"phone 1-907-723-1042 or stvbrknbn@yahoo.com","commission_status":"unknown","commission":"hotel","tier_absent_reason":"not-established","wells":["stay"],"draw_rank":25,"blurb":"\"Our unique domes are one bedroom with Queen bed and a loft with a bed. Living room has a pull out couch bed. Kitchen, bathroom. On site WiFi, washer and dryer, hot tub and wood burning sauna. Deck for barbecues, E-bikes. Complimentary Airport and ferry pickup is available.\" Gustavus."},{"name":"Bear Track Inn","source":"https://www.beartrackinn.com/","accessed":"2026-10-03","si":["wildlife","romance","senior","culinary"],"booking_route":"phone 907-697-3017, beartrackinn@gmail.com, or Check Availability on the own website","commission_status":"unknown","commission":"hotel","tier_absent_reason":"not-established","wells":["stay"],"draw_rank":26,"blurb":"\"Since 1997, Glacier Bay''s Bear Track Inn has been the premiere lodging choice for visitors to Gustavus\": a \"hand-crafted lodge\", \"family owned and operated\", with \"14 spacious guest rooms, each with private baths and two queen size beds\"; \"All meals are included with your stay\"; itineraries \"The Best of Glacier Bay,\" \"Animal Watchers Delight\" and \"The Adventurer\"; \"Our lodge operates in the summertime\"."},{"name":"The Excursion Restaurant at Bear Track Inn","source":"https://www.beartrackinn.com/","accessed":"2026-10-03","si":["culinary","romance"],"booking_route":"with a stay at the inn; phone 907-697-3017","commission_status":"none","commission":"venue","tier_absent_reason":"does-not-compete","wells":["eat"],"draw_rank":27,"blurb":"\"Breakfast and dinner...in the dining room, and a packed lunch is provided for you to take on any of our excursions\"; regional cuisine from a \"show kitchen\"; the Gustavus Visitors Association adds \"locally brewed beer or an extensive wine list\"."},{"name":"Glacier Bay Country Inn","source":"http://www.glacierbayalaska.com/","accessed":"2026-10-03","si":["adventure","group","family","culinary"],"booking_route":"phone 907-697-2288 or the contact page","commission_status":"unknown","commission":"hotel","tier_absent_reason":"not-established","wells":["stay"],"draw_rank":28,"blurb":"\"For over 40 years, the family-owned and operated Glacier Bay Country Inn has hosted anglers and adventurers from all over the world\"; lodge rooms, private cabins and a two-bedroom suite on \"164 Private acres\" with \"Private hiking trails\", hot tub and \"unforgettable meals featuring local seafood\"; all-inclusive fishing, adventure and combo packages of 3-5 nights and a \"7 Night Ultimate Alaska Adventure\"; \"NOW BOOKING SUMMER 2026 & 2027\"."},{"name":"Glacier Bay Country Inn dining room","source":"http://www.glacierbayalaska.com/","accessed":"2026-10-03","si":["culinary","family"],"booking_route":"with a stay at the inn; phone 907-697-2288","commission_status":"none","commission":"venue","tier_absent_reason":"does-not-compete","wells":["eat"],"draw_rank":29,"blurb":"The inn''s on-site restaurant serves \"unforgettable meals featuring local seafood\" to guests on its all-inclusive packages."},{"name":"Annie Mae Lodge","source":"http://www.anniemae.com","accessed":"2026-10-03","si":["group","family"],"booking_route":"phone (800) 478-2346 / (907) 697-2346, reservations@anniemae.com, or online at guest.rezstream.com","commission_status":"unknown","commission":"hotel","tier_absent_reason":"not-established","wells":["stay"],"draw_rank":30,"blurb":"\"Experience the stunning beauty of Southeast Alaska at The Annie Mae Lodge\", independent for over 30 years \"at the entrance to Glacier Bay National Park\"; deluxe and basic rooms; \"Our lodge does not offer meals or ground transfers and does not have a host on site.\" The entire lodge can be rented by a group, with full kitchen and laundry."},{"name":"Cottonwood Lodge & Cabin Rentals","source":"http://www.cottonwoodlodge.net","accessed":"2026-10-03","si":["family","romance"],"booking_route":"phone (907) 697-2227, text (907) 789-7901, or rental@cottonwoodlodge.net","commission_status":"unknown","commission":"hotel","tier_absent_reason":"not-established","wells":["stay"],"draw_rank":31,"blurb":"\"Located right outside Glacier Bay National Park in Gustavus, Alaska\": \"individual cabins built in private settings on ten acres\", each \"18'' X 24''\" with a \"Fully equipped kitchen\" and covered deck; \"Open May thru September\"; \"50% deposit is due at time of reservation with balance due on arrival.\""},{"name":"Fairweather Adventures Bed and Breakfast","source":"https://www.fairweatheradventures.net/bed-and-breakfast/","accessed":"2026-10-03","si":["wildlife","family","group"],"booking_route":"phone +1 (907) 723-3065 or (907) 697-2334 (May-Sept.), jim@fairweatheradventures.net","commission_status":"unknown","commission":"hotel","tier_absent_reason":"not-established","wells":["stay"],"draw_rank":32,"blurb":"\"approximately two miles from the Gustavus Dock\" in \"a private two acre meadow surrounded by a towering forest of Sitka Spruce and Western Hemlock\"; \"three clean and comfortable guest rooms featuring private baths with overnight accommodations for up to eight persons\"; \"a delicious home cooked breakfast\"; paired glacier bay sightseeing and sport fishing charters."},{"name":"The Halibut House (Gustavus Packing)","source":"https://www.gustavuspacking.com/lodging-1","accessed":"2026-10-03","si":["group","family"],"booking_route":"via the Gustavus Packing website","commission_status":"unknown","commission":"hotel","tier_absent_reason":"not-established","wells":["stay"],"draw_rank":33,"blurb":"\"A modern yet cozy 4-bedroom, 2-bath retreat, crafted from locally milled wood and surrounded by Alaskan wilderness\"; Gustavus Packing also offers anglers \"a convenient place to process and pack your fresh catch\"."},{"name":"Fireweed Gallery, Coffee & Tea House","source":"https://www.fireweedcoffee.com","accessed":"2026-10-03","si":["culinary","family","culture"],"booking_route":"walk-in, Gustavus; (907) 697-3013","commission_status":"none","commission":"venue","tier_absent_reason":"does-not-compete","wells":["eat","shop"],"draw_rank":34,"blurb":"\"Your source for the best cup of freshly roasted coffee, local and organic food, and handmade Alaskan goods and art\": specialty coffees, housemade baked goods, crepes, breakfast biscuits and milkshakes; summer Monday-Friday 7-5, Saturday 8-5; an art gallery of Alaska-made gifts."},{"name":"Red Rooster","source":"https://gustavusak.com/dining/","accessed":"2026-10-03","si":["culinary"],"booking_route":"walk-in, Gustavus","commission_status":"none","commission":"venue","tier_absent_reason":"does-not-compete","wells":["eat"],"draw_rank":35,"blurb":"Listed by the Gustavus Visitors Association: \"Red Rooster Open Monday-Saturday 11:00am-4:00pm Pub Nights coming soon!!! Beers on draft and small assortment of wine.\" No own website listed."},{"name":"Higher Grounds Coffee Shop","source":"https://gustavusak.com/dining/","accessed":"2026-10-03","si":["culinary"],"booking_route":"walk-in, Gustavus airport","commission_status":"none","commission":"venue","tier_absent_reason":"does-not-compete","wells":["eat"],"draw_rank":36,"blurb":"Listed by the Gustavus Visitors Association at the airport, inside Alaska Seaplanes, serving sandwiches and donuts. No own website listed."},{"name":"Tidelines Institute","source":"https://www.tidelinesinstitute.org/","accessed":"2026-10-03","si":["culture","group","deepdive"],"booking_route":"own website","commission_status":"unknown","commission":"operator","tier_absent_reason":"does-not-compete","wells":["activities"],"draw_rank":37,"blurb":"\"Alaskan education with a vision for the world\", \"In the communities and wildlands of Síx'' Tlein (Icy Strait) and Sít'' Eeti Gheeyí (Glacier Bay)\": a \"Semester program\", \"Short courses\" and \"Community workshops\". Dates and lengths were not on the page read."}],"faq":[{"q":"Can you drive to Glacier Bay National Park?","a":"No. \"Glacier Bay National Park and Preserve lies west of Juneau, AK and can only be reached by plane or boat.\" \"The only road in Glacier Bay National Park connects the small town of Gustavus and its airport to park headquarters at Bartlett Cove (Approx. 10 miles by road).\"","source":"https://www.nps.gov/glba/planyourvisit/directions.htm","accessed":"2026-10-03"},{"q":"How do I get to Glacier Bay National Park from Juneau?","a":"\"Alaska Airlines provides daily jet service from Juneau to Gustavus in the summer season\" and Alaska Seaplanes offers \"Multiple daily flights to Gustavus from Juneau\"; \"The flight between Juneau and Gustavus typically takes about 30 minutes one way.\" By sea, \"During the summer months, the Alaska state ferry typically stops in Gustavus twice weekly from Juneau.\"","source":"https://www.nps.gov/glba/planyourvisit/directions.htm","accessed":"2026-10-03"},{"q":"Can you camp in Glacier Bay National Park?","a":"Yes. \"The National Park Service maintains a free walk-in campground in Bartlett Cove\"; \"Advance reservations for the campground are not accepted. Camping is first come, first served.\" \"A permit and a brief orientation are required\".","source":"https://www.nps.gov/glba/planyourvisit/campground.htm","accessed":"2026-10-03"},{"q":"When was Glacier Bay National Park established?","a":"\"Glacier Bay was established in 1925 as a national monument and then a national park in 1980.\"","source":"https://www.nps.gov/glba/learn/management/index.htm","accessed":"2026-10-03"},{"q":"What animals can you see in Glacier Bay National Park?","a":"\"Humpback whales are most commonly seen in the lower region of Glacier Bay; Sitakaday Narrows, Whidbey Passage and the waters around South Marble Island.\" Black bears are common around Bartlett Cove, the Bartlett River and the Beardslee Islands, and brown bears \"north of Tidal Inlet in the west arm\".","source":"https://www.nps.gov/glba/faqs.htm","accessed":"2026-10-03"},{"q":"Where can you stay in Glacier Bay National Park?","a":"\"Glacier Bay Lodge, located within the park at Bartlett Cove is the only lodging within the park\", open \"from mid-may through early September\". Gustavus, about 9.5 miles away by road, has \"a number of popular inns, lodges, and B&B''s.\"","source":"https://www.nps.gov/glba/planyourvisit/eatingsleeping.htm","accessed":"2026-10-03"},{"q":"Is there a day boat in Glacier Bay National Park?","a":"Yes - \"the only scheduled day tour permitted inside Glacier Bay National Park & Preserve\", an \"8-hour tour\" from Bartlett Cove, \"narrated by a National Park Service Ranger\", with \"Lunch and a beverage\" included. \"Advance Reservations Highly Recommended.\"","source":"https://www.visitglacierbay.com/tours/glacier-bay-day-tour/","accessed":"2026-10-03"},{"q":"Can you hike in Glacier Bay National Park?","a":"Yes. Bartlett Cove has the Forest Trail (\"1 mile loop\"), the Bartlett River Trail (\"4 miles round-trip\"), the Bartlett Lake Trail (\"8 miles round-trip\"), the Tlingit Trail (\"1/2 mile one way\") and Explore The Shore, up to six miles to Point Gustavus. Wear \"sturdy shoes with good traction\" and bring rain gear.","source":"https://www.nps.gov/glba/planyourvisit/hiking.htm","accessed":"2026-10-03"},{"q":"Do you need a boat permit for Glacier Bay National Park?","a":"\"Boating permits are required to enter Glacier Bay during June, July and August\"; they allow stays \"up to seven days\" and can be reserved \"up to 60 days before your trip\".","source":"https://www.nps.gov/glba/faqs.htm","accessed":"2026-10-03"}],"seo":{"meta_title":"Glacier Bay National Park: Glaciers, Day Boat & Gustavus | TravelWell","meta_description":"No entrance fee, reached only by plane or boat: the ranger-narrated day boat to Margerie Glacier, Bartlett Cove trails, kayaking and where to stay in Gustavus.","slug":"glacier-bay-national-park-alaska","primary_keyword":"Glacier Bay National Park","jsonld_type":"TouristDestination"},"hero":{"query":"Glacier Bay National Park tidewater glacier"}}'::jsonb, 103),
  ('denali-alaska', '12A', 'Denali National Park', 'United States', 'Park road buses, sled dogs and subarctic wilderness', 'future', 'verified', 'mountainValley', 'Alaska', '{"wildlife","hiking","adventure","family","senior","group","parks"}', '{"wild","remote","rugged","adventurous"}', '{}', null, null, '{"safety":{"posture":"book-freely","source":"https://www.gov.uk/foreign-travel-advice/usa","verified":"2026-10-08"},"jewels":[{"name":"Denali Park Road tour buses (Doyon/Aramark Joint Venture)","source":"https://www.nps.gov/dena/planyourvisit/bus-tours.htm","accessed":"2026-10-03","si":["wildlife","senior","family","group","motoring"],"booking_route":"www.reservedenali.com or 1-800-622-7275 (Doyon/Aramark Joint Venture)","commission_status":"unknown","commission":"operator","tier_absent_reason":"does-not-compete","wells":["activities","move"],"draw_rank":1,"blurb":"\"tour buses feature a trained naturalist who both drives the bus and narrates during the trip\"; operated under concession by the Doyon/Aramark Joint Venture. 2026: Natural History Tour $116.75 adult / $51.00 child (May 13-Sept 15); Tundra Wilderness Tour $144.75 adult / $65.00 child (May 20-Sept 17); \"$15 park entrance fee is included in the price of an adult tour bus ticket\". 🔴 \"Due to the Pretty Rocks Landslide, buses are traveling no further than Mile 43 of the Denali Park Road.\""},{"name":"Sled Dog Demonstrations at the park kennels","source":"https://www.nps.gov/dena/planyourvisit/sled-dog-demonstrations.htm","accessed":"2026-10-03","si":["family","senior","wildlife","group"],"booking_route":"none needed - free, no reservation; free bus from the Denali Visitor Center","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":2,"blurb":"\"Rangers and dogs work together to demonstrate a traditional Alaskan mode of travel. These unique, 30 minute programs include an opportunity to tour the park kennels.\" Peak season (June 1 through early September) \"at 10 am, 2 pm, and 4 pm\"; \"Free buses leave the Denali Visitor Center for the kennels approximately forty (40) minutes before each demonstration\". \"No fees or reservations are required.\""},{"name":"Denali Park Road transit buses","source":"https://www.nps.gov/dena/planyourvisit/visiting-denali.htm","accessed":"2026-10-03","si":["hiking","wildlife","adventure"],"booking_route":"www.reservedenali.com or 800.622.7275 (Doyon/Aramark Joint Venture)","commission_status":"unknown","commission":"operator","tier_absent_reason":"does-not-compete","wells":["move"],"draw_rank":3,"blurb":"Non-narrated transit buses are cheaper than tours and let passengers get off anywhere along the restricted portion of the road; \"Due to the Pretty Rocks landslide, the road is currently closed to all traffic at Mile 43.\" Transit buses run from \"May 20 each year\" to \"the second Thursday after the Labor Day holiday each year\"."},{"name":"Denali Visitor Center","source":"https://www.nps.gov/dena/planyourvisit/the-denali-visitor-center.htm","accessed":"2026-10-03","si":["family","senior","hiking"],"booking_route":"none needed - free with park entry","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":4,"blurb":"\"the main National Park Service welcome and information center\"; shows \"Heartbeats of Denali\", \"about 20 minutes long\" and non-narrated, plus three short films; an exhibit area; \"a ranger is available 9 am to 4 pm daily (except on major holidays)\"; the Alaska Railroad depot is less than 100 yards away and \"Most of the trails in Denali can be accessed from the center.\""},{"name":"Savage River and the Savage River Loop","source":"https://www.nps.gov/dena/planyourvisit/savage-river-area.htm","accessed":"2026-10-03","si":["hiking","family","senior","wildlife"],"booking_route":"none needed - free shuttle or private vehicle to Mile 15","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":5,"blurb":"Mile 15, \"near the end of the paved and publicly-accessible portion of the Denali Park Road\"; the \"Savage River Loop Trail\" \"travels alongside its namesake river for a total distance of 2 miles\". \"Parking is extremely limited at Savage River\"; the free Savage River Shuttle runs \"roughly mid-May to mid-September\". Mountain Vista at Mile 13 has \"panoramic views, hiking trails, and a picnic area\"."},{"name":"Horseshoe Lake Trail","source":"https://www.nps.gov/dena/planyourvisit/dayhiking.htm","accessed":"2026-10-03","si":["hiking","family","wildlife"],"booking_route":"none needed - free park trail","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":6,"blurb":"2 miles round-trip: \"A popular trail that descends to, and travels entirely around, a lake\"; a 250-foot descent to the lakeshore, grades averaging 5% with sections up to 20%."},{"name":"Mount Healy Overlook Trail","source":"https://www.nps.gov/dena/planyourvisit/dayhiking.htm","accessed":"2026-10-03","si":["hiking","adventure"],"booking_route":"none needed - free park trail","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":7,"blurb":"2.7 miles one-way: \"An increasingly steep hike out of the forest and into the alpine country\"; rough surface with rocks and roots, up to a 25% grade."},{"name":"Triple Lakes Trail","source":"https://www.nps.gov/dena/planyourvisit/dayhiking.htm","accessed":"2026-10-03","si":["hiking","adventure","group"],"booking_route":"none needed - free park trail","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":8,"blurb":"9.5 miles one-way: \"Denali''s longest trail, with bridges over two creeks and great views of three lakes\"; grades up to 20%, and groups are limited to 12 people in the Wilderness area."},{"name":"McKinley Station Trail","source":"https://www.nps.gov/dena/planyourvisit/dayhiking.htm","accessed":"2026-10-03","si":["senior","hiking","family"],"booking_route":"none needed - free park trail","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":9,"blurb":"1.6 miles one-way from the visitor center, down \"one long, gently sloping hill\" with an 8.5% maximum grade - the gentlest grade of the entrance-area trails the NPS describes."},{"name":"Savage Alpine Trail","source":"https://www.nps.gov/dena/planyourvisit/dayhiking.htm","accessed":"2026-10-03","si":["hiking","adventure"],"booking_route":"none needed - free park trail","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":10,"blurb":"4 miles one-way, connecting the Savage River and Mountain Vista areas: \"Considered strenuous, the trail has steep sections up to 25% grade\"."},{"name":"Ranger Discovery Hikes","source":"https://www.nps.gov/dena/planyourvisit/discovery-hikes.htm","accessed":"2026-10-03","si":["hiking","adventure","group"],"booking_route":"in person at the Denali Visitor Center, one or two days ahead; transit bus ticket via reservedenali.com","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":11,"blurb":"\"Ranger-led hikes travel everywhere, so expect uneven terrain, small stream crossings, close encounters with dense vegetation and unpredictable weather.\" From mid-June, one hike a day; \"You may sign up for a hike one or two days in advance, and you can only sign up in person at the Denali Visitor Center\"; \"All Discovery Hikes begin with a bus ride from the entrance area into the park\" and most require a transit bus ticket."},{"name":"Discovery packs and the Junior Ranger programme","source":"https://www.nps.gov/dena/learn/kidsyouth/index.htm","accessed":"2026-10-03","si":["family","wildlife"],"booking_route":"none needed - free loan at the park","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":12,"blurb":"\"Borrow a free discovery pack for the duration of your visit and explore Denali like a scientist\"; a Denali Junior Ranger programme \"in person or online\"; a downloadable Denali for Families travel guide; \"Fourth graders are eligible for free passes to access federal lands and waters.\""},{"name":"Riley Creek Campground","source":"https://www.nps.gov/dena/planyourvisit/campgrounds.htm","accessed":"2026-10-03","si":["motoring","family","senior","hiking"],"booking_route":"online via the concessioner''s reservation system or Doyon/ARAMARK Joint Venture 1-800-622-7275","commission_status":"unknown","commission":"venue","tier_absent_reason":"not-established","wells":["stay"],"draw_rank":13,"blurb":"Mile 0.25: \"Open year-round, fees are only charged in summer\"; \"Open to RVs and tents\". \"Reservations can be made as early as December 1 of the year before your visit\"; \"Senior Pass and Access Pass holders receive 50% off nightly camping fees\". The Mercantile here sells \"snacks, sandwiches and camping food\"."},{"name":"Savage River Campground","source":"https://www.nps.gov/dena/planyourvisit/campgrounds.htm","accessed":"2026-10-03","si":["hiking","motoring","family"],"booking_route":"online via the concessioner''s reservation system or 1-800-622-7275","commission_status":"unknown","commission":"venue","tier_absent_reason":"not-established","wells":["stay"],"draw_rank":14,"blurb":"Mile 14: \"Open in summer only (mid-May to mid-September)\"; \"Open to RVs and tents\"; reservations \"as early as December 1 of the year before your visit\"."},{"name":"Teklanika River Campground","source":"https://www.nps.gov/dena/planyourvisit/campgrounds.htm","accessed":"2026-10-03","si":["motoring","wildlife","adventure"],"booking_route":"online via the concessioner''s reservation system or 1-800-622-7275","commission_status":"unknown","commission":"venue","tier_absent_reason":"not-established","wells":["stay"],"draw_rank":15,"blurb":"Mile 29: \"Open in summer only (May 20 - mid-September), to RVs and tents\"; \"Requires a minimum 3-night stay if you drive to the campground\"."},{"name":"Sanctuary River and Igloo Creek campgrounds","source":"https://www.nps.gov/dena/planyourvisit/campgrounds.htm","accessed":"2026-10-03","si":["adventure","hiking","wildlife"],"booking_route":"online via the concessioner''s reservation system or 1-800-622-7275","commission_status":"unknown","commission":"venue","tier_absent_reason":"not-established","wells":["stay"],"draw_rank":16,"blurb":"Sanctuary River (Mile 22) and Igloo Creek (Mile 35): \"Open in summer only (May 20 - mid-September)\"; \"Open to tents only, access is by bus\"."},{"name":"Wonder Lake Campground (closed through 2026)","source":"https://www.nps.gov/dena/planyourvisit/campgrounds.htm","accessed":"2026-10-03","si":["adventure","wildlife"],"booking_route":"none - closed through 2026","commission_status":"none","commission":"venue","tier_absent_reason":"not-established","wells":["stay"],"draw_rank":17,"blurb":"🔴 CLOSED: \"Wonder Lake Campground is closed through 2026, due to the Pretty Rocks Construction project.\" Mile 85, beyond the Mile 43 road closure."},{"name":"Backcountry backpacking permits","source":"https://www.nps.gov/dena/planyourvisit/backcountry.htm","accessed":"2026-10-03","si":["adventure","hiking","expedition"],"booking_route":"free permit in person, no more than one day ahead","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":18,"blurb":"\"Backcountry permits are free and required for overnight trips in the Denali backcountry\", issued in person at the Backcountry Information Center on the Denali Bus Depot campus \"no more than one day prior to the start of the trip\"; the park is \"divided into 87 sections, or units, and only a certain number of people can camp in a given unit each night.\""},{"name":"Winter in Denali - skiing, snowshoeing and mushing","source":"https://www.nps.gov/dena/planyourvisit/winter-activities.htm","accessed":"2026-10-03","si":["adventure","ski","wildlife"],"booking_route":"none needed - free; snowshoes loaned at the Murie Science and Learning Center","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":19,"blurb":"\"Denali is not closed in winter!\" - \"Cross-country skiing, winter biking and snowshoeing\", mushing, skijoring and aurora viewing; the Murie Science and Learning Center is \"Denali''s winter visitor center\" from late September to early May, lending snowshoes; \"The Denali Park Road typically closes at mile 3 for several months.\""},{"name":"Morino Grill","source":"https://www.nps.gov/dena/planyourvisit/eatingsleeping.htm","accessed":"2026-10-03","si":["culinary","family"],"booking_route":"walk-in (no booking route on the NPS page)","commission_status":"unknown","commission":"venue","tier_absent_reason":"does-not-compete","wells":["eat"],"draw_rank":20,"blurb":"\"the Morino Grill is the only sit-down restaurant in the park\", about 30 yards from the Denali Visitor Center; snacks are also sold at the Wilderness Access Center and the Riley Creek Mercantile."},{"name":"Rain gear and layers for subarctic weather","source":"https://www.nps.gov/dena/planyourvisit/safety.htm","accessed":"2026-10-03","si":["hiking","adventure","family","senior"],"booking_route":"affiliate referral to Rab US (AvantLink)","commission_status":"commissioned","commission":"affiliate","tier_absent_reason":"does-not-compete","commission_pct_low":10,"commission_pct_high":10,"commission_basis":"published","wells":["gear"],"draw_rank":21,"blurb":"NPS: \"Dress in layers, preferably made of wool or synthetic material that is able to insulate you even when wet. Bring rain gear or an umbrella.\" \"Hypothermia is always a factor in the subarctic. Rainy, chilly days are normal in summer.\" The weather page adds that \"a good waterproof, hooded raincoat is invaluable\"."},{"name":"Bear spray for every Denali hiker","source":"https://www.nps.gov/dena/planyourvisit/safety.htm","accessed":"2026-10-03","si":["hiking","adventure","wildlife"],"booking_route":"affiliate referral to Counter Assault (AvantLink)","commission_status":"commissioned","commission":"affiliate","tier_absent_reason":"does-not-compete","commission_pct_low":8,"commission_pct_high":8,"commission_basis":"published","wells":["gear"],"draw_rank":22,"blurb":"NPS: \"Bear spray is strongly encouraged for all hikers in Denali.\" The backcountry page lists \"Bear spray\" alongside \"Bug spray\", \"Gaiters\", \"Trekking poles\" and \"Proper layers\" for temperatures \"ranging from as warm as 75 F to as cold as 20 F\"."},{"name":"Bear-resistant food container for the backcountry","source":"https://www.nps.gov/dena/planyourvisit/backcountry.htm","accessed":"2026-10-03","si":["adventure","hiking","expedition"],"booking_route":"free NPS loan, or affiliate referral to BearVault (AvantLink)","commission_status":"commissioned","commission":"affiliate","tier_absent_reason":"does-not-compete","commission_pct_low":8,"commission_pct_high":8,"commission_basis":"published","wells":["gear"],"draw_rank":23,"blurb":"NPS: \"Bear Resistant Food Containers are required from April 15 - September 30.\" \"You may bring your own approved BRFC or check one out from the NPS\" - the park loan is free, so a purchase is optional."},{"name":"Denali Rainbow Village & RV Park","source":"https://hipcamp.com/d/united-states/alaska/healy/camping/all","accessed":"2026-10-03","si":["motoring","family"],"booking_route":"Hipcamp listing","commission_status":"unknown","commission":"affiliate","tier_absent_reason":"not-established","wells":["stay"],"draw_rank":24,"blurb":"Listed by Hipcamp as \"closest park to Denali National Park\", with 75 sites with full or partial hookups; \"15mi from Healy\". The business''s own domain did not resolve when fetched."},{"name":"Tatlanika Trading Company and RV Park","source":"https://hipcamp.com/d/united-states/alaska/healy/camping/all","accessed":"2026-10-03","si":["motoring","culture"],"booking_route":"Hipcamp listing","commission_status":"unknown","commission":"affiliate","tier_absent_reason":"not-established","wells":["stay"],"draw_rank":25,"blurb":"Listed by Hipcamp with 21 sites with water and electric hookups, \"6.4mi from Healy\"."},{"name":"Cantwell RV Park and Cabins","source":"https://hipcamp.com/d/united-states/alaska/healy/camping/all","accessed":"2026-10-03","si":["motoring","family"],"booking_route":"Hipcamp listing","commission_status":"unknown","commission":"affiliate","tier_absent_reason":"not-established","wells":["stay"],"draw_rank":26,"blurb":"Listed by Hipcamp as RV sites with cabin options, \"half an hour south of the Denali National Park entrance\", \"39mi from Healy\"."},{"name":"Wildthingz Dog Mushing","source":"https://www.hipcamp.com/en-US/land/alaska-wildthingz-dog-mushing-j29h8dq8","accessed":"2026-10-03","si":["glamping","family","wildlife","adventure"],"booking_route":"Hipcamp","commission_status":"unknown","commission":"affiliate","tier_absent_reason":"not-established","wells":["stay","activities"],"draw_rank":27,"blurb":"A working sled dog kennel in Cantwell, \"just 30 minutes south of the famed Denali National Park & Preserve, right off the Parks highway\", with canvas wall tents (Lynx Tent, Bear Cabin) and a log cabin (Moose Cabin), each for up to 3; propane heat, solar power, outhouses, no running water or showers; a \"summer tour operation\" June through September, discounted for overnight guests."},{"name":"Denali Princess Wilderness Lodge","source":"https://www.princesslodges.com/princess-alaska-lodges/denali-lodge/","accessed":"2026-10-03","si":["senior","family","group","wildlife"],"booking_route":"own website reservations or (907) 683-2282 / (800) 426-0500","commission_status":"unknown","commission":"hotel","tier_absent_reason":"not-established","wells":["stay"],"draw_rank":28,"blurb":"\"Mile 238.5 George Parks Hwy\"; \"the entrance to Denali National Park is located only a mile from our front door\", with \"expansive decks overlooking the Nenana River\"; rooms with \"two double beds, two queen beds, or one king bed\"; Grizzly Burger and King Salmon Restaurant on site; packages with Alaska Rail Tours."},{"name":"King Salmon Restaurant","source":"https://www.princesslodges.com/princess-alaska-lodges/denali-lodge/","accessed":"2026-10-03","si":["culinary","senior","romance"],"booking_route":"at the lodge, (907) 683-2282","commission_status":"unknown","commission":"venue","tier_absent_reason":"does-not-compete","wells":["eat"],"draw_rank":29,"blurb":"At the Denali Princess Wilderness Lodge, Mile 238.5: \"King Salmon Restaurant for delicious, Alaska cuisine and panoramic views\"."},{"name":"Kantishna Roadhouse","source":"https://www.kantishnaroadhouse.com/","accessed":"2026-10-03","si":["wildlife","adventure","senior","romance"],"booking_route":"own website availability check or (907) 374-3041 / (800) 942-7420","commission_status":"unknown","commission":"hotel","tier_absent_reason":"not-established","wells":["stay"],"draw_rank":30,"blurb":"\"Voted The #1 Wilderness Lodge In Alaska By USA Today\"; all-inclusive at \"Mile Marker 90, Denali Park Rd\". Its own wording: \"After several years of limited road access, the Denali Park Road is reopening\" for Summer 2027, with \"round-trip bus transportation between the Denali National Park entrance area and Kantishna Roadhouse\"; season \"June 11 - September 11\" (2027), two-night minimum. The NPS states the road is \"currently closed to all traffic at Mile 43\"."},{"name":"Denali Raft Adventures","source":"https://www.denaliraft.com/","accessed":"2026-10-03","si":["adventure","family","river"],"booking_route":"FareHarbor (own website); 907-683-2234","commission_status":"unknown","commission":"operator","tier_absent_reason":"does-not-compete","wells":["activities","gear"],"draw_rank":31,"blurb":"Mile 238.6 Parks Highway, about half a mile north of the park entrance; Nenana River trips from the 2-hour Wilderness Run (\"Class I/II ages 5+\") and Canyon Run (\"Class III/IV ages 12+\") to an 8-hour Full Day Adventure; \"May 20th to September 10th\"; modern dry suits provided; \"Last minute arrivals are always welcome\"."},{"name":"Denali Air flightseeing","source":"https://www.denaliair.com/","accessed":"2026-10-03","si":["adventure","senior","romance","wildlife"],"booking_route":"own website reservations or 907-683-2261","commission_status":"unknown","commission":"operator","tier_absent_reason":"does-not-compete","wells":["activities"],"draw_rank":32,"blurb":"\"Original flightseeing company in Denali\", flying from a private airstrip at Mile 229.5 Parks Highway: the Peak Experience Tour (60 minutes flight time, about 200 miles round trip, $469 adult / $235 child) and the Denali Express Tour (45-50 minutes, $380 adult / $225 child); seven daily flight times."},{"name":"Denali Jeep Excursions","source":"https://www.denalijeep.com/","accessed":"2026-10-03","si":["motoring","adventure","family"],"booking_route":"FareHarbor (own website)","commission_status":"unknown","commission":"operator","tier_absent_reason":"does-not-compete","wells":["activities"],"draw_rank":33,"blurb":"Office \"on the Denali Boardwalk at Mile 238.6 Parks Hwy\"; the 4-hour \"Denali Highway Jeep Excursion\" - guests drive new Jeep Wranglers on about 100 miles of the Denali Highway with CB radio contact; \"Daily departures from May 20th to September 15th, 2027\"; $189 adult (13+), $119 child; transfers from Denali area lodging included."},{"name":"Black Diamond Resort Co","source":"https://blackdiamondresortco.com/","accessed":"2026-10-03","si":["family","group","adventure","golf"],"booking_route":"FareHarbor (fareharbor.com/embeds/book/blackdiamondtourco) or (907) 683-4653","commission_status":"unknown","commission":"operator","tier_absent_reason":"does-not-compete","wells":["activities"],"draw_rank":34,"blurb":"Healy, \"One Mile Otto Lake Road\": ATV and side-by-side backcountry tours, \"Draft horse-drawn covered wagon expeditions\", a 9-hole tundra golf course and the Black Diamond Grill; \"Open Every day May 13th - September 21st From 11 AM to 10 PM\"."},{"name":"Black Diamond Grill","source":"https://blackdiamondresortco.com/","accessed":"2026-10-03","si":["culinary","family"],"booking_route":"(907) 683-4653","commission_status":"unknown","commission":"venue","tier_absent_reason":"does-not-compete","wells":["eat"],"draw_rank":35,"blurb":"Healy: \"Black Diamond Grill is located in the heart of Alaska!\" - \"freshly prepared meals in a casual Alaskan style\" with seafood, steaks and burgers; open daily May 13-September 21, 11 AM-10 PM."},{"name":"49th State Brewing - Healy","source":"https://www.49thstatebrewing.com/","accessed":"2026-10-03","si":["culinary","group"],"booking_route":"phone 907.683.2739 (no booking method read)","commission_status":"unknown","commission":"venue","tier_absent_reason":"does-not-compete","wells":["eat"],"draw_rank":36,"blurb":"\"Denali Park''s Only Brewpub\", at \"Mile 248.4 Parks Highway\" in Healy; 907.683.2739."},{"name":"Moose-AKa''s","source":"https://www.moose-akas.com/","accessed":"2026-10-03","si":["culinary","romance"],"booking_route":"email reservation, 24 hours ahead","commission_status":"unknown","commission":"venue","tier_absent_reason":"does-not-compete","wells":["eat"],"draw_rank":37,"blurb":"\"238.9 George Parks Hwy, Denali Park\": an \"Eastern European Restaurant and Tavern\" - moussaka, schnitzel, stuffed bell peppers, with vegan, vegetarian and gluten-free options; reservations only by email (mooseakasreservations@gmail.com), 24 hours ahead, no walk-ins. The page read still shows its 2025 season (opening \"June 9th\")."},{"name":"Prospector''s Pizzeria & Alehouse (closed for 2026)","source":"https://www.prospectorspizza.com/","accessed":"2026-10-03","si":["culinary","family"],"booking_route":"none - closed for the 2026 season; (907) 683-7437","commission_status":"unknown","commission":"venue","tier_absent_reason":"does-not-compete","wells":["eat"],"draw_rank":38,"blurb":"\"MILE POST 238.9 PARKS HWY. DENALI PARK\": wood stone-fired pizzas with Alaskan toppings incl. elk, salmon, reindeer and king crab. 🔴 \"We''re closed for the 2026 season. Thank you and see you again in spring 2027!\""},{"name":"Denali Doghouse (closed for 2026)","source":"https://www.denalidoghouse.com/","accessed":"2026-10-03","si":["culinary","family"],"booking_route":"none - closed for the 2026 season","commission_status":"unknown","commission":"venue","tier_absent_reason":"does-not-compete","wells":["eat"],"draw_rank":39,"blurb":"Buffalo hot dogs, with online ordering via Square. 🔴 \"Closed for the 2026 Season!\""},{"name":"Alaska Railroad Denali Star","source":"https://www.alaskarailroad.com/ride-a-train/our-trains/denali-star","accessed":"2026-10-03","si":["rail","senior","family","group"],"booking_route":"own website or 800.544.0552","commission_status":"unknown","commission":"operator","tier_absent_reason":"does-not-compete","wells":["move"],"draw_rank":40,"blurb":"Anchorage > Wasilla > Talkeetna > Denali > Fairbanks, a \"356-mile, 12-hour journey\"; \"GoldStar Service\" or \"Adventure Class\", both with dining-car access; baggage service at Denali; wheelchair access. The NPS: the railroad \"runs directly through Denali''s entrance\"."},{"name":"Trafalgar - Majestic Alaska (10 days)","source":"https://www.trafalgar.com/en-us/tours/majestic-alaska?tripcode=dsma","accessed":"2026-10-03","si":["group","senior","wildlife"],"booking_route":"trafalgar.com or a travel advisor","commission_status":"commissioned","commission":"operator","tier_absent_reason":"does-not-compete","commission_pct_low":5,"commission_pct_high":10,"commission_basis":"published","wells":["activities"],"draw_rank":41,"blurb":"A 10-day guided tour from Anchorage with Denali on Day 2 (\"Step Into The Wilderness Of Denali National Park\") and Day 3 (\"Uncover The Natural History Of Denali\"), then Fairbanks, Valdez and Seward; \"Guided throughout, with authentic local connections\"; from $5,495."},{"name":"Cosmos - Grand Alaskan Adventure (7 days)","source":"https://www.cosmos.com/tour/grand-alaskan-adventure/8420/","accessed":"2026-10-03","si":["senior","group","wildlife"],"booking_route":"cosmos.com or a travel advisor","commission_status":"unknown","commission":"operator","tier_absent_reason":"does-not-compete","commission_pct_low":3,"commission_pct_high":3,"commission_basis":"benchmark","wells":["activities"],"draw_rank":42,"blurb":"\"7 days from Anchorage to Anchorage\", with Denali \"two nights with free time to explore or join optional excursions, including a wildlife tour, sled dog kennel tour, and a flightseeing adventure\"; \"from $3,059\"."},{"name":"Healy","source":"https://www.nps.gov/dena/planyourvisit/eatingsleeping.htm","accessed":"2026-10-03","si":["family","motoring"],"booking_route":"none needed - a gateway town","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":43,"blurb":"The NPS: \"In fall, winter and spring (roughly mid-September to mid-May), the nearest restaurants and convenience stores are in Healy, 11 miles to the north.\" Home to 49th State Brewing (Mile 248.4) and Black Diamond Resort Co."}],"faq":[{"q":"How far is Denali National Park from Anchorage?","a":"The NPS puts the park \"240 miles north of Anchorage, 120 miles south of Fairbanks\", with the entrance at \"Mile 237 on Alaska Highway 3 (also called the George Parks Highway).\" The Alaska Railroad \"runs directly through Denali''s entrance.\"","source":"https://www.nps.gov/dena/planyourvisit/directions.htm","accessed":"2026-10-03"},{"q":"Can you drive through Denali National Park?","a":"Only part of the way. \"During summer, roughly late May through early September, private vehicles may drive the first fifteen miles of this road, to a place called Savage River.\" Beyond that, buses run - and \"Due to the Pretty Rocks landslide, the road is currently closed to all traffic at Mile 43.\"","source":"https://www.nps.gov/dena/planyourvisit/visiting-denali.htm","accessed":"2026-10-03"},{"q":"How much is the Denali National Park entrance fee?","a":"\"$15.00\" buys \"a 7-day entrance permit\", and \"Youth age 15 or younger are free.\" A Denali Annual Pass is \"$45.00\". The $15 fee is included in an adult tour bus ticket.","source":"https://www.nps.gov/dena/planyourvisit/fees.htm","accessed":"2026-10-03"},{"q":"Are there bus tours in Denali National Park?","a":"Yes - run by the Doyon/Aramark Joint Venture, with a naturalist who \"both drives the bus and narrates\". In 2026 the Natural History Tour was $116.75 adult and the Tundra Wilderness Tour $144.75 adult; \"Due to the Pretty Rocks Landslide, buses are traveling no further than Mile 43 of the Denali Park Road.\" Book at www.reservedenali.com or 1-800-622-7275.","source":"https://www.nps.gov/dena/planyourvisit/bus-tours.htm","accessed":"2026-10-03"},{"q":"Can you camp in Denali National Park?","a":"Yes. Riley Creek (year-round), Savage River and Teklanika River take RVs and tents; Sanctuary River and Igloo Creek are tent-only and reached by bus. \"Wonder Lake Campground is closed through 2026, due to the Pretty Rocks Construction project.\" \"Reservations can be made as early as December 1 of the year before your visit.\"","source":"https://www.nps.gov/dena/planyourvisit/campgrounds.htm","accessed":"2026-10-03"},{"q":"Is Denali National Park open in winter?","a":"Yes: \"Denali is not closed in winter!\" Visitors can ski, snowshoe, mush and watch for aurora; the Murie Science and Learning Center serves as \"Denali''s winter visitor center\" from late September to early May, and \"The Denali Park Road typically closes at mile 3 for several months.\"","source":"https://www.nps.gov/dena/planyourvisit/winter-activities.htm","accessed":"2026-10-03"},{"q":"When does Denali National Park close for the season?","a":"The park itself does not close, but transit buses stop \"the second Thursday after the Labor Day holiday each year\" and resume \"May 20 each year.\" In fall visitors can drive to Teklanika River (Mile 30) until heavy snow, after which only the first 3 miles stay plowed.","source":"https://www.nps.gov/dena/planyourvisit/shoulder-season.htm","accessed":"2026-10-03"},{"q":"What should you wear in Denali National Park?","a":"The NPS: \"Dress in layers, preferably made of wool or synthetic material that is able to insulate you even when wet. Bring rain gear or an umbrella.\" \"Rainy, chilly days are normal in summer\", and \"Bear spray is strongly encouraged for all hikers in Denali.\"","source":"https://www.nps.gov/dena/planyourvisit/safety.htm","accessed":"2026-10-03"},{"q":"What can you do in Denali National Park with kids?","a":"Families can \"Borrow a free discovery pack for the duration of your visit and explore Denali like a scientist\", follow the Junior Ranger programme \"in person or online\", and see the free sled dog demonstrations, for which \"No fees or reservations are required.\"","source":"https://www.nps.gov/dena/learn/kidsyouth/index.htm","accessed":"2026-10-03"},{"q":"Do you need reservations for Denali National Park?","a":"Not to enter, but bus seats and campsites are reserved through the concessioner: \"We will begin accepting reservations for the 2027 season on December 1, 2026\" (800.622.7275).","source":"https://www.reservedenali.com/","accessed":"2026-10-03"}],"seo":{"meta_title":"Denali National Park: Park Road Buses, Sled Dogs & Camping | TravelWell","meta_description":"Denali''s park road buses (to Mile 43 while Pretty Rocks is closed), free sled dog demos, six campgrounds, Healy and Cantwell stays, rafting and Alaska tours.","slug":"denali-national-park-alaska","primary_keyword":"Denali National Park","jsonld_type":"TouristDestination"},"hero":{"query":"Denali National Park park road bus"}}'::jsonb, 104)
