insert into public.destinations (id, region_code, name, country, line, status, depth, img, sub_region, si, feel, tier_range, price_band, draw_rank, data, position) values
  ('kenai-fjords-alaska', '12A', 'Kenai Fjords National Park', 'United States', 'Tidewater glaciers, Exit Glacier and the Harding Icefield', 'future', 'verified', 'mountainValley', 'Alaska', '{"wildlife","hiking","ocean","adventure","family","senior","group","glamping","parks"}', '{"dramatic","wild","coastal","remote","adventurous"}', '{}', null, null, '{"safety":{"posture":"book-freely","source":"https://www.gov.uk/foreign-travel-advice/usa","verified":"2026-10-08"},"jewels":[{"name":"Kenai Fjords Tours","source":"https://www.alaskacollection.com/day-tours/kenai-fjords-tours/","accessed":"2026-10-03","si":["wildlife","ocean","family","senior","group"],"booking_route":"own website booking (alaskacollection.com) or 1.888.478.3346; travel-trade affiliate login at affiliates.pursuitcollection.com","commission_status":"unknown","commission":"operator","tier_absent_reason":"does-not-compete","wells":["activities"],"draw_rank":1,"blurb":"\"Seward''s original wildlife and glacier cruise\", operating \"since 1978\"; narrated cruises from Seward from a 3-hour Resurrection Bay Express to a 6-hour Classic Kenai Fjords Park Tour, a 7-hour Captain''s Choice National Park Tour and an 8-hour Northwestern Fjord Tour, plus a 6-hour Glacier Dinner Cruise with \"a delicious multi-course meal\". Wildlife named: whales, sea otters, Steller sea lions, puffins. \"2026 Tour Dates: March 12 – September 27\". Part of the Alaska Collection; 1.888.478.3346."},{"name":"Exit Glacier Area","source":"https://www.nps.gov/kefj/planyourvisit/placestogo.htm","accessed":"2026-10-03","si":["hiking","family","senior","wildlife"],"booking_route":"none needed - \"No entrance fees are charged at Kenai Fjords National Park\"","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":2,"blurb":"\"Located just 12 miles outside of the community of Seward and accessible by road, the Exit Glacier Area is the easiest part of the park to visit.\" The road \"is not plowed during the winter months and is closed to automobiles\", typically \"from sometime in October to May depending on the year.\" A safety closure is in place \"from the toe of Exit Glacier to the end of the canyon where Exit Creek opens into the Outwash Plain.\""},{"name":"Harding Icefield Trail","source":"https://www.nps.gov/kefj/planyourvisit/harding_icefield_trail.htm","accessed":"2026-10-03","si":["hiking","adventure","wildlife"],"booking_route":"none needed - free park trail","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":3,"blurb":"\"The 7.8-mile round trip Harding Icefield Trail\" gains \"approximately 1,000 feet of elevation\" per mile; \"Allow at least 6-8 hours for the hike.\" \"The trail is strenuous!\" \"Black bears are spotted almost everyday from the Harding Icefield Trail.\" On 9/8/2026 the NPS reported it \"almost completely snow-free, with a few snow patches on the traverse to End of Trail.\""},{"name":"Major Marine Tours","source":"https://www.majormarine.com/","accessed":"2026-10-03","si":["wildlife","ocean","group","senior","family"],"booking_route":"own website booking; (907) 224-8030 or 800-764-7300","commission_status":"unknown","commission":"operator","tier_absent_reason":"does-not-compete","wells":["activities"],"draw_rank":4,"blurb":"\"a locally-owned, family company with over 30 years of sharing authentic Alaska adventures\", sailing from 1412 4th Ave, Seward: 8.5-hour Northwestern Fjord Cruise, 7.5-hour and 6-hour Kenai Fjords National Park Cruises, 4-hour Kenai Fjords Wildlife Cruise, 4-hour Spring Wildlife Cruise and private charters. \"Cruises 6 hours and over include a complimentary hearty deli lunch for all guests.\" \"2026 Cruise Season: March 7th - October 11th\". Offers \"Travel Trade & Group Travel\" services."},{"name":"Glacier View Loop","source":"https://www.nps.gov/kefj/planyourvisit/accessibility.htm","accessed":"2026-10-03","si":["senior","family","hiking"],"booking_route":"none needed - free park trail","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":5,"blurb":"\"A one-mile wheelchair-accessible loop (partially paved, partially compressed gravel) leads to a panoramic view of Exit Glacier\"; snow may affect access when the road opens in May, and limited wheelchairs are available to borrow at the Exit Glacier Nature Center."},{"name":"Kenai Fjords Glacier Lodge","source":"https://www.nps.gov/kefj/planyourvisit/eatingsleeping.htm","accessed":"2026-10-03","si":["wildlife","ocean","romance","adventure"],"booking_route":"own website (kenaifjordsglacierlodge.com) - not read, SSL error","commission_status":"unknown","commission":"hotel","tier_absent_reason":"not-established","wells":["stay"],"draw_rank":6,"blurb":"NPS: \"It is the only lodge on the Kenai Fjords coast, and is accessible solely by boat during the summer months.\" The lodge''s own website (kenaifjordsglacierlodge.com, linked by the NPS) failed with an SSL error when fetched."},{"name":"Aialik, Holgate and Willow public use cabins","source":"https://www.nps.gov/kefj/planyourvisit/publicusecabins_summer.htm","accessed":"2026-10-03","si":["adventure","ocean","family","group"],"booking_route":"Recreation.gov (\"Kenai Fjords National Park Cabins\") or 1-877-444-6777","commission_status":"none","commission":"hotel","tier_absent_reason":"not-established","wells":["stay"],"draw_rank":7,"blurb":"\"Two rustic Public Use Cabins, Aialik and Holgate, are available during the summer months (generally from Memorial Day weekend through Labor Day weekend)\", reached \"by water only, as there is no road or trail to either cabin.\" Aialik sleeps four, Holgate \"Contains six wooden beds that sleep six people\"; no electricity or running water. The Willow cabin at Exit Glacier opens once the road closes for winter. Fees: \"Coastal Public Use Cabins (summer only): $75 per night\"; \"Willow Cabin at Exit Glacier (winter only): $50 per night\"."},{"name":"Exit Glacier Nature Center","source":"https://www.nps.gov/kefj/planyourvisit/placestogo.htm","accessed":"2026-10-03","si":["family","senior","hiking"],"booking_route":"none needed - free","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":8,"blurb":"\"Learn about how glaciers are formed, go over your hiking plans with a ranger, find your stamp, and do a little shopping.\" Visitor centers are open \"from Memorial Day weekend (the weekend before the last Monday of May) through Labor Day\"; the Nature Center and its restrooms are wheelchair-accessible."},{"name":"Junior Glacier Ranger and Junior Fjord Ranger walks","source":"https://www.nps.gov/kefj/learn/kidsyouth/index.htm","accessed":"2026-10-03","si":["family","wildlife","hiking"],"booking_route":"none needed - free; ask rangers for current dates and times","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":9,"blurb":"\"Junior Glacier Ranger walks are available for visitors (recommended ages 5-12) in the summer\" at the Exit Glacier Nature Center, and \"Junior Fjord Ranger walks are available for visitors (recommended ages 8-12) in the summer\" at the Kenai Fjords Visitor Center; each earns a patch. Junior Ranger Adventure Guide \"(ages 4-12)\" and Explorer Journal \"(ages 13+)\"."},{"name":"Sea kayaking the fjords","source":"https://www.nps.gov/kefj/planyourvisit/kayaking.htm","accessed":"2026-10-03","si":["adventure","ocean","wildlife"],"booking_route":"none needed in the park; guided trips through CUA-authorised businesses (nps.gov/locations/alaska/services-kenai-fjords.htm)","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":10,"blurb":"\"The fjords are exposed to the Gulf of Alaska, with only a few protected coves, leading to challenging landings and sea conditions.\" \"Traveling with a guide is strongly recommended for inexperienced paddlers.\" Most kayakers arrive by water-taxi or charter drop-off in Aialik Bay, Northwestern Lagoon or Bear Glacier Lagoon."},{"name":"Exit Glacier Campground","source":"https://www.nps.gov/kefj/planyourvisit/camping.htm","accessed":"2026-10-03","si":["hiking","family","group","adventure"],"booking_route":"none - first-come, first-served, no fee","commission_status":"none","tier_absent_reason":"not-sold","wells":["stay"],"draw_rank":11,"blurb":"A \"12-site, tent-only campground\" on a \"first-come, first-served basis\" that \"frequently fills by early evening in July and August\"; up to \"two tents and/or eight people per site\"; a \"central food storage, cooking and dining shelter\", a water pump and pit toilets. \"No camping fees are charged at Kenai Fjords National Park.\" No sleeping in RVs or vehicles in the parking area."},{"name":"Alaska SeaLife Center","source":"https://www.alaskasealife.org/","accessed":"2026-10-03","si":["family","wildlife","group","senior"],"booking_route":"own website tickets (\"Hours & Tickets\") or (907) 224-6300","commission_status":"unknown","commission":"venue","tier_absent_reason":"does-not-compete","wells":["activities"],"draw_rank":12,"blurb":"A marine science facility in Seward (301 Railway Avenue) offering wildlife rescue and rehabilitation, research and education; special \"Marine Mammal Encounter,\" \"Octopus Encounter,\" and \"Puffin Encounter\" experiences, youth camps, \"Small Fry School\" for younger visitors, and a \"Groups\" section for tour wholesalers. (907) 224-6300."},{"name":"Kenai Fjords Wilderness Lodge","source":"https://www.alaskacollection.com/lodging/kenai-fjords-wilderness-lodge/","accessed":"2026-10-03","si":["wildlife","ocean","romance","wellness"],"booking_route":"own website booking (alaskacollection.com)","commission_status":"unknown","commission":"hotel","tier_absent_reason":"not-established","wells":["stay"],"draw_rank":13,"blurb":"Eight waterfront cabins on Fox Island, \"twelve miles south of Seward and accessible only by sea\"; \"a two-night stay, or linger longer with a four-night escape\" with meals and activities included (yoga, naturalist-led hikes, kayaking). 2027 season June 2 - September 11. Adventure Green Alaska certified."},{"name":"Seward Windsong Lodge","source":"https://www.alaskacollection.com/lodging/seward-windsong-lodge/","accessed":"2026-10-03","si":["hiking","family","senior","wildlife"],"booking_route":"own website booking or 1.800.808.8068","commission_status":"unknown","commission":"hotel","tier_absent_reason":"not-established","wells":["stay"],"draw_rank":14,"blurb":"Alongside the Resurrection River in the Exit Glacier Valley, near Seward and Kenai Fjords National Park; rooms with individual decks among the trees and no air conditioning; the on-site Resurrection Roadhouse. Operating dates \"May 14 – September 15 (2026)\" and \"May 13 – September 14 (2027)\"; \"now booking 2027\". 1.800.808.8068."},{"name":"Miller''s Landing","source":"https://www.millerslandingak.com/","accessed":"2026-10-03","si":["adventure","ocean","family","group"],"booking_route":"FareHarbor (own website) or reservations@millerslandingak.com","commission_status":"unknown","commission":"operator","tier_absent_reason":"not-established","commission_basis":"published","wells":["stay","activities","gear"],"draw_rank":15,"blurb":"A family-run \"adventure basecamp\" on Lowell Point, Seward, since 1982, offering \"lodging of all types, daily fishing charters and kayak tours\", cabins and campsites, a water taxi to remote areas and gear rentals for experienced boaters. 907-331-3113."},{"name":"Trafalgar Majestic Alaska","source":"https://www.trafalgar.com/en-us/tours/majestic-alaska","accessed":"2026-10-03","si":["group","senior","wildlife","rail"],"booking_route":"trafalgar.com (affiliate via Impact) or TourRadar (tourradar.com/t/161844)","commission_status":"commissioned","commission":"operator","tier_absent_reason":"does-not-compete","commission_pct_low":5,"commission_pct_high":10,"commission_basis":"published","wells":["activities"],"draw_rank":16,"blurb":"Trafalgar''s 10-day escorted \"Majestic Alaska\", Anchorage to Anchorage; Day 9 \"Glance At Glaciers\" runs \"Seward ➝ Kenai Fjords National Park ➝ Anchorage\" (Trafalgar). TourRadar''s listing of the same tour gives Day 9 as \"Anchorage to Seward\" with the \"Alaska Wildlife Conservation Center\" and an optional \"Kenai Fjords National Park Cruise\", \"All Ages Welcome\", \"Group Size: 20 - 48\". Departures listed May through October 2027."},{"name":"Howling Wolf Resort","source":"https://sewardhospitalitygroup.com/howling-wolf-resort","accessed":"2026-10-03","si":["glamping","family","wellness"],"booking_route":"own website (Seward Hospitality Group, FareHarbor); walk-ins welcome; Campspot listing states \"Online booking isn''t available for this campground right now\"","commission_status":"unknown","commission":"hotel","tier_absent_reason":"not-established","wells":["stay"],"draw_rank":17,"blurb":"\"Glamping cottages, canvas tents & RV sites on 34 acres\" outside Seward: the Glamour Creekview Cottage (\"Our most luxurious glamping experience\"), Glamour Tents and a Family Glamping Tent; stone-heated saunas, hot tubs and cold plunge tubs. \"RV sites offer electricity only, with no dump station or water.\" Pets at the RV park only."},{"name":"Riptide RV Resort","source":"https://www.riptidervresort.com/","accessed":"2026-10-03","si":["family","senior","ocean"],"booking_route":"own website (ResNexus)","commission_status":"unknown","commission":"hotel","tier_absent_reason":"not-established","wells":["stay"],"draw_rank":18,"blurb":"\"A waterfront Seward RV park built around one straightforward idea: put travelers close to the water, close to town, and close to the trailheads\" - 1823 Nash Rd on Resurrection Bay, full-hookup sites (electric, water, sewer) and Sawmill Creek Cabins; \"waterfront sites are limited.\" \"Peak season runs mid-May through mid-September.\""},{"name":"Harbor 360 Hotel","source":"https://www.harbor360hotel.com/","accessed":"2026-10-03","si":["wildlife","family","senior","group"],"booking_route":"own website or (907) 224-2550","commission_status":"unknown","commission":"hotel","tier_absent_reason":"not-established","wells":["stay"],"draw_rank":19,"blurb":"\"Premier waterfront hotel in the scenic harbor town of Seward\", \"locally-owned\", at 1412 4th Avenue with \"360 degree views of Resurrection Bay and the surrounding Kenai Mountains\"; \"Seward''s only hotel pool\", hot tub, breakfast, seasonal shuttle, \"Open year-round\"; cruise-and-hotel packages with Major Marine Tours. A 2026 hotel listing calls it \"formerly Holiday Inn Express Seward Harbor\" (travelness.com); the hotel''s own page names no brand."},{"name":"Seward","source":"https://www.seward.com/things-to-do/tours/day-cruises-and-boat-charters/","accessed":"2026-10-03","si":["ocean","wildlife","family"],"booking_route":"none needed - a town","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":20,"blurb":"The gateway town: \"Kenai Fjords National Park is located just outside the town of Seward\" (NPS), and the Seward Chamber & CVB calls the day cruise \"Seward''s most popular excursion\" - \"Trips range from 3.5 to 9 hours.\" Chamber visitor center, 2001 Seward Highway, (907) 224-8051."},{"name":"Resurrection Roadhouse","source":"https://www.alaskacollection.com/lodging/seward-windsong-lodge/dining/","accessed":"2026-10-03","si":["culinary","family","wine"],"booking_route":"OpenTable; reservations for parties of six or more","commission_status":"none","commission":"venue","tier_absent_reason":"does-not-compete","wells":["eat"],"draw_rank":21,"blurb":"\"Local Cuisine on Seward''s Best Patio\": \"sustainable Alaska seafood, complemented by local, seasonal sides and an award-winning wine list\"; breakfast buffet and a \"tide-to-table dinner menu\" with halibut, salmon and king crab; kids menus. Open daily May 14 – September 15; 31572 Herman Leirer Road, next to Windsong Lodge, on the road to Exit Glacier."},{"name":"The Cookery","source":"https://www.cookeryseward.com/","accessed":"2026-10-03","si":["culinary","wine","romance"],"booking_route":"walk-in only - first come, first served","commission_status":"none","commission":"venue","tier_absent_reason":"does-not-compete","wells":["eat"],"draw_rank":22,"blurb":"Chef Kevin Lane and Stacey Lane''s restaurant at 209 5th Avenue: \"fresh oysters delivered daily, locally farmed meats, produce sourced from the Kenai Peninsula, foraged finds, and fresh fish\". \"As of Summer 2025, we no longer accept reservations\"; no tables over 8. Its site states it is closed for the season, reopening in 2027."},{"name":"Seward Brewing Company","source":"https://www.sewardbrewery.com/","accessed":"2026-10-03","si":["culinary","group"],"booking_route":"walk-in; phone 907-422-0337","commission_status":"none","commission":"venue","tier_absent_reason":"does-not-compete","wells":["eat"],"draw_rank":23,"blurb":"\"Seward Brewing Company is a family-owned & operated brew pub located in downtown Seward, Alaska\", craft beer with food built on \"unique ingredients\"; open 3pm-9pm, closed Tuesdays; it closes for the winter on September 14th each year. 907-422-0337."},{"name":"Miller''s Landing Cafe","source":"https://www.millerslandingak.com/cafe","accessed":"2026-10-03","si":["culinary","ocean","family"],"booking_route":"walk-in","commission_status":"none","commission":"venue","tier_absent_reason":"does-not-compete","wells":["eat"],"draw_rank":24,"blurb":"\"Waterfront dining, coffee, local beer, and hearty meals in Seward\" on Lowell Point, with \"one of the best dining views in town, with a front-row seat to Resurrection Bay\" and a \"Cook Your Catch\" service for fish caught on its charters. \"Our Last Day is October 4th\"; it reopens in spring."},{"name":"Chinooks Seafood and Grill","source":"https://www.chinooksak.com/","accessed":"2026-10-03","si":["culinary","ocean","family"],"booking_route":"phone 907-224-2207","commission_status":"none","commission":"venue","tier_absent_reason":"does-not-compete","wells":["eat"],"draw_rank":25,"blurb":"\"SEAFOOD & GRILL\" at 1404 Fourth Avenue, \"Located in the heart of the harbor in Seward Alaska\", \"Locally owned and operated\"; cocktails, wine and local Alaska beers. 2026 summer hours 4pm - 8pm Sunday, Monday, Wednesday, Thursday, and \"FRIDAY AND SATURDAY open 4pm - 9pm\". 907-224-2207."},{"name":"The Salmon Bake","source":"https://www.sewardsalmonbake.com/","accessed":"2026-10-03","si":["culinary","family","group"],"booking_route":"walk-in only","commission_status":"none","commission":"venue","tier_absent_reason":"does-not-compete","wells":["eat"],"draw_rank":26,"blurb":"Seward restaurant with \"KING CRAB LEGS\", nightly specials and \"Prime Rib every Friday\", smoking its meats over \"local Alaskan Birch and Alder wood\". \"Sorry, we do not take reservations.\" Its site states \"CLOSED UNTIL MAY 2027\". 907-224-2204."},{"name":"Rain gear, layers and water filter for the Harding Icefield","source":"https://www.nps.gov/kefj/planyourvisit/harding_icefield_trail.htm","accessed":"2026-10-03","si":["hiking","adventure"],"booking_route":"affiliate referral to rei.com (AvantLink)","commission_status":"commissioned","commission":"affiliate","tier_absent_reason":"does-not-compete","commission_pct_low":5,"commission_pct_high":5,"commission_basis":"published","wells":["gear"],"draw_rank":27,"blurb":"NPS: \"Bring warm clothes, rain gear, sturdy footwear, sunglasses, and sunscreen. Carry plenty of water (at least 2 liters per person), or bring along a filter.\" Hikers should prepare for storms, high winds, intense sunlight and sudden temperature changes; the upper trail is often snow-covered through early July."},{"name":"Cook stove, bedding and water treatment for the coastal cabins","source":"https://www.nps.gov/kefj/planyourvisit/publicusecabins_summer.htm","accessed":"2026-10-03","si":["adventure","ocean","family"],"booking_route":"affiliate referral to campsaver.com (AvantLink)","commission_status":"commissioned","commission":"affiliate","tier_absent_reason":"does-not-compete","commission_pct_low":7,"commission_pct_high":7,"commission_basis":"published","wells":["gear"],"draw_rank":28,"blurb":"For the Aialik and Holgate cabins, which have no electricity or running water, the NPS says to bring \"Bedding and sleeping pads\", a \"Cook stove, lighter and utensils\" and \"Drinking water and/or means to treat drinking water\", plus food, clothing, emergency supplies and toilet paper. \"Paddling from Seward and rounding Aialik Cape in a kayak is not recommended.\""},{"name":"Exit Glacier ranger-led walks and pavilion talks","source":"https://www.nps.gov/kefj/planyourvisit/ranger-programs.htm","accessed":"2026-10-03","si":["senior","family","hiking","group"],"booking_route":"none needed - meet at the Exit Glacier Nature Center","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":29,"blurb":"From the Exit Glacier Nature Center, \"Lasting about 1 hour, 30 minutes, the walk will follow the trail to the Glacier Overlook\" - \"May 23 - September 7, 2026, 10:00 AM, 2:00 PM\"; \"The first part of the program will follow the trail to the Glacier View lookout, and is wheelchair accessible.\" Pavilion talks: \"Lasting about 20 minutes, the ranger will give an interactive presentation\", \"June 6 - August 15, 2026, 1:30 PM\"."},{"name":"Flightseeing over the Harding Icefield","source":"https://www.nps.gov/kefj/planyourvisit/flightseeing.htm","accessed":"2026-10-03","si":["adventure","wildlife","senior"],"booking_route":"through Seward flightseeing operators (none named by the NPS; Seward Chamber list)","commission_status":"unknown","commission":"operator","tier_absent_reason":"does-not-compete","wells":["activities"],"draw_rank":30,"blurb":"NPS: overflights give views of \"glaciers, fjords, and wildlife\" - a \"mountain goat traversing a rocky ledge\", a \"brown bear fishing in a salmon-choked stream\" - and the Harding Icefield, an \"expanse of ice broken only by isolated mountain peaks, or nunataks.\" The NPS names no operator and points to the Seward Chamber of Commerce for \"a list of operators that offer scenic overflights.\""}],"faq":[{"q":"Is Kenai Fjords National Park free?","a":"Yes. The NPS states \"No entrance pass required\" and \"No camping fees are charged at Kenai Fjords National Park\"; the park \"does not sell or require any park passes.\" The public use cabins carry a fee: \"$75 per night\" for the coastal cabins in summer and \"$50 per night\" for the Willow cabin in winter.","source":"https://www.nps.gov/kefj/planyourvisit/fees.htm","accessed":"2026-10-03"},{"q":"Can you drive to Kenai Fjords National Park from Anchorage?","a":"Yes, to the Exit Glacier area. The park is \"126 miles south of Anchorage\" via the \"Seward Highway (AK-1)\", which becomes \"AK-9 around mile 35\". \"Herman Leirer Road (commonly called ''Exit Glacier Road'') is the only road into Kenai Fjords National Park\", 8.6 miles from the Seward Highway. The Alaska Railroad runs Anchorage to Seward \"during the summer months (May - September)\".","source":"https://www.nps.gov/kefj/planyourvisit/directions.htm","accessed":"2026-10-03"},{"q":"Can you camp in Kenai Fjords National Park?","a":"Yes. Exit Glacier Campground is a \"12-site, tent-only campground\" on a \"first-come, first-served basis\" that \"frequently fills by early evening in July and August\". Backcountry camping is permitted in most of the park, but not \"within 500 feet of a public use cabin or within 1/8 mile of a road or trail at Exit Glacier.\" \"No permits or reservations are required for any camping.\"","source":"https://www.nps.gov/kefj/planyourvisit/camping.htm","accessed":"2026-10-03"},{"q":"What is the best time to visit Kenai Fjords National Park?","a":"\"The park is open year round. The primary months to visit are June, July, and August\", with \"reduced services in the area during the months of May and September.\" Visitor centers open \"from Memorial Day weekend (the weekend before the last Monday of May) through Labor Day (first Monday of September)\".","source":"https://www.nps.gov/kefj/planyourvisit/hours.htm","accessed":"2026-10-03"},{"q":"Can you visit Kenai Fjords National Park in October?","a":"The park is open year round, but the Exit Glacier road \"is not plowed during the winter months and is closed to automobiles. This means the park is inaccessible by car when the road is covered in snow, typically from sometime in October to May depending on the year.\"","source":"https://www.nps.gov/kefj/planyourvisit/hours.htm","accessed":"2026-10-03"},{"q":"Where do Kenai Fjords National Park boat tours leave from in Seward?","a":"\"Boat tours depart Seward''s small boat harbor daily in the summer months\" - \"Full-day tours that venture out to the park''s tidewater glaciers\" and \"half-day tours that stay in the more protected waters of Resurrection Bay.\" The NPS notes that the park \"does not have any authorized concessionners or park rangers on boat tours.\"","source":"https://www.nps.gov/kefj/planyourvisit/boattours.htm","accessed":"2026-10-03"},{"q":"How do you book the Kenai Fjords National Park public use cabins?","a":"Bookings open January 1st each year at Recreation.gov (search \"Kenai Fjords National Park Cabins\") or by calling 1-877-444-6777. Aialik sleeps four and Holgate \"Contains six wooden beds that sleep six people\"; both are reached by float plane, water taxi, private vessel or charter boat. \"Reservations must be canceled at least 14 days in advance to receive a refund.\"","source":"https://www.nps.gov/kefj/planyourvisit/publicusecabins_summer.htm","accessed":"2026-10-03"},{"q":"Where can you stay in Kenai Fjords National Park?","a":"Inside the park: the 12-site tent-only Exit Glacier Campground, the Aialik and Holgate coastal cabins in summer, the Willow cabin in winter, and the Kenai Fjords Glacier Lodge - \"the only lodge on the Kenai Fjords coast\", \"accessible solely by boat during the summer months.\" Seward offers \"a full range of hotels, B&B''s, RV campgrounds, restaurants, and grocery stores\".","source":"https://www.nps.gov/kefj/planyourvisit/eatingsleeping.htm","accessed":"2026-10-03"},{"q":"What is there for kids at Kenai Fjords National Park?","a":"\"Junior Glacier Ranger walks are available for visitors (recommended ages 5-12) in the summer\" at the Exit Glacier Nature Center and \"Junior Fjord Ranger walks\" (recommended ages 8-12) at the Kenai Fjords Visitor Center, each with a patch; families can \"check out an Art for Parks or a Discovery backpack\". The Junior Ranger Adventure Guide is for ages 4-12 and the Explorer Journal for 13+.","source":"https://www.nps.gov/kefj/learn/kidsyouth/index.htm","accessed":"2026-10-03"}],"seo":{"meta_title":"Kenai Fjords National Park: Exit Glacier, Cruises & Cabins | TravelWell","meta_description":"No entrance fee, Exit Glacier by road from Seward, the 7.8-mile Harding Icefield Trail, glacier cruises March to October, and coastal cabins opening January 1.","slug":"kenai-fjords-national-park-alaska","primary_keyword":"Kenai Fjords National Park","jsonld_type":"TouristDestination"},"hero":{"query":"Kenai Fjords National Park tidewater glacier"}}'::jsonb, 105),
  ('wrangell-st-elias-alaska', '12A', 'Wrangell-St. Elias National Park', 'United States', 'Kennecott mill town and the Root Glacier', 'future', 'verified', 'mountainValley', 'Alaska', '{"hiking","adventure","culture","expedition","family","parks"}', '{"wild","remote","rugged","historic","adventurous"}', '{}', null, null, '{"safety":{"posture":"book-freely","source":"https://www.gov.uk/foreign-travel-advice/usa","verified":"2026-10-08"},"jewels":[{"name":"Kennecott Mines National Historic Landmark","source":"https://www.nps.gov/wrst/learn/historyculture/kennecott-mines-national-historic-landmark.htm","accessed":"2026-10-03","si":["culture","family","senior","hiking"],"booking_route":"none needed - the park charges no entrance fee","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":1,"blurb":"\"Kennecott is considered the best remaining example of early 20th Century copper mining\"; \"From 1911 to 1938, nearly $200 million worth of copper was processed.\" Listed on the National Register in 1978, a National Historic Landmark since 1986; exhibits in the General Store, the North Sacking Shed and the General Manager''s Office."},{"name":"Root Glacier Trail","source":"https://www.nps.gov/wrst/faqs.htm","accessed":"2026-10-03","si":["hiking","adventure","family"],"booking_route":"none needed - free park trail","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":2,"blurb":"\"Of the 5,000 square miles of glacial ice in Wrangell-St. Elias, the Root Glacier is the most accessible. A moderate 1 1/2 mile walk from the historic mining town of Kennecott along the Root Glacier Trail leads you onto the glacier. Be aware that glaciers can be dangerous.\""},{"name":"Kennecott Mill Town Tour (St. Elias Alpine Guides)","source":"https://www.steliasguides.com/trips/kennecott-mill-town-tour/","accessed":"2026-10-03","si":["culture","family","senior","group"],"booking_route":"own website (BOOK NOW)","commission_status":"unknown","commission":"operator","tier_absent_reason":"does-not-compete","wells":["activities"],"draw_rank":3,"blurb":"\"St. Elias Alpine Guides holds the exclusive concession with the National Park Service, and access to the 14-story Concentration Mill is only possible through this tour.\" Two hours, about a mile; adult (13+) $36, child (12-) $18; \"All ages welcome\"; \"ADVANCED RESERVATIONS STRONGLY ENCOURAGED!\""},{"name":"Wrangell Mountain Air flightseeing","source":"https://www.wrangellmountainair.com/alaska-flightseeing-tours","accessed":"2026-10-03","si":["adventure","senior","family","wildlife"],"booking_route":"request form and email on the own website","commission_status":"unknown","commission":"operator","tier_absent_reason":"does-not-compete","wells":["activities","fly"],"draw_rank":4,"blurb":"McCarthy-based since 1992; \"all flightsees originate from and return to McCarthy, and there is a two person minimum\". Mile High Cliff Tour \"50 minute - $330/person\"; Thirteen Glacier Tour \"70 minute - $405/person\" over the Nizina, Chitistone Canyon and the University Range."},{"name":"Kennicott Wilderness Guides glacier hikes","source":"https://kennicottguides.com/hiking-trips-overview/","accessed":"2026-10-03","si":["adventure","hiking","family"],"booking_route":"own website; phone 1-800-664-4537 / 907-554-1044","commission_status":"unknown","commission":"operator","tier_absent_reason":"does-not-compete","wells":["activities"],"draw_rank":5,"blurb":"Half-Day Glacier Hike (5 hours), Full-Day (7-8 hours), Ice Explorer Climb & Hike - \"Great for families with mixed abilities\" - fly-in hikes and Donoho Falls; trips include \"Round-trip transportation from your local lodging\" and \"Any technical, or glacier gear required for the hike.\" \"Currently booking trips for 2026!\""},{"name":"St. Elias Alpine Guides multi-day Group Trips","source":"https://www.steliasguides.com/trips/multi-day-trips/","accessed":"2026-10-03","si":["group","expedition","hiking","adventure"],"booking_route":"own website online booking or a call with the Expedition Coordinator; deposit, balance 30 days before","commission_status":"unknown","commission":"operator","tier_absent_reason":"does-not-compete","wells":["activities","gear"],"draw_rank":6,"blurb":"\"the oldest continuously operating business in Wrangell-St. Elias National Park\", guiding \"since 1978\". Set-date Group Trips - basecamp hiking, backpacking, rafting, mountaineering - that \"max out at 8 participants and 12 participants for rafting trips\"; \"We''ll run the trip even if only 1 person signs up!\"; trip packages arrange \"transportation to and from the Wrangells, local lodging\". FAQ: \"Limited rental equipment is available to our multi-day trip guests.\""},{"name":"Kennicott Wilderness Guides Package Trips","source":"https://kennicottguides.com/package-trips-overview/","accessed":"2026-10-03","si":["group","family","adventure"],"booking_route":"own website; phone 1-800-664-4537","commission_status":"unknown","commission":"operator","tier_absent_reason":"does-not-compete","wells":["activities"],"draw_rank":7,"blurb":"\"two, three, and five-day itineraries\": Water & Ice (2 days), Water, Ice & Air (3 days, adds a scenic flight to a fly-in hike), Water, Ice & Basecamp (5 days, \"3 days of basecamping\"). \"Each trip includes a private guide, prepared lunches, and flexible scheduling\"; \"Transportation to McCarthy-Kennicott and lodging are not included.\""},{"name":"Wrangell Mountain Air Chitina-McCarthy flights and Glacier Adventure Day Trip","source":"https://www.wrangellmountainair.com/glacier-adventure-day-trip-to-mccarthy","accessed":"2026-10-03","si":["adventure","senior","hiking"],"booking_route":"request form on the own website","commission_status":"unknown","commission":"operator","tier_absent_reason":"does-not-compete","wells":["fly","activities"],"draw_rank":8,"blurb":"Scheduled flights leave Chitina 9:05a and McCarthy 5:00p. Glacier Adventure Day Trip (flight plus a half-day Root Glacier hike with a St. Elias Alpine guide and a Kennicott Glacier Lodge sack lunch) \"$ 590 /person (includes excise tax)\"; Packrafting Adventure Day Trip with Kennicott Wilderness Guides \"$ 780 /person\"; children 12 and under $20 off."},{"name":"Copper Valley Air Service","source":"https://www.alaska.org/destination/mccarthy/transportation","accessed":"2026-10-03","si":["adventure","senior"],"booking_route":"phone (907) 822-4200 (Copper Valley Chamber listing)","commission_status":"unknown","commission":"operator","tier_absent_reason":"does-not-compete","wells":["fly","move"],"draw_rank":9,"blurb":"Year-round from Glennallen: \"Flightseeing tours of Wrangell St. Elias National Park. Mail plane flights or scheduled service between Anchorage, Glennallen, and McCarthy\"; listed at \"Flightseeing $350+ | Air Taxi $450+ One Way\". Its own site did not resolve when fetched; sourced to the Alaska.org listing."},{"name":"Ma Johnson''s Historic Hotel","source":"https://www.mccarthylodge.com/ma-johnson-hotel/","accessed":"2026-10-03","si":["culture","romance","senior"],"booking_route":"own website - Cloudbeds booking engine (us2.cloudbeds.com)","commission_status":"unknown","commission":"hotel","tier_absent_reason":"not-established","wells":["stay"],"draw_rank":10,"blurb":"\"Pete & Ma Johnson''s restored boarding house\" in McCarthy; \"There are 20 rooms in Ma Johnson''s\"; rooms carry \"Luxury Linens\", robes, breakfast and a \"Complimentary Copper Town Shuttle Pass - NPS authorized transportation\". The lodge calls it \"the only authentic historic hotel in the park.\""},{"name":"Kennicott Glacier Lodge","source":"https://www.alaska.org/detail/kennicott-glacier-lodge","accessed":"2026-10-03","si":["romance","culture","family"],"booking_route":"phone 907-258-2350 / 800-582-5128 (own site not read - HTTP 403)","commission_status":"unknown","commission":"hotel","tier_absent_reason":"not-established","wells":["stay","eat"],"draw_rank":11,"blurb":"In Kennecott itself: the Main Lodge (built 1987) has \"a 190-foot-long front porch\" and 23 rooms with shared baths; the South Wing''s 20 rooms each have a private bath and two queens; breakfast buffet, lunch from a menu, \"dinner at a single seating with a fixed menu.\" Own site refused the fetch (HTTP 403); sourced to Alaska.org."},{"name":"Ultima Thule Lodge","source":"https://www.ultimathulelodge.com/","accessed":"2026-10-03","si":["ultra","group","romance","adventure"],"booking_route":"reservations page on the own website; info@ultimathulelodge.com","commission_status":"unknown","commission":"hotel","tier_absent_reason":"not-established","wells":["stay","fly"],"draw_rank":12,"blurb":"\"an adventure centric wilderness outpost inside the vast Wrangell/St. Elias Mountains\", \"a hundred miles from paved roads\", on a glacier river inside the park; bush-plane adventures; \"stays are available May-September\"; \"a haven for small groups and intimate gatherings\" with Whole Package private-use reservations."},{"name":"Copper River Princess Wilderness Lodge","source":"https://www.princesslodges.com/princess-alaska-lodges/copper-river-lodge/","accessed":"2026-10-03","si":["senior","group","family"],"booking_route":"own website; (907) 822-4000","commission_status":"unknown","commission":"hotel","tier_absent_reason":"not-established","wells":["stay"],"draw_rank":13,"blurb":"85 rooms on 200 acres \"near the junction of the Klutina and Copper Rivers\", \"just four miles from the Wrangell-St. Elias National Park visitor''s center\"; the Two Rivers Restaurant; a Guest Service Desk books Gulkana River rafting and Kennicott visits; Princess sells it inside Alaska vacation packages."},{"name":"Old Town Copper Center Inn & Restaurant","source":"https://www.oldtowncoppercenter.com/","accessed":"2026-10-03","si":["motoring","family","senior"],"booking_route":"Book Now on the own website; (907) 822-3245","commission_status":"unknown","commission":"hotel","tier_absent_reason":"not-established","wells":["stay"],"draw_rank":14,"blurb":"Traces its roots to \"the original Copper Center Lodge, established in 1896 along Alaska''s historic Richardson Trail\"; the original lodge was \"lost to fire\" in 2012 and \"historic outbuildings remain\". Guest rooms plus Nummy''s Restaurant; \"Minutes from Wrangell-St. Elias National Park\"."},{"name":"Lancaster''s Backpacker Hotel","source":"https://www.mccarthylodge.com/lancaster-backpackers-hotel/","accessed":"2026-10-03","si":["hiking","adventure","group"],"booking_route":"own website - Cloudbeds booking engine","commission_status":"unknown","commission":"hotel","tier_absent_reason":"not-established","wells":["stay"],"draw_rank":15,"blurb":"McCarthy Lodge''s budget house: \"budget-friendly accommodations with shared bathrooms, basic amenities, and a casual, social atmosphere, ideal for backpackers\"; private rooms for one to four, breakfast at McCarthy Lodge and the Copper Town Shuttle pass included."},{"name":"Base Camp Kennicott","source":"https://www.basecampkennicott.com/","accessed":"2026-10-03","si":["adventure","motoring","group"],"booking_route":"no reservation; check in with the camp host","commission_status":"none","commission":"hotel","tier_absent_reason":"not-established","wells":["stay"],"draw_rank":16,"blurb":"At \"Mile 59.4 McCarthy Road End\" by the footbridge: \"Uncrowded, Open Camping Sites - Tents/Cars/Trailers/RVs (no hook-ups)\"; open \"MAY 21 through Sept 30, 2026\"; 2026 rates: 24-hour parking $12, basic camping $35, oversize (over 25 feet) $45; \"RESERVATIONS ARE NOT REQUIRED.\""},{"name":"Tolsona Wilderness Campground","source":"https://tolsonacampground.com/rates","accessed":"2026-10-03","si":["motoring","family","group"],"booking_route":"Campspot (campspot.com/book/tolsona-campground); phone (907) 822-3900","commission_status":"commissioned","commission":"hotel","tier_absent_reason":"not-established","commission_pct_low":3,"commission_pct_high":3,"commission_basis":"published","wells":["stay"],"draw_rank":17,"blurb":"Glennallen: \"RV sites equipped with water and 30 or 50 amp electric hook-ups\", creekside tent sites, bathrooms, showers, laundry, dump station, yurts that \"have electric, heat and can sleep up to six people\" (no bedding), three group sites \"for up to 15 RVs\", themed weekends and a playground. Booked on Campspot."},{"name":"Northern Nights Campground & RV Park","source":"https://northernnightscampground.com/the-park-and-facilities/","accessed":"2026-10-03","si":["motoring","family"],"booking_route":"phone (907) 822-3199 or the contact form","commission_status":"unknown","commission":"hotel","tier_absent_reason":"not-established","wells":["stay"],"draw_rank":18,"blurb":"Mile Post 188.7 Glenn Highway, Glennallen: 28 wooded RV sites (5 full hook-up, 16 pull-thru), 5 dry tent sites, \"RV sites are 50- 60 +feet in length\" with some 70-90 feet, showers, laundry, free Wi-Fi; \"2025 Marks our 35th season!\""},{"name":"Kendesnii Campground","source":"https://www.nps.gov/wrst/planyourvisit/camping-along-the-nabesna-road.htm","accessed":"2026-10-03","si":["motoring","family","wildlife"],"booking_route":"none - first come, first served; no reservations taken","commission_status":"none","tier_absent_reason":"not-sold","wells":["stay"],"draw_rank":19,"blurb":"\"the only National Park Service campground in the park\" at Mile 27.8 Nabesna Road: 10 sites, each with a picnic table and fire ring, \"can accommodate a small to medium RV\"; \"free and open year-round. No reservations are required and none are taken.\" Canoeing, waterfowl and grayling fishing."},{"name":"Public-use cabins","source":"https://www.nps.gov/wrst/planyourvisit/public-use-cabins.htm","accessed":"2026-10-03","si":["expedition","hiking","group"],"booking_route":"NPS email form for the four reservable cabins","commission_status":"none","commission":"hotel","tier_absent_reason":"not-established","wells":["stay"],"draw_rank":20,"blurb":"\"All cabins are remote and very rustic\"; \"Most cabins are accessible only by flying into remote airstrips.\" Viking Lodge, Caribou Creek, Nugget Creek and Esker Stream \"are the only cabins that require reservations\"; the rest are first come, first served. \"The park does not stock: firewood, water, dishes, supplies, sleeping pads, bedding\"."},{"name":"Wrangell-St. Elias Visitor Center and Ahtna Cultural Center, Copper Center","source":"https://www.nps.gov/wrst/planyourvisit/wrangell-st-elias-visitor-center.htm","accessed":"2026-10-03","si":["senior","family","culture"],"booking_route":"none needed - free visitor center","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":21,"blurb":"Mile 106.8 Richardson Highway, \"about 10 miles south of the intersection of the Glenn Highway and the Richardson Highway in Glennallen\": film, exhibits, a short trail, the park store. In the same complex the Ahtna Cultural Center, \"Operated by Ahtna, Incorporated\", shows \"a beautifully hand-built fish wheel\". 2026 hours May 11 - September 20, 9-5."},{"name":"Junior Ranger and ranger programmes","source":"https://www.nps.gov/wrst/planyourvisit/ranger-guided-tours.htm","accessed":"2026-10-03","si":["family","senior","culture"],"booking_route":"none needed - free; booklets at any visitor center","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":22,"blurb":"\"Throughout the summer months, park rangers present free interpretive talks, guided walks, and evening programs. The Junior Ranger program is available too! This is a free program for kids of all ages\"; a Junior Ranger Angler booklet too. Weekend evening programmes at the Kennecott Recreation Hall."},{"name":"Kennecott Visitor Center","source":"https://www.nps.gov/wrst/planyourvisit/kennecott-visitor-center.htm","accessed":"2026-10-03","si":["culture","family","senior"],"booking_route":"none needed - free","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":23,"blurb":"\"located in the historic Blackburn School within the Kennecott Mill Town\", \"5 miles north from McCarthy\": exhibits, park film in the General Store, ranger programmes, an Alaska Geographic bookstore, backcountry trip planning. 2026 hours May 23 - September 13, daily 9-5; closed fall to spring."},{"name":"McCarthy Road","source":"https://www.nps.gov/wrst/planyourvisit/directions-mccarthy-rd-and-kennecott.htm","accessed":"2026-10-03","si":["motoring","overland","adventure"],"booking_route":"none needed - public road","commission_status":"none","tier_absent_reason":"not-sold","wells":["move"],"draw_rank":24,"blurb":"\"a narrow, gravel road that is 59 miles to the Kennicott River Bridge\" on the old Copper River & Northwestern Railway route: \"Drive slow. Be aware of soft road edges, potholes, and railroad ties and possible spikes.\" It is \"owned and operated by the State of Alaska\". Free day parking at the State Wayside (mile 55) or the McCarthy Road Information Station (mile 58.6)."},{"name":"Nabesna Road","source":"https://www.nps.gov/wrst/planyourvisit/camping-along-the-nabesna-road.htm","accessed":"2026-10-03","si":["motoring","wildlife","overland"],"booking_route":"none needed - public road; first come, first served pullouts","commission_status":"none","tier_absent_reason":"not-sold","wells":["move"],"draw_rank":25,"blurb":"From mile 60 of the Tok Cutoff, \"nestled in a valley between two mountain ranges\": a \"gravel road that is 42 miles long, with 3 stream crossings\"; pullout campsites at Rufus Creek, Kettle Lake, Dead Dog Hill, Rock Lake and Jack Creek, where \"you may be able to view Dall Sheep.\" No fuel in Slana or on the road."},{"name":"Bonanza Mine and Jumbo Mine trails","source":"https://www.nps.gov/wrst/planyourvisit/mccarthy-rd-kennecott-trails.htm","accessed":"2026-10-03","si":["hiking","culture","adventure"],"booking_route":"none needed - free park trails","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":26,"blurb":"From Kennecott: Bonanza Mine Trail, \"Strenuous day hike to tremendous views and remnants of the Bonanza Mine bunkhouse\"; Jumbo Mine Trail, \"Strenuous day hike to panoramic views and remnants of the Jumbo Mine bunkhouse.\""},{"name":"Erie Mine Trail (partly washed out)","source":"https://www.nps.gov/wrst/planyourvisit/backpacking.htm","accessed":"2026-10-03","si":["hiking","expedition"],"booking_route":"none needed - free park route","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":27,"blurb":"\"Hike on a primitive trail alongside the Root Glacier for 4 miles (one way)\" toward the Erie Mine cables and the Stairway Icefall. ⚠️ NPS: \"Update fall 2023: A landslide has washed out a significant portion of the trail several miles in. This point has been marked with signage and travel beyond it is not recommended.\" The Erie Mine Trail food box \"was REMOVED\"."},{"name":"Crystalline Hills Trail","source":"https://www.nps.gov/wrst/planyourvisit/mccarthy-rd-kennecott-trails.htm","accessed":"2026-10-03","si":["hiking","family","senior"],"booking_route":"none needed - free park trail","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":28,"blurb":"McCarthy Road Mile 34.8: \"2.5 mile loop\", \"2-3 hours\", \"Easy to Moderate\", \"Road access, beautiful views\"; \"bug spray is highly recommended in summer.\""},{"name":"Donoho Basin and Jumbo Creek backcountry camping","source":"https://www.nps.gov/wrst/planyourvisit/camping-along-the-mccarthy-road-and-kennecott-area.htm","accessed":"2026-10-03","si":["expedition","group","hiking"],"booking_route":"none - group registration at a visitor center or wrst_backcountry@nps.gov","commission_status":"none","tier_absent_reason":"not-sold","wells":["stay"],"draw_rank":29,"blurb":"Jumbo Creek, \"1.4 miles north by trail past Kennecott mill town\", primitive NPS camping with bear boxes; Donoho Basin, 3-6 miles north, where a group \"of more than 8 people, maximum 12\" must register with the park. \"This route requires glacier travel experience and equipment.\""},{"name":"Sport hunting in the national preserve","source":"https://www.nps.gov/wrst/planyourvisit/hunting.htm","accessed":"2026-10-03","si":["expedition","wildlife"],"booking_route":"Alaska state licence; a registered guide where required","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":30,"blurb":"\"Sport hunting is ONLY allowed within the NATIONAL PRESERVE and must be conducted in accordance with Alaska State Law\"; \"An Alaska state hunting license is required for all hunters age 16 or older\"; registered guides operate under permit, from \"private fly-in lodging facilities\" to \"basic ''spike'' camp operations accessible by horseback.\""},{"name":"Bear-resistant food container","source":"https://www.nps.gov/wrst/planyourvisit/bear-resistant-food-containers.htm","accessed":"2026-10-03","si":["hiking","expedition","adventure"],"booking_route":"affiliate referral to bearvault.com (AvantLink)","commission_status":"commissioned","commission":"affiliate","tier_absent_reason":"does-not-compete","commission_pct_low":8,"commission_pct_high":8,"commission_basis":"published","wells":["gear"],"draw_rank":31,"blurb":"\"Bear Resistant Food Containers (BRFC) are required for all backcountry camping\". \"You need to buy or rent a BRFC for your backcountry trip prior to your arrival at the park\"; there is \"a limited amount to borrow at the Visitor Centers and Ranger Stations\". Each \"holds enough food for one person for about 5 days\"."},{"name":"Crampons or ice spikes for the Root Glacier","source":"https://www.nps.gov/wrst/faqs.htm","accessed":"2026-10-03","si":["hiking","adventure"],"booking_route":"affiliate referral to blackdiamondequipment.com (AvantLink)","commission_status":"commissioned","commission":"affiliate","tier_absent_reason":"does-not-compete","commission_pct_low":7,"commission_pct_high":7,"commission_basis":"published","wells":["gear"],"draw_rank":32,"blurb":"NPS on the Root Glacier: \"It is recommended to wear crampons or ice spikes on your shoes and go with an experienced guide.\" On a guided hike the guide supplies them: St. Elias Alpine Guides \"do not rent out crampons\" but include them on glacier tours."},{"name":"Satellite communicator for the backcountry","source":"https://www.nps.gov/wrst/planyourvisit/backcountry.htm","accessed":"2026-10-03","si":["expedition","hiking","adventure"],"booking_route":"affiliate referral to zoleo.com (AvantLink)","commission_status":"commissioned","commission":"affiliate","tier_absent_reason":"does-not-compete","commission_pct_low":10,"commission_pct_high":10,"commission_basis":"published","wells":["gear"],"draw_rank":33,"blurb":"NPS: \"Satellite phones and satellite messengers are the only way to communicate from the backcountry of Wrangell-St. Elias. We recommend bringing a satellite communication device\"; \"In an emergency, help will not be immediate\"."},{"name":"Bear spray, bought before you fly","source":"https://www.nps.gov/wrst/planyourvisit/backcountry.htm","accessed":"2026-10-03","si":["hiking","wildlife","expedition"],"booking_route":"affiliate referral to counterassault.com (AvantLink)","commission_status":"commissioned","commission":"affiliate","tier_absent_reason":"does-not-compete","commission_pct_low":8,"commission_pct_high":8,"commission_basis":"published","wells":["gear"],"draw_rank":34,"blurb":"NPS gear list: \"Bear spray - Note that this cannot be carried on planes or trains. Bear spray is permitted in the United States when crossing the land border by vehicle.\" Canada admits bear spray that carries USEPA on the label."},{"name":"Layers, trekking poles and bug spray - no gear store at the end of the road","source":"https://www.nps.gov/wrst/planyourvisit/backcountry.htm","accessed":"2026-10-03","si":["hiking","expedition","family"],"booking_route":"affiliate referral to rei.com (AvantLink)","commission_status":"commissioned","commission":"affiliate","tier_absent_reason":"does-not-compete","commission_pct_low":5,"commission_pct_high":5,"commission_basis":"published","wells":["gear"],"draw_rank":35,"blurb":"NPS: \"Plan on temps ranging from as warm as 75 F to as cold as 20 F, possibly in the same day!\"; it lists trekking poles, a tent (\"We strongly discourage bivy sacks\") and bug spray, and warns \"Do not count on acquiring or renting gear once you arrive at the park.\" St. Elias Alpine Guides confirms \"there is no gear store in McCarthy-Kennecott\"."},{"name":"Salmon & Bear Restaurant","source":"https://www.mccarthylodge.com/salmon-bear/","accessed":"2026-10-03","si":["culinary","romance","wine"],"booking_route":"reservation form on the own website","commission_status":"unknown","commission":"venue","tier_absent_reason":"does-not-compete","wells":["eat"],"draw_rank":36,"blurb":"McCarthy Lodge''s dining room: \"Wine Spectator Award Of Excellence each year Since 2020\"; \"just 10 intimate tables\" that \"sells out most busy summer nights\"; local ingredients \"like our wild caught Copper River Red Salmon\"; breakfast 7-9 am, dinner 5:30-9 pm."},{"name":"The Golden Saloon","source":"https://www.mccarthylodge.com/golden-saloon/","accessed":"2026-10-03","si":["entertainment","culinary","group"],"booking_route":"reservation form on the own website","commission_status":"unknown","commission":"venue","tier_absent_reason":"does-not-compete","wells":["eat"],"draw_rank":37,"blurb":"\"the center of evening entertainment in Wrangell St. Elias National Park\": buffalo burgers, wings, salads, wine flights and single malts; lunch and dinner noon to midnight. Alaska.org: \"Thursday evenings are open mic night in McCarthy\"."},{"name":"Roadside Potatohead","source":"https://www.alaska.org/detail/roadside-potatohead","accessed":"2026-10-03","si":["culinary","family"],"booking_route":"walk-in; phone 907-554-4440","commission_status":"unknown","commission":"venue","tier_absent_reason":"does-not-compete","wells":["eat"],"draw_rank":38,"blurb":"\"Quirky restaurant and espresso bar that serves great burritos and burgers on the outskirts of town\", Kennicott Road, McCarthy; 907-554-4440. No own site found; sourced to Alaska.org."},{"name":"Kennicott Glacier Lodge dining room","source":"https://www.alaska.org/detail/kennicott-glacier-lodge","accessed":"2026-10-03","si":["culinary","romance"],"booking_route":"phone 907-258-2350 (own site not read - HTTP 403)","commission_status":"unknown","commission":"venue","tier_absent_reason":"does-not-compete","wells":["eat"],"draw_rank":39,"blurb":"\"Breakfast is served as a buffet, lunch is served from a menu, and dinner at a single seating with a fixed menu. The ''wilderness gourmet'' dishes feature homemade soups, pastries, breads, and delicious desserts.\" Its sack lunches ride on the Wrangell Mountain Air day trips."},{"name":"Nummy''s Restaurant, Old Town Copper Center","source":"https://www.oldtowncoppercenter.com/","accessed":"2026-10-03","si":["culinary","family","senior"],"booking_route":"walk-in; (907) 822-3245","commission_status":"unknown","commission":"venue","tier_absent_reason":"does-not-compete","wells":["eat"],"draw_rank":40,"blurb":"\"In 1948, Nummy''s Restaurant began serving guests and quickly became a local favorite\"; \"hearty breakfasts, delicious lunches, and homestyle dinners in a relaxed Alaskan atmosphere.\""},{"name":"Two Rivers Restaurant, Copper River Princess","source":"https://www.princesslodges.com/princess-alaska-lodges/copper-river-lodge/","accessed":"2026-10-03","si":["culinary","senior","group"],"booking_route":"at the lodge; (907) 822-4000","commission_status":"unknown","commission":"venue","tier_absent_reason":"does-not-compete","wells":["eat"],"draw_rank":41,"blurb":"\"a two-level dining area with excellent mountain and valley views\"; \"our Two Rivers Restaurant provides excellent mountain and valley views alongside signature Alaska cuisine.\""},{"name":"Caribou Grill, Glennallen","source":"https://www.coppervalleychamber.com/where-to-eat","accessed":"2026-10-03","si":["culinary","motoring"],"booking_route":"phone (907) 822-4222","commission_status":"unknown","commission":"venue","tier_absent_reason":"does-not-compete","wells":["eat"],"draw_rank":42,"blurb":"Listed by the Copper Valley Chamber of Commerce - the body the NPS sends visitors to for area restaurants - under Glennallen: \"Caribou Grill - (907) 822-4222\". Nothing else about it is stated here."},{"name":"McCarthy","source":"https://www.mccarthylodge.com/","accessed":"2026-10-03","si":["culture","adventure","entertainment"],"booking_route":"none needed - a town","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":43,"blurb":"McCarthy Lodge calls it \"the Gateway Community to America''s largest national park\", with \"Open Mic Thursday''s, Live Music on Friday and Saturday nights.\" The NPS: the town \"is located 1/2 mile east\" of the Kennicott River Bridge, and \"There are no services available in McCarthy or Kennecott during the winter.\""},{"name":"McCarthy/Kennicott Museum","source":"https://www.alaska.org/destination/mccarthy/museums","accessed":"2026-10-03","si":["culture","family","senior"],"booking_route":"walk-in","commission_status":"unknown","commission":"venue","tier_absent_reason":"does-not-compete","wells":["activities"],"draw_rank":44,"blurb":"In the old railway depot: the copper rush \"between 1900 and 1938\", with \"pictures of railway construction - 196 miles of track from Cordova\". Sourced to Alaska.org; no own site found."},{"name":"Alaska Overlander rooftop-tent rigs","source":"https://www.alaska.org/destination/mccarthy/transportation","accessed":"2026-10-03","si":["overland","motoring","adventure"],"booking_route":"operator website (not read)","commission_status":"unknown","commission":"operator","tier_absent_reason":"does-not-compete","wells":["move","gear"],"draw_rank":45,"blurb":"Anchorage-based rentals that Alaska.org lists for the McCarthy Road: \"Complete with rooftop tents that set up in minutes, camp stove, and refrigerator\"; \"Season: April to Mid-October\", \"$299+ per day\", \"3+ days\". Alaska.org notes \"many Alaska car rental companies don''t allow their vehicles on non-paved roads\" and that this one does."}],"faq":[{"q":"Do you need tickets for Wrangell-St. Elias National Park and Preserve?","a":"No entrance ticket is needed. The NPS states: \"Wrangell-St. Elias National Park & Preserve is one of the National Park Service sites that does NOT charge an entrance fee.\" Private businesses may charge for parking and camping.","source":"https://www.nps.gov/wrst/planyourvisit/fees.htm","accessed":"2026-10-03"},{"q":"How big is Wrangell-St. Elias National Park?","a":"The NPS: \"It is the largest national park in the United States, with a size equal to six Yellowstone National Parks\", and the park and preserve contain \"approximately 13 million acres of public land in south-central Alaska.\"","source":"https://www.nps.gov/wrst/whats-so-special.htm","accessed":"2026-10-03"},{"q":"Can you drive to Wrangell-St. Elias National Park?","a":"Yes, on two State-owned gravel roads. \"The McCarthy Road is a narrow, gravel road that is 59 miles to the Kennicott River Bridge\"; \"There is no public vehicle access to Kennecott Mill town\", 5 miles beyond McCarthy, and \"most rental car companies do not allow their cars on this road.\" The Nabesna Road in the north is 42 miles of gravel with 3 stream crossings.","source":"https://www.nps.gov/wrst/planyourvisit/directions-mccarthy-rd-and-kennecott.htm","accessed":"2026-10-03"},{"q":"How far is Wrangell-St. Elias National Park from Anchorage?","a":"The NPS gives drive time, not mileage: \"Kennecott Mines National Historic Landmark is located approximately 8 hours (by car) from Anchorage\" - east on the Glenn Highway, south on the Richardson, east on the Edgerton, then 59 miles on the McCarthy Road.","source":"https://www.nps.gov/wrst/planyourvisit/directions-mccarthy-rd-and-kennecott.htm","accessed":"2026-10-03"},{"q":"When is the best time to visit Wrangell-St. Elias National Park?","a":"\"Summer is the primary season for visiting Wrangell-St. Elias from mid-May through mid-September. Winter arrives early to interior Alaska and by the end of September, available services and facilities are limited.\" Visitor centers and ranger stations close from October through April.","source":"https://www.nps.gov/wrst/planyourvisit/hours.htm","accessed":"2026-10-03"},{"q":"Can you camp in Wrangell-St. Elias National Park?","a":"Yes. Kendesnii Campground on the Nabesna Road \"is the only National Park Service campground in the park\": 10 sites, \"free and open year-round. No reservations are required and none are taken.\" Pullouts along the Nabesna Road and primitive NPS areas north of Kennecott are also available.","source":"https://www.nps.gov/wrst/planyourvisit/camping-along-the-nabesna-road.htm","accessed":"2026-10-03"},{"q":"Can you hunt in Wrangell-St. Elias National Park?","a":"Only in the preserve: \"Sport hunting is ONLY allowed within the NATIONAL PRESERVE and must be conducted in accordance with Alaska State Law. Subsistence hunting by qualified, local rural residents is authorized in both the park and preserve.\" An Alaska state licence is required from age 16.","source":"https://www.nps.gov/wrst/planyourvisit/hunting.htm","accessed":"2026-10-03"},{"q":"When was Wrangell-St. Elias National Park established?","a":"\"When the park and preserve were established by the U.S. Congress in 1980\". The NPS dates the act that created it, the Alaska National Interest Lands Conservation Act, to \"December 2, 1980\".","source":"https://www.nps.gov/wrst/learn/management/alaska-national-interest-lands-conservation-act.htm","accessed":"2026-10-03"},{"q":"What can you do at Wrangell-St. Elias National Park?","a":"At Kennecott the NPS lists day hikes - the Root Glacier, Jumbo Mine and Bonanza Mine trails - and the mill town tour by the concessioner, \"the only way to see inside the Concentration Mill building and the Leaching Plant\"; rangers give free talks, walks and a Junior Ranger programme in summer.","source":"https://www.nps.gov/wrst/planyourvisit/ranger-guided-tours.htm","accessed":"2026-10-03"}],"seo":{"meta_title":"Wrangell-St. Elias National Park: Kennecott & Root Glacier | TravelWell","meta_description":"The largest US national park: free entry, the Kennecott mill town, the Root Glacier, 59 miles of gravel McCarthy Road, and where to camp, stay and fly nearby.","slug":"wrangell-st-elias-national-park-alaska","primary_keyword":"Wrangell-St. Elias National Park","jsonld_type":"TouristDestination"},"hero":{"query":"Kennecott mill town Wrangell-St. Elias"}}'::jsonb, 106),
  ('katmai-alaska', '12A', 'Katmai National Park', 'United States', 'Brooks Falls brown bears and a volcanic valley', 'future', 'verified', 'mountainValley', 'Alaska', '{"wildlife","adventure","hiking","family","parks"}', '{"wild","remote","rugged","dramatic"}', '{}', null, null, '{"safety":{"posture":"book-freely","source":"https://www.gov.uk/foreign-travel-advice/usa","verified":"2026-10-08"},"jewels":[{"name":"Brooks Falls Platform and Brooks Falls Trail","source":"https://www.nps.gov/katm/planyourvisit/hiking-in-brooks-camp.htm","accessed":"2026-10-03","si":["wildlife","hiking","senior","family"],"booking_route":"none needed - no entrance fee; reached by floatplane or water taxi to Brooks Camp","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":1,"blurb":"\"This is the most popular trail in Katmai\": 1.2 mi, easy, wheelchair accessible; \"At the end of the trail, two raised platforms offer a bird''s eye view of bears fishing in the Brooks River. Bear viewing at the Falls is best during the July salmon run.\" The Falls Platform \"has a maximum capacity of 40 people\"; when full, rangers keep a waiting list and visitors may be asked to yield after one hour."},{"name":"Brooks Camp bear orientation (\"Bear School\")","source":"https://www.nps.gov/katm/planyourvisit/bear-safety-brooks-camp.htm","accessed":"2026-10-03","si":["wildlife","family","senior","group"],"booking_route":"none needed - given at the Brooks Camp Visitor Center on arrival","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":2,"blurb":"\"All visitors to Brooks Camp are required to begin their stay by attending a brief bear safety talk outlining park regulations.\" The rules: \"Remain at least 50 yards (46 meters) from any bear at all times\"; \"Never run from any bear\"; outside designated areas \"you cannot possess any food (even gum and candy) or beverages other than plain water\"; \"No clothing, bags, or other equipment can be left unattended at any time.\""},{"name":"Valley of Ten Thousand Smokes Tour","source":"https://www.nps.gov/katm/planyourvisit/rangerguided.htm","accessed":"2026-10-03","si":["adventure","hiking","group","senior"],"booking_route":"reservations at Brooks Lodge or through Katmailand, Inc. (1-800-544-0551)","commission_status":"unknown","commission":"operator","tier_absent_reason":"does-not-compete","wells":["activities"],"draw_rank":3,"blurb":"\"Not far from Brooks River, the largest volcanic eruption of the 20th century began on June 6, 1912.\" A day-long tour: 46-mile bus trip from the South Platform at 9 a.m. daily June 7 to September 17, lunch at the Robert F. Griggs Visitor Center, then an optional ranger-led hike of \"3.4 miles (5.4 km) round trip with 1000 feet (305 m) of elevation change\"; 7 hours. \"A fee is charged for this tour and reservations are required.\""},{"name":"Brooks Camp Campground","source":"https://www.nps.gov/katm/planyourvisit/campingbcdv.htm","accessed":"2026-10-03","si":["adventure","wildlife","senior","group"],"booking_route":"Recreation.gov or 1-877-444-6777","commission_status":"unknown","commission":"venue","tier_absent_reason":"not-established","wells":["stay"],"draw_rank":4,"blurb":"The only designated campground in Katmai, \"surrounded by an electric fence to deter bears from entering. The fence is bear-resistant, but not bear-proof.\" Three covered cooking shelters, a food and gear cache, fuel lockers, two vault toilets, potable water June 1 through September 18. $18 per person per night June 1-September 17, $10 in May and from September 18 to October 31; \"Group size is limited to 6\"; Access and Senior Pass holders 50% off (card holder only)."},{"name":"Brooks Lodge","source":"https://katmailand.com/rates-and-services/lodging/","accessed":"2026-10-03","si":["wildlife","family","group","romance"],"booking_route":"Katmailand lottery application (katmailand.com/brooks-lodge-lottery/), then a 50% deposit within 3 days","commission_status":"unknown","commission":"hotel","tier_absent_reason":"not-established","wells":["stay"],"draw_rank":5,"blurb":"\"The Only Full-Service Lodge Within Walking Distance of Brooks Falls\": sixteen rooms, \"each with private facilities\", each with \"2 sets of bunk beds that can accommodate up to four guests\". Rooms are allocated by lottery: \"Due to a high demand for overnight accommodations at Brooks, we operate a random lottery system\". 2026 season June 1-September 18."},{"name":"Katmai Air - Brooks Falls day tour from Anchorage","source":"https://katmaiair.com/bear-viewing/brooks-falls-day-tours/","accessed":"2026-10-03","si":["wildlife","adventure","senior","group"],"booking_route":"own website / Katmailand trip planners","commission_status":"unknown","commission":"operator","tier_absent_reason":"does-not-compete","wells":["activities","fly"],"draw_rank":6,"blurb":"\"A One Day Adventure to the World Famous Brooks Falls\": an \"approx. one hour and fifteen minute flight from Anchorage to King Salmon\", then a \"scenic 20-minute flight to Brooks Lodge\" by float plane; \"As a sister operation of Brooks Lodge, we''re proud to say we offer the most dependable day trip option to Brooks from Anchorage.\" June 1-September 18, 2026, $1489 per person including taxes and fees."},{"name":"Riffles and Lower River platforms","source":"https://www.nps.gov/katm/planyourvisit/bear-safety-brooks-camp.htm","accessed":"2026-10-03","si":["wildlife","senior","family"],"booking_route":"none needed - free at Brooks Camp","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":7,"blurb":"\"Five elevated viewing platforms at Brooks Camp are the only outdoor locations where bears can be safely observed at close distances.\" \"Neither the Riffles nor the three Lower River platforms have a time limit or capacity, and they can offer just as many rewarding bear viewing opportunities as Brooks Falls.\" On the platforms \"please keep your voices low and avoid cheering for bears\" and turn camera flash off."},{"name":"Katmai Water Taxi","source":"https://katmaiwatertaxi.com/","accessed":"2026-10-03","si":["adventure","wildlife","family"],"booking_route":"own website \"Book Your Ride\"","commission_status":"unknown","commission":"operator","tier_absent_reason":"does-not-compete","wells":["move"],"draw_rank":8,"blurb":"\"Your Gateway to Katmai\": a shuttle from your location in King Salmon to Lake Camp Boat Launch, then \"a 45-minute ride across Naknek Lake to Brooks Camp. The water taxi departs every odd hour from 7 AM to 5 PM. Upon arrival, our crew will guide you to the Visitor Center for the bear viewing orientation.\" $205 per one-way ticket, \"CUA fee included in the price\". Season ended; \"2027 bookings will be available in late November or December 2026.\""},{"name":"Smokey Bay Air - Katmai coast bear viewing from Homer","source":"https://smokeybayair.com/bear-viewing.html","accessed":"2026-10-03","si":["wildlife","adventure","family"],"booking_route":"own website Book Online (50% deposit or pay in full) or 907-531-0602","commission_status":"unknown","commission":"operator","tier_absent_reason":"does-not-compete","wells":["activities","fly"],"draw_rank":9,"blurb":"\"You will be accompanied by an experienced bush pilot who will be your bear viewing guide. Your plane will land on one of the National Park beaches, just a short walk away from the main attraction: brown bears in their natural habitat.\" About five hours - \"approximately one hour flight each way and three hours on the beach\"; \"a 280 pound limit per person and a 7 year old minimum age\"; $1145.00 per person (2 person min.), \"Price includes all National Park fees\". 2100 Kachemak Drive, Homer; 907-531-0602."},{"name":"Beluga Air - Katmai bear viewing from Homer","source":"https://www.belugaair.com/","accessed":"2026-10-03","si":["wildlife","hiking","group"],"booking_route":"email or phone (907) 235-8256","commission_status":"unknown","commission":"operator","tier_absent_reason":"does-not-compete","wells":["activities","fly"],"draw_rank":10,"blurb":"\"Since 1984\": \"Daily tours to Katmai National Park to view majestic Alaska Coastal Brown Bears in the wild.\" Its most popular tour: \"guided June hikes. We specialize in small-group tours led by expert naturalists\". Also McNeil River Bear Sanctuary transport for permit winners. info@belugaair.com, (907) 235-8256."},{"name":"Regal Air - Katmai bear viewing from Anchorage","source":"https://regal-air.com/alaska-shore-excursions/alaska-bear-viewing/katmai/","accessed":"2026-10-03","si":["wildlife","adventure","senior"],"booking_route":"own website \"Book Online\" or (907) 243-8535","commission_status":"unknown","commission":"operator","tier_absent_reason":"does-not-compete","wells":["activities","fly"],"draw_rank":11,"blurb":"\"Your Katmai Bear Viewing Adventure Begins when you depart Anchorage on one of our aircraft and head south along the Cook Inlet.\" By floatplane direct or twin-engine then floatplane, \"Both options take approximately 2.5 hours each way\", with \"(Approximately 4 hours)\" on the ground; after \"a quick bear orientation with one of the park rangers\", \"approximately 2 miles of easy walking\" to a platform. (907) 243-8535."},{"name":"Hallo Bay","source":"https://www.nps.gov/katm/planyourvisit/plyovicamp.htm","accessed":"2026-10-03","si":["wildlife","adventure","expedition"],"booking_route":"none needed in the park - reached by an authorized air taxi","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":12,"blurb":"\"Hallo Bay sits on the Pacific Coast of Katmai in the shadow of Kukak Volcano\"; \"Most commonly in June, bears roam about feasting on the nutrient dense sedges. Other wildlife in Halo Bay include wolves, foxes, and migratory birds.\" Reached by air taxi from King Salmon, Homer, Kodiak or Anchorage; \"The core meadow areas of Hallo Bay are closed to camping from April 1st through October 31st\"."},{"name":"Fishing the Brooks River and Katmai waters","source":"https://www.nps.gov/katm/planyourvisit/fishing.htm","accessed":"2026-10-03","si":["adventure","wildlife"],"booking_route":"none needed in the park - an Alaska sport fishing license (ADF&G); a Brooks River Corridor permit ($6 Recreation.gov booking fee) applies June 15-October 31","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":13,"blurb":"Rainbow trout, arctic char, dolly varden, arctic grayling, lake trout and five Pacific salmon species; \"An Alaska sport fishing license is required of all nonresidents 16 and over and most residents 16 to 59.\" At Brooks: \"Fishing must be terminated within 50 yards of any bear—no lures can remain in the water. When playing a fish, always be prepared to break your fishing line in case a bear approaches.\""},{"name":"Dumpling Mountain Trail","source":"https://www.nps.gov/katm/planyourvisit/hiking-in-brooks-camp.htm","accessed":"2026-10-03","si":["hiking","adventure"],"booking_route":"none needed - free park trail","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":14,"blurb":"1.5 mi, moderate to strenuous: \"climbs 800 feet (244 m) over 1.5 miles (2.4 km) to an overlook above Brooks Camp with expansive views of Naknek Lake, Brooks River, and Lake Brooks.\" The trailhead is in the campground; the summit (2440 ft) is \"another 2.5 mi (4 km) beyond the overlook\", through \"boreal forest, subalpine meadows, and alpine tundra.\""},{"name":"Grosvenor Lodge","source":"https://grosvenorlodge.com/","accessed":"2026-10-03","si":["adventure","family","group","wildlife"],"booking_route":"own website \"Reserve\"","commission_status":"unknown","commission":"hotel","tier_absent_reason":"not-established","wells":["stay","activities"],"draw_rank":15,"blurb":"Inside Katmai, \"at the confluence between two lakes, Lake Coville and Lake Grosvenor\"; \"Limited to no more than six guests at a time, Grosvenor provides the ''it feels like my own Alaska fishing lodge'' experience and is ideal for families, business associates, and/or a close group of fishing buddies.\" 3-, 4- and 7-night trips June 7-September 27, transfer days Wednesday and Sunday, flights not included."},{"name":"Kulik Lodge","source":"https://kuliklodge.com/","accessed":"2026-10-03","si":["adventure","wildlife"],"booking_route":"own website (rates not read)","commission_status":"unknown","commission":"hotel","tier_absent_reason":"not-established","wells":["stay","activities"],"draw_rank":16,"blurb":"\"Established in 1950, Kulik Lodge is recognized as Alaska''s first fly-out fishing lodge. Located in the heart of Katmai National Park and Preserve\". Listed by the NPS among lodges within the park."},{"name":"King Salmon Lodge","source":"https://kingsalmonlodge.com/","accessed":"2026-10-03","si":["family","wildlife","adventure"],"booking_route":"own website \"Book Your Reservations\"","commission_status":"unknown","commission":"hotel","tier_absent_reason":"not-established","wells":["stay"],"draw_rank":17,"blurb":"\"An Alaska Fishing Lodge where family and friends create memories of a lifetime\", \"ideally situated on the scenic Naknek River\"; it offers \"King Salmon Lodge Bear Tours\" and guided fishing. Natural Habitat Adventures describes it as \"rustic luxury on the edge of Katmai National Park\" with the Brooks River \"just 15 minutes away by floatplane\"."},{"name":"Brooks Lodge dining room","source":"https://katmailand.com/rates-and-services/meal-pricing/","accessed":"2026-10-03","si":["culinary","family","senior"],"booking_route":"purchased ahead through Katmailand or on-site","commission_status":"unknown","commission":"venue","tier_absent_reason":"does-not-compete","wells":["eat"],"draw_rank":18,"blurb":"\"Hearty Alaska fare is served buffet style each day for breakfast, lunch, and dinner in the lodge dining area. Cocktails are also available for purchase at the lodge bar each afternoon and evening.\" 2026 buffets: breakfast $25, lunch $45, dinner $52 (adult); child prices for ages 2-11; \"Senior discounts also available.\" Open to day visitors."},{"name":"The Katmai Trading Post","source":"https://katmailand.com/rates-and-services/trading-post/","accessed":"2026-10-03","si":["adventure","wildlife","family"],"booking_route":"on-site at Brooks Lodge","commission_status":"unknown","commission":"operator","tier_absent_reason":"does-not-compete","wells":["gear","shop"],"draw_rank":19,"blurb":"Katmailand''s store at Brooks: \"Canoes, kayaks, chest waders, Swarovski binoculars, and single burner stoves available for rent. Bear resistant containers, showers, and towels also available for campers\"; camp stove fuel (\"White gas, propane, & Jetboil fuel\"), insect repellent, fishing tackle and Alaska fishing licenses. 2026: chest waders $40/day, Swarovski binoculars $30/day, canoe or single kayak $50/day."},{"name":"Bear-resistant food container for the backcountry","source":"https://www.nps.gov/katm/planyourvisit/plyovicamp.htm","accessed":"2026-10-03","si":["hiking","adventure","expedition"],"booking_route":"affiliate referral to BearVault (AvantLink)","commission_status":"commissioned","commission":"affiliate","tier_absent_reason":"does-not-compete","commission_pct_low":8,"commission_pct_high":8,"commission_basis":"published","wells":["gear"],"draw_rank":20,"blurb":"NPS: \"The use of bear-resistant food containers (BRFCs) is mandatory in all backcountry areas. A limited supply of BRFCs are available to borrow free of charge at the visitor centers in King Salmon and Brooks Camp.\" It also recommends \"an electric fence when camping in the wilderness. As a reminder, electric fences are bear deterrents; they are not bear proof.\""},{"name":"Bear spray for Katmai''s trails and coast","source":"https://www.nps.gov/katm/planyourvisit/bear-safety-in-katmai.htm","accessed":"2026-10-03","si":["hiking","wildlife","adventure"],"booking_route":"affiliate referral to Counter Assault (AvantLink)","commission_status":"commissioned","commission":"affiliate","tier_absent_reason":"does-not-compete","commission_pct_low":8,"commission_pct_high":8,"commission_basis":"published","wells":["gear"],"draw_rank":21,"blurb":"NPS: \"Use your bear spray if you think the bear will attack. While most charges stop short of contact, there is no way to know and bear spray is a very effective tool to stop a charge.\" With a non-defensive bear: \"shout, make yourself look large and threatening, throw a rock towards the bear, and prepare to use your bear spray.\""},{"name":"Waterproof layers, hat and gloves","source":"https://www.nps.gov/katm/planyourvisit/weather.htm","accessed":"2026-10-03","si":["hiking","family","senior","wildlife"],"booking_route":"affiliate referral to rei.com (AvantLink)","commission_status":"commissioned","commission":"affiliate","tier_absent_reason":"does-not-compete","commission_pct_low":5,"commission_pct_high":5,"commission_basis":"published","wells":["gear"],"draw_rank":22,"blurb":"NPS: \"Bring high quality waterproof clothing: A reliably waterproof outer layer can keep you dry\"; \"Dress in layers: Start with a base layer to manage moisture... Wear an insulating layer such as a fleece jacket... Lastly, add a waterproof shell\"; \"Even during the relatively mild temperatures of summer, a warm hat and lightweight gloves can add significantly to your comfort level.\" On the trails: \"Bring a rain jacket and rain pants on every hike.\""},{"name":"Satellite communicator where there is no signal","source":"https://www.nps.gov/katm/planyourvisit/accessibility.htm","accessed":"2026-10-03","si":["adventure","hiking","expedition"],"booking_route":"affiliate referral to zoleo.com (AvantLink)","commission_status":"commissioned","commission":"affiliate","tier_absent_reason":"does-not-compete","commission_pct_low":10,"commission_pct_high":10,"commission_basis":"published","wells":["gear"],"draw_rank":23,"blurb":"NPS: \"WiFi and cellular service are may be limited or nonesistant in most of the park\" (sic), and Katmai \"is a remote park that cannot be accessed by car. There are few services in the park and preserve.\""},{"name":"Southwest Adventure Tours - 10-Day Ultimate Alaska Journey (TourRadar)","source":"https://www.tourradar.com/t/224703","accessed":"2026-10-03","si":["group","senior","wildlife","family"],"booking_route":"TourRadar (affiliate link)","commission_status":"commissioned","commission":"operator","tier_absent_reason":"does-not-compete","commission_pct_low":7,"commission_pct_high":7,"commission_basis":"published","wells":["activities"],"draw_rank":24,"blurb":"A 10-day guided trip from and to Anchorage, group size 4-10, ages 8+, with 2027 departures (June-August) listed; Day 3 of the itinerary: \"Scenic flight to Katmai National Park and Preserve or Lake Clark National Park and Preserve\" and a \"Guided hike in Katmai or Lake Clark National Park\" - Katmai is one of two named options, not a guarantee."},{"name":"Katmai Junior Ranger","source":"https://www.nps.gov/katm/learn/kidsyouth/juniorranger.htm","accessed":"2026-10-03","si":["family","wildlife"],"booking_route":"none needed - free book at the visitor centers or online","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":25,"blurb":"\"Junior Rangers are typically between the ages of 5 to 13, although people of all ages can participate. Get your free Junior Ranger book at the King Salmon and Brooks Camp visitor centers or download it here\"; a ranger checks the book and swears you in, or you can mail it to the park and a patch is mailed back."},{"name":"Cultural Walk and the Brooks River archaeology","source":"https://www.nps.gov/katm/planyourvisit/rangerguided.htm","accessed":"2026-10-03","si":["culture","senior","family"],"booking_route":"none needed - free ranger programme","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":26,"blurb":"\"With over 900 house depressions near the river, this is one of the most densely concentrated archeological areas in North America.\" The ranger-led walk \"follows an easy 1/4 mile trail to a reconstructed traditional Alutiiq/Sugpiaq home\"; 2 p.m. daily June 7 to September 17 from the Brooks Camp Visitor Center, 45 minutes to 1 hour."},{"name":"Brooks River bear cams (explore.org)","source":"https://www.nps.gov/katm/planyourvisit/bear-watching.htm","accessed":"2026-10-03","si":["wildlife","family","senior"],"booking_route":"none needed - free online","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":27,"blurb":"\"Now you can follow the lives of the brown bears of Brooks River anywhere with an internet connection. Katmai National Park and explore.org have partnered to bring the bears to you.\" Rangers also host live chats on the cams: \"Replays and recorded live chats can be found on explore.org''s YouTube channel.\""},{"name":"Fat Bear Week","source":"https://www.fatbearweek.org/","accessed":"2026-10-03","si":["wildlife","family"],"booking_route":"none needed - free online vote","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":28,"blurb":"\"Fat Bear Week is an annual tournament celebrating their success in preparation for winter hibernation\" - a single-elimination vote on the brown bears of Brooks River. \"Matchups are open for voting September 22 - 29 between 12 - 9 p.m. Eastern / 9 a.m. - 6 p.m. Pacific / 8 a.m. - 5 p.m. Alaska.\""},{"name":"Sea Hawk Air - floatplanes from Kodiak","source":"https://seahawkair.com/","accessed":"2026-10-03","si":["adventure","wildlife","group"],"booking_route":"custom air charter by contact (rates not read)","commission_status":"unknown","commission":"operator","tier_absent_reason":"does-not-compete","wells":["fly"],"draw_rank":29,"blurb":"Listed by the NPS among air taxis permitted in Katmai (Kodiak). In its own words: \"Sea Hawk Air provides safe, reliable floatplane service across Kodiak Island and the Alaska Peninsula\" for \"fishing, viewing bears and wildlife, or embarking on your own wilderness adventure\"; \"Since 1987\"; \"Our de Havilland Beaver seats up to six passengers and carries up to 1,200 lbs of gear.\""},{"name":"Katmai Wilderness Lodge","source":"https://katmai-wilderness.com/","accessed":"2026-10-03","si":["wildlife","romance","adventure"],"booking_route":"own website \"Reserve Now\" (2027 and 2028 only)","commission_status":"unknown","commission":"hotel","tier_absent_reason":"not-established","wells":["stay"],"draw_rank":30,"blurb":"🔴 CLOSED FOR 2026 by its own notice: \"KWL is closed for 2026\"; \"we look forward to welcoming guests back when we reopen on June 1, 2027.\" Listed by the NPS among lodges in the park; it calls itself \"the most remote bear lodge in Alaska\" offering \"a truly exclusive, small-group bear-viewin[g]\" stay."},{"name":"Crystal Creek Lodge","source":"https://crystalcreeklodge.com/","accessed":"2026-10-03","si":["adventure","wildlife"],"booking_route":"own website (rates not read)","commission_status":"unknown","commission":"hotel","tier_absent_reason":"not-established","wells":["stay","activities"],"draw_rank":31,"blurb":"King Salmon fly-fishing and adventure lodge \"Since 1988\": \"In our home waters of the Naknek River, anglers can reel in trout exceeding 30 inches in length\"; it names \"Katmai & Lake Clark National Park, Becharof & Alaska Peninsula National Wildlife Refuge, Aniakchak National Monument\" as within reach."},{"name":"King Salmon Lodge dining room and bar","source":"https://nathab.com/accommodations/king-salmon-lodge","accessed":"2026-10-03","si":["culinary","family"],"booking_route":"with a stay at King Salmon Lodge (kingsalmonlodge.com)","commission_status":"unknown","commission":"venue","tier_absent_reason":"does-not-compete","wells":["eat"],"draw_rank":32,"blurb":"\"Enjoy a drink at the cocktail bar, then indulge in a classically Alaskan meal of fresh-caught fish and locally grown produce in the riverside dining room, where large picture windows frame scenic views.\" (Natural Habitat Adventures'' accommodation page for the lodge.)"},{"name":"King Salmon Visitor Center","source":"https://www.nps.gov/katm/planyourvisit/nearbyattractions.htm","accessed":"2026-10-03","si":["family","senior","culture"],"booking_route":"none needed - free; hours change seasonally","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":33,"blurb":"\"Located just next door to the King Salmon Airport, the King Salmon Visitor Center is where you can find detailed information about the many federal public lands on the Alaska Peninsula as well as the Bristol Bay region.\" Exhibits, films and an Alaska Geographic bookstore; it also lends bear-resistant food containers and hands out the Junior Ranger book. The park headquarters is in King Salmon, \"about 290 miles southwest of Anchorage\" (NPS FAQ)."},{"name":"Evening Program, Brooks Camp Auditorium","source":"https://www.nps.gov/katm/planyourvisit/rangerguided.htm","accessed":"2026-10-03","si":["family","senior","culture"],"booking_route":"none needed - free ranger programme","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":34,"blurb":"\"Join a park ranger for an illustrated talk in the Brooks Camp Auditorium. Each night, this program offers unique perspectives, stories, and information on Katmai National Park.\" 8 p.m. daily June 7 to September 17, 45 minutes to 1 hour."},{"name":"Wilderness camping beyond Brooks Camp","source":"https://www.nps.gov/katm/planyourvisit/plyovicamp.htm","accessed":"2026-10-03","si":["adventure","hiking","expedition"],"booking_route":"none needed - no fee or permit","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":35,"blurb":"\"Wilderness camping is allowed everywhere in Katmai National Park outside of a 1.5-mile radius outside of Brooks Camp. There are no fees or permits required for wilderness camping.\" Via Dumpling Mountain (about 3 miles and 1,000 ft) or the Valley road (1.5 miles); \"Camping in one location for more than 14 consecutive days is prohibited.\""}],"faq":[{"q":"How do you get to Katmai National Park?","a":"By air or boat. The NPS: \"Most destinations are directly accessed via air taxi flights from Anchorage, Dillingham, Homer, King Salmon, Kodiak, and other nearby Alaska towns and villages. Regularly scheduled commercial flights to King Salmon (AKN) are available from Ted stevens Anchorage International Airport (ANC) via Alaska Airlines. Boats can access the Pacific coast of Katmai.\" Brooks Camp is reached by floatplane or by power boat from Naknek and King Salmon.","source":"https://www.nps.gov/katm/faqs.htm","accessed":"2026-10-03"},{"q":"Can you drive to Katmai National Park?","a":"No: \"Unlike most parks in the United States, there are no roads connecting the park to the rest of the state -- you cannot drive to Katmai, Brooks Camp, or King Salmon from Anchorage. Most visitors fly or boat to the park.\"","source":"https://www.nps.gov/katm/faqs.htm","accessed":"2026-10-03"},{"q":"When is the best time to see bears in Katmai National Park?","a":"At Brooks Camp, July and September: \"In July and September, bears are everywhere at Brooks Camp... During July, many bears can be seen fishing at Brooks Falls... In September, most bears are seen at the mouth of the Brooks River. Please note that in June and August few bears, if any, can be seen at Brooks Camp.\" On the coast at Hallo Bay, bears feed on sedges \"Most commonly in June\".","source":"https://www.nps.gov/katm/faqs.htm","accessed":"2026-10-03"},{"q":"Is there an entrance fee for Katmai National Park?","a":"No: \"An entrance pass is not required to access Katmai National Park & Preserve.\" The Brooks Camp Campground ($18 per person per night in season) and a Brooks River Corridor permit ($6 Recreation.gov booking fee) carry their own fees.","source":"https://www.nps.gov/katm/planyourvisit/fees.htm","accessed":"2026-10-03"},{"q":"Can you camp in Katmai National Park?","a":"Yes, two ways: \"Camping in a designated campground can only occur at Brooks Camp Campground\" (reserved on Recreation.gov), and \"Wilderness camping is allowed everywhere in Katmai National Park outside of a 1.5-mile radius outside of Brooks Camp. There are no fees or permits required for wilderness camping.\" Bear-resistant food containers are mandatory in all backcountry areas.","source":"https://www.nps.gov/katm/planyourvisit/plyovicamp.htm","accessed":"2026-10-03"},{"q":"Where can you stay in Katmai National Park?","a":"At Brooks Camp: \"You can stay at Brooks Lodge or camp in the Brooks Camp Campground. For information on rates and reservations for Brooks Lodge, visit Katmailand.com... Campground reservations can be made on recreation.gov.\" Brooks Lodge rooms are allocated by Katmailand''s lottery.","source":"https://www.nps.gov/katm/faqs.htm","accessed":"2026-10-03"},{"q":"What is the weather like in Katmai National Park?","a":"\"On average, wet and cool conditions predominate in spring, summer, and fall. Summer temperatures range from 30˚ to 80˚ Fahrenheit (-1˚ to 27˚ Celsius). Winters are drier and colder.\" \"Strong winds are common all year.\" The NPS advises waterproof clothing, layers, and a warm hat and lightweight gloves even in summer.","source":"https://www.nps.gov/katm/planyourvisit/weather.htm","accessed":"2026-10-03"},{"q":"Can you fish in Katmai National Park?","a":"Yes. \"An Alaska sport fishing license is required of all nonresidents 16 and over and most residents 16 to 59.\" \"Special federal regulations, in addition to state regulations, exist for the Brooks River.\" Near bears, \"Fishing must be terminated within 50 yards of any bear\".","source":"https://www.nps.gov/katm/planyourvisit/fishing.htm","accessed":"2026-10-03"},{"q":"Where can you watch the Katmai bear cam?","a":"Online, through explore.org: \"Now you can follow the lives of the brown bears of Brooks River anywhere with an internet connection. Katmai National Park and explore.org have partnered to bring the bears to you.\"","source":"https://www.nps.gov/katm/planyourvisit/bear-watching.htm","accessed":"2026-10-03"},{"q":"When is Fat Bear Week at Katmai National Park?","a":"\"Fat Bear Week is an annual tournament celebrating their success in preparation for winter hibernation.\" \"Matchups are open for voting September 22 - 29 between 12 - 9 p.m. Eastern / 9 a.m. - 6 p.m. Pacific / 8 a.m. - 5 p.m. Alaska.\"","source":"https://www.fatbearweek.org/","accessed":"2026-10-03"}],"seo":{"meta_title":"Katmai National Park: Brooks Falls Bears & How to Get There | TravelWell","meta_description":"No roads, free entry: fly in to Brooks Falls bears in July and September, the Valley of Ten Thousand Smokes, Brooks Lodge by lottery and the NPS campground.","slug":"katmai-national-park-alaska","primary_keyword":"Katmai National Park","jsonld_type":"TouristDestination"},"hero":{"query":"Brooks Falls brown bears Katmai"}}'::jsonb, 107)
